INSERT INTO m254_ver VALUES
(0,0,1,$m254$قانون رقم 148 لسنة 2019
بإصدار قانون التأمينات الاجتماعية والمعاشات
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m254$,'d06290a1446e2ab53f7fa3f3a8362de0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(1,-1,1,$m254$يعمل فى شأن نظام التأمينات الاجتماعية والمعاشات بأحكام القانون المرافق .$m254$,'1865a92c5e38aedd6d41dd46fade9da8',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(2,-1,1,$m254$تتولى الهيئة القومية للتأمين الاجتماعى صرف الحقوق المقررة بالتشريعات المتعلقة بالتأمين الاجتماعى والتى كانت تتولى الجهات الإدارية صرفها ، وذلك على حساب الخزانة العامة ، وتتضمن اللائحة التنفيذية للقانون المرافق القواعد والإجراءات المنفذة لأحكام هذه المادة .$m254$,'3f8b103b8e5ba984385d0ad97fb7f4d4',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(3,-1,1,$m254$لا يترتب على تطبيق أحكام القانون المرافق الإخلال بما تتضمنه أحكام القوانين المنظمة للشئون الوظيفية للمعاملين بالكادرات الخاصة ، ويستمر العمل بالمزايا المقررة فى هذه القوانين والأنظمة الوظيفية وتتحمل الخزانة العامة فروق التكلفة المترتبة على ذلك طبقا لأحكام القانون المرافق .$m254$,'36376bc2a450f02da597f1f46e92c9b6',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(4,-1,1,$m254$يستمر العمل باللوائح والقرارات الصادرة تنفيذا لأحكام القوانين المتعلقة بالتأمين الاجتماعى ، بما لا يتعارض مع أحكام القانون المرافق وذلك إلى حين صدور اللائحة التنفيذية له .$m254$,'286243a78f0333a0edcb4cf037a15198',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(5,-1,1,$m254$يصدر رئيس مجلس الوزراء اللائحة التنفيذية للقانون المرافق خلال ستة أشهر من تاريخ صدور هذا القانون .$m254$,'4580a918c769522eabf18be3cdd7cca0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(6,-1,1,$m254$يلغى كل حكم يخالف أحكام هذا القانون بالنسبة للمعاملين بأحكامه .$m254$,'47daab439b562d08be4eaf50fb7725f0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(7,-1,1,$m254$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به اعتبارا من 1/1/2020 ، فيما عدا المواد ( 111 و112 و113 و114 ) فيعمل بها من اليوم التالى لتاريخ نشره .$m254$,'d8a4f4b1bf1534a45ce4c73a73eefb4f',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(1,0,1,$m254$فى تطبيق أحكام هذا القانون ، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
1 - المؤمن عليه : كل من تسرى عليه أحكام هذا القانون حتى تحقق واقعة استحقاق حقوقه التأمينية عن مدة اشتراكه فى تأمين الشيخوخة والعجز والوفاة .
2 - صاحب العمل : كل شخص طبيعى أو اعتبارى يستخدم عاملا أو أكثر من الخاضعين لأحكام البند ( أولا ) من المادة ( 2 ) من هذا القانون .
3 - الهيئة : الهيئة القومية للتأمين الاجتماعى .
4 - مجلس الإدارة : مجلس إدارة الهيئة القومية للتأمين الاجتماعى .
5 - لجنة الخبراء : لجنة تتكون من خبراء اكتواريين يزاولون أعمالهم وفقا لأحكام القانون رقم 10 لسنة 1981 فى شأن الإشراف والرقابة على هيئات التأمين ، وخبراء ماليين وتأمينيين يرشحهم مجلس الإدارة ، ويكون من بينهم ممثل عن وزارة المالية متخصص فى أعمال اللجنة يرشحه وزير المالية .
6 - معدل التضخم : الرقم القياسى لأسعار المستهلكين على مستوى الجمهورية الصادر عن الجهاز المركزى للتعبئة العامة والإحصاء ، ويحدد بالمتوسط الشهرى لمعدلات التضخم عن مدة سنة سابقة ، ويحدد فى شهر يوليو من كل عام ، ويصدر به قرار من رئيس الهيئة .
7 - سعر الخصم الاكتوارى : معدل التضخم مضافا إليه نسبة ( 1٪ ) .
8 - أجر الاشتراك : المقابل النقدى الذى يحصل عليه المؤمن عليه من الفئات المشار إليها بالبند أولا من المادة ( 2 ) من هذا القانون من جهة عمله الأصلية لقاء عمله الأصلى .
وتحدد عناصر أجر الاشتراك على النحو الآتى :
1 - الأجر الوظيفى .
2 - الأجر الأساسى .
3 - الأجر المكمل .
4 - الحوافز .
5 - العمولات .
6 - الوهبة ، متى توافرت فى شأنها الشروط الآتية :
( أ ) أن يكون قد جرى العرف على أن يدفعها عملاء المنشأة على أساس نسبة مئوية محددة مقدما من المبالغ المستحقة على العملاء .
( ب ) أن يكون لها صندوق مشترك فى المنشأة توضع فيه حصيلتها لتوزيعها بين العمال .
( ج ) أن تكون هناك قواعد متفق عليه بين رب العمل والعمال تحدد بموجبها كيفية توزيعها عليهم .
7 - البدلات ، فيما عدا البدلات التالية فلا تعتبر جزءا من أجر الاشتراك :
( أ ) بدل الانتقال وبدل السفر وبدل حضور الجلسات وغيرها من البدلات التى تصرف للمؤمن عليه مقابل ما يتكلفه من أعباء تقتضيها أعمال وظيفته ويستثنى من ذلك بدل التمثيل .
( ب ) بدل السكن وبدل الملبس وبدل السيارة وغيرها من البدلات التى تصرف مقابل مزايا عينية .
( ج ) البدلات التى تستحق نتيجة ندب المؤمن عليه بعض الوقت داخل جهة عمله الأصلية أو خارجها .
( د ) البدلات التى تستحق للمؤمن عليه لمواجهة أعباء المعيشة خارج البلاد .
8 - الأجور الإضافية .
9 - التعويض عن الجهود غير العادية .
10 - إعانة غلاء المعيشة .
11 - العلاوات الاجتماعية .
12 - العلاوات الاجتماعية الإضافية .
13 - المنح الجماعية .
14 - المكافآت الجماعية .
15 - ما زاد عن الحد الأقصى للأجر الأساسى .
16 - العلاوات الخاصة التى لم يتم ضمها للأجر الأساسى .
وتحدد اللائحة التنفيذية لهذا القانون الحدين الأدنى والأقصى لأجر الاشتراك .
9 - دخل الاشتراك : الدخل الذى يختاره المؤمن عليه من الفئات المنصوص عليها فى البندين ثانيا وثالثا من المادة ( 2 ) من هذا القانون للاشتراك عنه ، بما لا يقل عن الحد الأدنى لأجر الاشتراك ولا يزيد على الحد الأقصى له ، وتحدد اللائحة التنفيذية لهذا القانون جدول دخل الاشتراك والشروط الأخرى التى يجب مراعاتها عند تحديد دخل الاشتراك وكذلك قواعد وإجراءات تعديله .
10 - سن الشيخوخة : سن الستين بالنسبة للبنود أولا وثالثا من المادة ( 2 ) من هذا القانون ، وسن الخامسة والستين بالنسبة للمؤمن عليهم المشار إليهم بالبند ثانيا ورابعا ، وذلك مع مراعاة حكم المادة ( 41 ) من هذا القانون .
11 - صاحب المعاش : من تحققت فى شأنه واقعة استحقاق المعاش عن نفسه فى تأمين الشيخوخة والعجز والوفاة .
12 - العجز الكلى المستديم : كل عجز من شأنه أن يحول كليا وبصفة مستديمة بين المؤمن عليه وبين مزاولته مهنته الأصلية أو أى مهنة أو نشاط يتكسب منه ، ويعتبر فى حكم ذلك حالات الأمراض العقلية ، وكذلك الأمراض المزمنة والمستعصية التى يصدر بها قرار من رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى .
13 - العجز الجزئى المستديم : كل عجز بخلاف حالات العجز الكلى من شأنه أن يحول بصفة مستديمة بين المؤمن عليه الخاضع للبند أولا من المادة ( 2 ) من هذا القانون وبين عمله الأصلى .
14 - دفعة الحياة : القيمة الحالية لدفعة المعاش للجنيه الواحد التى سوف يحصل عليها صاحب المعاش عند تقاعده ولمدى الحياة والمستحقين .
15 - إصابة العمل : الإصابة بأحد الأمراض المهنية المبينة بالجدول رقم ( 1 ) المرافق لهذا القانون ، أو الإصابة نتيجة حادث وقع أثناء تأدية العمل أو بسببه ، ويعتبر فى حكم ذلك كل حادث يقع للمؤمن عليه خلال فترة ذهابه لمباشرة عمله أو عودته منه بشرط أن يكون الذهاب أو الإياب دون تخلف أو توقف أو انحراف عن الطريق الطبيعى ، وتعتبر الإصابة الناتجة عن الإجهاد أو الإرهاق من العمل إصابة عمل متى توافرت فيها الشروط والقواعد التى تحددها اللائحة التنفيذية لهذا القانون بالتنسيق مع رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى .
16 - المصاب : من أصيب بإصابة عمل .
17 - المريض : من أصيب بمرض أو حادث غير إصابة العمل .
18 - العاجز عن الكسب : كل شخص مصاب بعجز يحول كليا بينه وبين العمل أو ينقص قدرته على العمل بواقع ( 50٪ ) على الأقل ، ويشترط أن يكون هذا العجز ناشئا بالميلاد أو نتيجة حادث أو مرض يصاب به الشخص قبل سن الستين .$m254$,'658e57da4d743c68f5745fa1f4a29afa',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(2,0,1,$m254$تسرى أحكام هذا القانون على الفئات الآتية :
أولا - العاملين لدى الغير :
1 - العاملين المدنيين بالجهاز الإدارى للدولة والهيئات العامة والمؤسسات العامة والوحدات الاقتصادية التابعة لأى من هذه الجهات .
2 - العاملين بوحدات القطاع العام وقطاع الأعمال العام وغيرها من الوحدات الاقتصادية التابعة لها ، بما فى ذلك رؤساء وأعضاء مجالس الإدارة المنتدبون فى شركات قطاع الأعمال العام .
كما تسرى أحكام هذا القانون على العاملين المؤقتين والعرضيين والموسميين بالجهات المنصوص عليها فى البند ( 1 ، 2 ) .
3 - العاملين بالقطاع الخاص الخاضعين لأحكام قانون العمل ، مع مراعاة أن تكون علاقة العمل التى تربط المؤمن عليه بصاحب العمل منتظمة ، ويستثنى من هذا الشرط عمال المقاولات وعمال الشحن والتفريغ وعمال الصيد وعمال النقل البرى ، وتحدد اللائحة التنفيذية لهذا القانون القواعد والشروط اللازم توافرها لاعتبار علاقة العمل منتظمة .
4 - المشتغلين بالأعمال المتعلقة بخدمة المنازل ، فيما عدا من يعمل منهم داخل المنازل وتحددهم اللائحة التنفيذية لهذا القانون .
5 - أفراد أسرة صاحب العمل الذين يعملون لديه ويعولهم فعلا ، بشرط توافر الشروط المنصوص عليها فى البند ( 3 ) .
ويشترط فى البنود ( 3 ، 4 ، 5 ) ألا تقل سن المؤمن عليه عن الثامنة عشرة .
وفى حالة التحاق المؤمن عليه بالعمل لدى أكثر من صاحب عمل فلا يعتد ضمن مدة اشتراكه إلا بمدة عمله لدى صاحب عمل واحد ، وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام تحديد مدة العمل الخاضعة لهذا القانون .
ثانيا - أصحاب الأعمال ، ومن فى حكمهم :
1 - الأفراد الذين يزاولون لحساب أنفسهم نشاطا تجاريا أو صناعيا أو زراعيا ، والحرفيين وغيرهم ممن يؤدون نشاطا أو خدمات لحساب أنفسهم ، ويشترط لخضوعهم أن تنظم أنشطتهم قوانين خاصة ، أو يلزم لمزاولتها الحصول على ترخيص بذلك من الجهة الإدارية المختصة .
2 - الشركاء المتضامنين فى شركات الأشخاص وشركات التوصية بالأسهم ، ورؤساء وأعضاء مجالس الإدارة والأعضاء المنتدبين فى الشركات المساهمة بالقطاع الخاص ، والمديرين فى الشركات ذات المسئولية المحدودة .
3 - ملاك شركات الشخص الواحد .
4 - المشتغلين بالمهن الحرة ، وأعضاء النقابات المهنية ، ويحدد تاريخ بدء انتفاع كل مهنة بأحكام هذا القانون بقرار من رئيس الهيئة .
5 - الأعضاء المنتجين فى الجمعيات التعاونية الإنتاجية الذين يشتغلون لحساب أنفسهم .
6 - مالكى الأراضى الزراعية التى تبلغ مساحتها فدانا فأكثر .
7 - حائزى الأراضى الزراعية التى تبلغ مساحتها فدانا فأكثر ، سواء كانوا ملاكا أو مستأجرين بالأجرة أو بالمزارعة أو كليهما معا .
8 - ملاك العقارات المبنية الذين لا يقل نصيب كل منهم من الدخل السنوى عن الحد الأدنى لأجر الاشتراك ، وتحدد اللائحة التنفيذية لهذا القانون شروط وقواعد الخضوع لهذا البند .
9 - أصحاب وسائل النقل الآلية للأشخاص أو البضائع ، بما فى ذلك وسائل النقل البرى والنهرى والبحرى والجوى .
10 - الوكلاء التجاريين .
11 - أصحاب مراكب الصيد الميكانيكية أو الشراعية .
12 - المأذونين الشرعيين والموثقين المنتدبين من غير الرهبان .
13 - العمد والمشايخ .
14 - المرشدين والأدلاء السياحيين وقصاصى الأثر .
15 - الأدباء والفنانين .
16 - ورثة أصحاب الأعمال فى المنشآت الفردية ، وتحدد اللائحة التنفيذية لهذا القانون شروط الخضوع .
17 - أصحاب الصناعات المنزلية والبيئية والريفية والأسرية .
ويشترط للانتفاع بأحكام هذا البند عدم الخضوع لأحكام هذا القانون طبقا للبند أولا من هذه المادة ، وألا تقل سن المؤمن عليه عن الحادية والعشرين .
ويجوز بقرار من رئيس الهيئة إضافة فئات أخرى وفقا لهذا البند ، على أن يحدد القرار تاريخ بدء الانتفاع والشروط الأخرى للانتفاع بأحكام هذا القانون .
ثالثا - العاملين المصريين فى الخارج :
1 - العاملين المرتبطين بعقود عمل شخصية .
2 - العاملين لحساب أنفسهم .
3 - المهاجرين من الفئات المشار إليها فى البنود السابقة المحتفظ لهم بالجنسية المصرية .
4 - العاملين البحريين الذين يعملون على سفن بحرية ترفع علم دولة أجنبية وذلك خلال فترة سريان جواز السفر البحرى .
ويعتبر العامل المصرى بوحدات المنظمات الدولية والإقليمية والسفارات الأجنبية داخل جمهورية مصر العربية المرتبط بعقد عمل شخصى ولا يسرى فى شأنه قانون العمل فى حكم العامل المصرى بالخارج .
ويشترط للانتفاع بأحكام هذا البند ما يأتى :
ألا يكون خاضعا لأحكام البندين أولا وثانيا من هذه المادة .
ألا يقل سن المؤمن عليه عن الثامنة عشرة .
رابعا - العمالة غير المنتظمة :
1 - ملاك العقارات المبنية الذين يقل نصيب كل منهم من الدخل السنوى عن فئة الحد الأدنى لأجر الاشتراك .
2 - عمال التراحيل .
3 - صغار المشتغلين لحساب أنفسهم كالباعة الجائلين ومنادى السيارات وموزعى الصحف وماسحى الأحذية المتجولين وغيرهم من الفئات المماثلة والحرفيين .
4 - خدم المنازل ومن فى حكمهم الذين يعملون داخل المنازل .
5 - محفظى القرآن الكريم وقرائه .
6 - المرتلين والقيمة وغيرهم من خدام الكنيسة .
7 - ورثة أصحاب الأعمال فى المنشآت الفردية غير الخاضعين للبند ثانيا متى توافرت فى شأنهم الشروط الآتية :
( أ ) ألا يعمل بالمنشأة عمال وقت وفاة مورثها .
( ب ) أن يكون نصيب الوارث من الدخل السنوى للمنشأة المتخذ أساسا لربط الضريبة على الدخل أقل من الحد الأدنى لأجر الاشتراك .
( ج ) ألا يكون قائما بإدارة المنشأة .
8 - العاملين المؤقتين فى الزراعة سواء فى الحقول والحدائق والبساتين أو فى مشروعات تربية الماشية أو الحيوانات الصغيرة أو الدواجن أو فى المناحل أو فى أراضى الاستصلاح والاستزراع ، ويقصد بالعاملين المؤقتين من تقل مدة عمالتهم لدى صاحب العمل عن ستة أشهر متصلة أو كان العمل الذى يزاولونه لا يدخل بطبيعته فيما يزاوله صاحب العمل من نشاط .
9 - حائزى الأراضى الزراعية الذين تقل مساحة حيازتهم عن فدان سواء كانوا ملاكا أو مستأجرين بالأجرة أو بالمزارعة .
10 - ملاك الأراضى الزراعية غير الحائزين لها ممن تقل ملكيتهم عن فدان .
ويشترط للانتفاع بأحكام هذا البند عدم الخضوع لأحكام هذا القانون طبقا للبنود أولا وثانيا وثالثا ، وألا يقل سن المؤمن عليه عن الثامنة عشرة .
ويجوز بقرار من رئيس الهيئة إضافة فئات أخرى وفقا لهذا البند ، على أن يحدد القرار تاريخ بدء الانتفاع والشروط الأخرى للانتفاع بأحكام هذا القانون وقواعد وإجراءات سداد الاشتراكات .
وتحدد اللائحة التنفيذية لهذا القانون شروط وضوابط خضوع كل فئة من هذه الفئات لأحكام هذه المادة .$m254$,'5fa5cbd92790cbe3fc993c864822e418',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(3,0,1,$m254$يشمل نظام التأمينات الاجتماعية التأمينات الآتية :
1 - تأمين الشيخوخة والعجز والوفاة .
2 - تأمين إصابات العمل .
3 - تأمين المرض .
4 - تأمين البطالة .$m254$,'2ead044e429ebb78438343f2791318ea',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(4,0,1,$m254$يكون التأمين وفقا لأحكام هذا القانون إلزاميا ، فيما عدا الفئات المنصوص عليها بالبند ثالثا من المادة ( 2 ) من هذا القانون فيكون خضوعهم اختياريا ، ولرئيس مجلس الوزراء بناء على عرض رئيس الهيئة إصدار قرار بإلزامية التأمين لهذه الفئة بالدول التى لا يتم التأمين فيها على العمالة المصرية .
ولا يجوز تحميل المؤمن عليه أى نصيب فى نفقات التأمين إلا فيما يرد به نص خاص .
ولا يجوز حرمان المؤمن عليه أو صاحب المعاش من الحقوق التأمينية المستحقة كليا أو جزئيا لأى سبب من الأسباب .$m254$,'c61ee79161b86c05e150de3462f3c0af',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(5,0,1,$m254$ينشأ صندوق للتأمينات المنصوص عليها فى المادة ( 3 ) من هذا القانون ، ويخصص لكل نوع من أنواع التأمينات المشار إليها حساب خاص فى هذا الصندوق .$m254$,'8daaf74e64b4ac334839621d7b6a93b3',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(6,0,1,$m254$تتكون أموال كل حساب من الحسابات المشار إليها بالمادة السابقة من الموارد الآتية :
1 - الاشتراكات التى يؤديها أصحاب الأعمال عن العاملين لديهم ، سواء الحصة التى يلتزم بها صاحب العمل أو الحصة التى يلتزم بها المؤمن عليه .
2 - الاشتراكات التى يؤديها المؤمن عليهم .
3 - المبالغ الإضافية المستحقة .
4 - المبالغ التى تؤديها الخزانة العامة للدولة وفقا لأحكام هذا القانون .
5 - حصيلة استثمار أموال الحساب .
6 - حصيلة المقابل النقدى للخدمات المقررة بموجب هذا القانون .
7 - حصيلة الغرامات المقضى بها عن مخالفة أحكام هذا القانون .
8 - الإعانات والتبرعات والهبات التى يقرر مجلس الإدارة قبولها .
9 - الموارد الأخرى الناتجة عن نشاط الصندوق .
ويتولى مجلس الإدارة تحديد ما يخصص لكل حساب من حصيلة الموارد المنصوص عليها فى البنود أرقام ( 6 ، 7 ، 8 ، 9 ) من هذه المادة .$m254$,'e0814423a3ebfe86a9c77318dbd80807',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(7,0,1,$m254$يتم فحص المركز المالى للحسابات المشار إليها بالمادة ( 5 ) من هذا القانون مرة واحدة على الأقل كل ثلاث سنوات بواسطة لجنة الخبراء فى تقرير إكتوارى يقدم إلى مجلس النواب .
ويقيم التقرير الإكتوارى ما إذا كانت معدلات الاشتراكات المطبقة فى تاريخ الفحص الإكتوارى وأى زيادات لاحقة ينص عليها القانون كافية لمقابلة الالتزامات للمزايا الممنوحة فى كل حساب وذلك على أساس مبادئ التمويل التالية :
أولا - مزايا تأمين الشيخوخة والعجز والوفاة :
فيتم الفحص على أساس تمويل جزئى مع الاحتفاظ باحتياطى إيجابى لمدة لا تقل عن 50 سنة بعد تاريخ الفحص الاكتوارى .
ثانيا - مزايا تأمين إصابة العمل المالية :
فيتم الفحص على أساس نظام تمويل الموازنة السنوية بالنسبة للمزايا قصيرة الأجل مع تكوين احتياطى طوارئ ، ونظام التمويل الكامل بالنسبة إلى المزايا طويلة الأجل .
ثالثا - مزايا تأمين المرض المالية ومزايا تأمين البطالة :
فيتم الفحص على أساس نظام الموازنة السنوية مع تكوين احتياطى طوارئ .
ويكون رصيد الاحتياطى الذى يخص كل حساب من حسابات المزايا على النحو الآتى :
مزايا تأمين الشيخوخة والعجز والوفاة :
مساو لإجمالى الاحتياطيات للصندوق المشار إليه بالمادة ( 5 ) من هذا القانون مطروحا منه الاحتياطى المحتسب لفروع مزايا تأمين إصابات العمل والمرض والبطالة .
مزايا تأمين إصابة العمل :
تكوين احتياطى طوارئ يساوى اثنى عشر ( 12 ) شهرا من نفقات الاستحقاقات قصيرة الأجل المتوقعة بالإضافة إلى تكوين احتياطى فنى يساوى القيمة الاكتوارية الحالية للاستحقاقات طويلة الأجل المدفوعة فى تاريخ التقييم الاكتوارى .
المزايا المالية لتأمين المرض :
تكوين احتياطى طوارئ يساوى اثنى عشر ( 12 ) شهرا من النفقات المتوقعة .
مزايا البطالة :
تكوين احتياطى طوارئ يساوى أربعة وعشرين ( 24 ) شهرا من النفقات المتوقعة .
وفى حالة عدم كفاية معدلات الاشتراك المطبقة فى تاريخ الفحص الاكتوارى وأى زيادات لاحقة ينص عليها القانون لمقابلة مزايا كل فرع من فروع المزايا يوصى التقرير الاكتوارى بمعدلات الاشتراك المناسبة التى يتعين تطبيقها فى السنوات اللاحقة .
وفى حالة عجز التدفقات النقدية للهيئة عن الوفاء بالتزاماتها النقدية المقررة قانونا لأصحاب الشأن ، تلتزم الخزانة العامة بتدبير تلك المبالغ اللازمة ، على أن تلتزم الهيئة بسدادها للخزانة العامة وفقا للقواعد والإجراءات التى يتم الاتفاق عليها بين رئيس الهيئة ووزير المالية وموافقة مجلس الوزراء .
وتحدد اللائحة التنفيذية لهذا القانون المعايير وأسس حساب الفروض الاكتوارية التى يتم على أساسها إعداد التقييم الاكتوارى لحسابات التأمين الاجتماعى .$m254$,'2cd4d558925389f58115f453b6e196e7',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(8,0,1,$m254$تتولى الهيئة إدارة الصناديق المشار إليها بالمواد أرقام ( 5 ) ، ( 14 ) من هذا القانون .
ويكون للهيئة الشخصية الاعتبارية ، والموازنة المستقلة التى يتم إعدادها على نمط الوحدات الاقتصادية ، كما يكون لها الاستقلال الفنى والمالى والإدارى ، وتتبع الوزير المختص بالتأمينات الاجتماعية .
ويصدر بتنظيم أجهزة الهيئة وقطاعاتها وتحديد اختصاصاتها وتسيير العمل بها قرار من رئيس الهيئة .$m254$,'5f9ac50def8b29d5d18606ac9f156743',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(9,0,1,$m254$يتولى إدارة الهيئة مجلس إدارة ، يشكل على النحو الآتى :
1 - رئيس متفرغ من ذوى الخبرة فى مجال المعاشات والتأمين الاجتماعى .
2 - نواب متفرغين لرئيس الهيئة من ذوى الخبرة فى مجال التأمين الاجتماعى أو نظم التأمين ، على أن يكون أحدهم ذا خبرة فى مجال الاستثمار .
3 - رئيس إدارة الفتوى المختصة بمجلس الدولة .
4 - رئيس مجلس إدارة الهيئة العامة للتأمين الصحى الشامل .
5 - رئيس قطاع بوزارة المالية ، يختاره وزير المالية .
6 - رئيس الاتحاد العام لنقابات عمال مصر ، أو من يفوضه .
7 - رئيس اتحاد الغرف التجارية ، أو من يفوضه .
8 - رئيس اتحاد الصناعات المصرية ، أو من يفوضه .
9 - ممثلين اثنين عن أصحاب المعاشات ، يختارهما مجلس الإدارة .
10 - ثلاثة من الخبراء المستقلين فى مجالات عمل الهيئة ، يختارهم مجلس الإدارة .
ويصدر بتشكيل المجلس قرار من رئيس الجمهورية لمدة أربع سنوات .
ويكون التجديد لرئيس الهيئة ونوابه وممثلى أصحاب المعاشات والخبراء لمرة واحدة فقط .
ويحدد القرار الصادر بتشكيل المجلس المعاملة المالية لرئيس الهيئة ونوابه ، وما يتقاضاه كل من رئيس وأعضاء المجلس من مكافآت وبدلات .
وللمجلس أن يشكل من بين أعضائه لجنة أو أكثر يعهد إليها بصفة مؤقتة ببعض المهام ، كما يجوز له تفويض رئيس المجلس أو أحد نوابه فى مباشرة بعض اختصاصاته .
ويشكل مجلس إدارة الهيئة لجنة للمراجعة من ثلاثة على الأقل من الأعضاء أو من غيرهم ، على أن تكون مدة عضويتها ثلاث سنوات قابلة للتجديد لمرة واحدة ، وتختص اللجنة بمراجعة التقارير المالية والاستثمارية للهيئة بما فى ذلك الحسابات الختامية قبل عرضها على مجلس إدارة الهيئة .
كما يشكل مجلس إدارة الهيئة لجنة للحوكمة من ثلاثة من الأعضاء واثنين من مجلس أمناء الاستثمار وثلاثة من الخبراء المتخصصين فى التأمينات الاجتماعية وأحد القانونيين ، على أن تكون مدة عضويتها ثلاث سنوات قابلة للتجديد لمرة واحدة ، ولا يجوز الجمع بين عضوية لجنة المراجعة وعضوية لجنة الحوكمة ، ويحدد مجلس إدارة الهيئة اختصاصات اللجنة .$m254$,'7b2d338252e8b84263286d5761cc8b3e',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(10,0,1,$m254$مجلس إدارة الهيئة هو السلطة العليا المهيمنة على شئونها وتصريف أمورها ، ووضع وتنفيذ السياسات اللازمة لتحقيق أغراضها وأهدافها ، وله أن يتخذ ما يراه لازما من قرارات نهائية لمباشرة اختصاصاتها ، وذلك دون الحاجة لاعتمادها من جهة أخرى ، وله على الأخص ما يأتى :
1 - اعتماد القرارات ذات الصبغة التشريعية والقرارات واللوائح الداخلية المتعلقة بالشئون الفنية والمالية والإدارية للهيئة وذلك دون التقيد بالقواعد والنظم الحكومية ، على أن تراجع اللوائح المالية من وزارة المالية .
2 - اعتماد القرارات واللوائح الداخلية المتعلقة بالشئون الفنية والمالية والإدارية ولائحة الاستثمار لصندوق الاستثمار دون التقيد بالقواعد والنظم الحكومية .
3 - الإشراف على سير العمل بالهيئة ، ومراجعة واعتماد سياستها وإستراتيجيتها المختلفة فى جميع المجالات .
4 - اعتماد الهيكل التنظيمى للهيئة .
5 - دراسة الخطط وإقرار مشروع الموازنة التخطيطية للهيئة .
6 - دراسة تقارير المتابعة وتقييم الأداء الدورية وإصدار القرارات اللازمة لرفع مستوى الأداء .
7 - إقرار ميزانية الهيئة وقوائمها المالية .
8 - اقتراح التشريعات الخاصة بالتأمين الاجتماعى .
9 - اعتماد ومتابعة خطط وسياسات استثمار أموال التأمين الاجتماعى .
10 - الإشراف والرقابة على إدارة صندوق استثمار أموال التأمين الاجتماعى .
11 - تعيين مديرى الاستثمار .
12 - ترشيح لجنة الخبراء لفحص وإعداد المركز المالى لحسابات نظم التأمين الاجتماعى .
13 - مناقشة واعتماد التقارير الإكتوارية الخاصة بالهيئة بما يكفل ضمان التوازن المالى للنظام .
14 - إقرار المسائل المالية والإدارية والفنية التى تقضى القوانين واللوائح والقرارات باختصاص المجلس بها .
15 - مباشرة السلطات والاختصاصات المقررة لوزارة التأمينات والمنصوص عليها فى القانون رقم 64 لسنة 1980 بشأن أنظمة التأمين الاجتماعى الخاصة البديلة .
16 - وضع نظام خاص لأجور وإثابة العاملين بالهيئة فى ضوء معدلات أدائهم وحجم ومستوى إنجازهم فى العمل ، وذلك دون التقيد بأى نظام أو قانون آخر ، وتتضمن موازنة الهيئة تخصيص مبالغ للمساهمة فى صندوق الرعاية الاجتماعية والصحية للعاملين بالهيئة وأسرهم .
ويكون لرئيس الهيئة سلطات الوزير المختص فى التعاقد طبقا لأحكام قانون تنظيم التعاقدات التى تبرمها الجهات العامة الصادر بالقانون رقم 182 لسنة 2018 ، لتدبير احتياجات الهيئة من المقار والتجهيزات والمعدات والأدوات والأجهزة اللازمة لحسن سير العمل وتقديم خدمة تأمينية متميزة .
ويتعين أخذ رأى مجلس إدارة الهيئة فى مشروعات القوانين المتعلقة بمجال عمل الهيئة .$m254$,'c1c483e7da466ee555f0c3a910568b1d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(11,0,1,$m254$يمثل الهيئة رئيسها أمام القضاء وفى صلاتها بالغير ، ويتولى الاختصاصات الآتية :
1 - تنفيذ قرارات مجلس الإدارة .
2 - إدارة الهيئة وتطوير نظام العمل بها ومتابعته .
3 - دراسة وإقرار المسائل المالية والإدارية والفنية التى تقضى القوانين واللوائح والقرارات باختصاصه بها .
4 - عرض مشروع ميزانية الهيئة وحساباتها الختامية على مجلس الإدارة خلال ستة أشهر من تاريخ انتهاء السنة المالية ، مع تقرير عن متابعة أعمال الهيئة وتقييم أدائها .
5 - إبلاغ الجهات المختصة بمشروع الحساب الختامى للهيئة خلال شهر من تاريخ موافقة مجلس الإدارة عليه .
6 - موافاة أجهزة الدولة بما تطلبه من بيانات وتقارير عن الهيئة .
ويجوز لرئيس الهيئة أن يفوض أحد نوابه فى بعض اختصاصاته .$m254$,'7aec12de744e18bb7f8212ba50278bc8',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(12,0,1,$m254$تنشأ بالهيئة لجنة الخبراء ، بعدد لا يزيد على تسعة أعضاء ، يصدر بتشكيلها قرار من رئيس مجلس الوزراء بناء على عرض رئيس الهيئة بعد موافقة مجلس الإدارة على أن يتضمن القرار تحديد اختصاصاتها ومكافآت أعضائها ولها على الأخص ما يأتى :
1 - تحديد الأسس والفروض وجداول الحياة التى يتم على أساسها إجراء التقييم الإكتوارى .
2 - إجراء التقييم الاكتوارى لنظم التأمين الاجتماعى ، ويعتمد من الخبراء الإكتواريين .
3 - تقديم الخبرات والاستشارات سواء الاكتوارية أو التأمينية لمجلس إدارة الهيئة .
4 - إعداد الدراسات والأبحاث التى يكلفها بها مجلس الإدارة .
5 - إبداء الرأى فى مشروعات قوانين التأمين الاجتماعى .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وإجراءات ونظام عمل هذه اللجنة .$m254$,'b45d8764689434e38e4bd16c6b10ad53',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(13,0,1,$m254$تلتزم الهيئة بأن تقدم قوائم مالية سنوية وربع سنوية إلى رئيس الجمهورية ومجلس الوزراء ومجلس النواب ، وتحدد اللائحة التنفيذية لهذا القانون المواعيد والقواعد والإجراءات الخاصة بتقديم هذه القوائم ، ومواعيد وطريقة نشرها .$m254$,'ff1d66a0ac4995d0c0e49798dbda14f5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(14,0,1,$m254$ينشأ صندوق لإدارة واستثمار أموال الصندوق المشار إليه بالمادة ( 5 ) من هذا القانون .$m254$,'abc207387259a7d78e338610a76edad1',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(15,0,1,$m254$يشكل بقرار من رئيس مجلس الوزراء بعد موافقة مجلس إدارة الهيئة مجلس أمناء لا يزيد عدد أعضائه على خمسة عشر عضوا من المتخصصين لاستثمار أموال التأمين الاجتماعى يتولى إدارة الصندوق المشار إليه بالمادة السابقة ، ويحدد القرار أجور ومكافآت الرئيس والأعضاء وذلك دون التقيد بأى قانون آخر ، كما يحدد حالات عزل رئيس المجلس والأعضاء وشروط العضوية واستمرارها ، على أن تكون مدة رئاسة هذا الصندوق ومدة العضوية ثلاث سنوات تجدد لمرة واحدة فقط .
وتحدد اللائحة التنفيذية لهذا القانون قواعد تشكيل هذا المجلس ونظام العمل به وقواعد ونسب استثمار أصول وأموال التأمين الاجتماعى .$m254$,'a369ee4b86c8310d92bf30f37e18dd81',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(16,0,1,$m254$يختص مجلس أمناء استثمار أموال التأمين الاجتماعى بما يأتى :
1 - وضع السياسة العامة الاستثمارية لصندوق الاستثمار ، والإشراف عليه ووضع الخطط والبرامج اللازمة بما يكفل تنمية موارده المالية ، مع مراعاة الأسس الآتية :
( أ ) السيولة اللازمة لصرف المستحقات التأمينية .
( ب ) استثمار نسبة لا تقل عن ( 75٪ ) من احتياطيات الأموال فى أذون وسندات الخزانة العامة ، ويجوز تخفيض هذه النسبة باقتراح من رئيس الهيئة باتفاق الوزير المختص بالتأمينات الاجتماعية ووزير المالية ووفقا للقواعد والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
( ج ) تنويع المحفظة بين أدوات الاستثمار المختلفة ، على أن تتضمن نسبة فى الاستثمارات الاجتماعية ، على ألا يقل عائد الاستثمار عنها عن سعر الخصم الاكتوارى .
( د ) التكاليف والمصروفات التشغيلية والاستثمارية والحدود القصوى لهما .
( هـ ) العائد الاستثمارى المحقق لا يقل عن سعر الخصم الاكتوارى .
( و ) الطاقة الاستيعابية لأسواق رأس المال وتأثير تدفقات أموال التأمين الاجتماعى إلى السوق .
( ز ) الحفاظ على القيمة الحقيقية للأموال المستثمرة .
2 - وضع مشروع الموازنة السنوية لصندوق الاستثمار .
3 - رفع التقارير الدورية لمجلس إدارة الهيئة عن نشاط صندوق الاستثمار وأدائه .
4 - مراجعة الحسابات الختامية عن صندوق الاستثمار .
5 - اقتراح الهيكل التنظيمى وجدول الوظائف لصندوق استثمار أموال التأمين الاجتماعى .
6 - اقتراح تعيين أمين الحفظ ومديرى الأصول ومتابعة أدائهم .
7 - الاختصاصات الأخرى التى تحدد بقرار تشكيل مجلس أمناء الاستثمار .$m254$,'dbc21ba9e4e8c0b91a15eeb8694fdf51',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(17,0,1,$m254$يجوز للهيئة تأسيس شركات مساهمة بمفردها أو مع شركاء آخرين ، وفقا لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981 ، وذلك بما لا يتعارض وأغراض الهيئة ، على أن يصدر قرار من رئيس الهيئة بعد موافقة مجلس الوزراء ووفقا للضوابط التى يحددها مجلس الإدارة .$m254$,'d3aa9fcd778d23cd815533810d76411d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(18,0,1,$m254$تنشئ الهيئة صندوقا للاستثمارات العقارية وفقا لأحكام قانون سوق رأس المال .
ويصدر رئيس الجمهورية القرارات اللازمة لتخصيص الأصول العقارية للهيئة ، على أن تشكل لجنة بقرار من رئيس مجلس الوزراء لتقييم هذه الأصول .$m254$,'201a1ee046302b51ca72442adfa1ebf5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(19,0,1,$m254$تتحدد اشتراكات تأمين الشيخوخة والعجز والوفاة للفئات المشار إليها بالمادة ( 2 ) من هذا القانون وفقا لما يأتى :
1 - بالنسبة للفئات المشار إليها بالبند أولا :
( أ ) الحصة التى يلتزم بها صاحب العمل بواقع ( 12٪ ) من أجور المؤمن عليهم العاملين لديه شهريا .
( ب ) الحصة التى يلتزم بها المؤمن عليه بواقع ( 9٪ ) من أجره شهريا .
2 - بالنسبة للفئات المشار إليها بالبندين ثانيا وثالثا بواقع ( 21٪ ) من دخل الاشتراك الشهرى الذى يختاره المؤمن عليه من الجدول المرفق باللائحة التنفيذية لهذا القانون .
3 - بالنسبة للفئات المشار إليها بالبند رابعا :
( أ ) الحصة التى يلتزم بها المؤمن عليه بواقع ( 9٪ ) من الحد الأدنى لأجر الاشتراك شهريا .
( ب ) مساهمة الخزانة العامة بواقع ( 12٪ ) من الحد الأدنى لأجر الاشتراك شهريا .
وتزاد نسبة الاشتراكات كل سبع سنوات اعتبارا من تاريخ العمل بهذا القانون بنسبة ( 1٪ ) وتقسم مناصفة بين صاحب العمل والمؤمن عليه ، على ألا تتجاوز إجمالى نسبة الاشتراكات 26٪ .$m254$,'2b626be1128593ff7e52b5f400db95d5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(20,0,1,$m254$يجوز للمؤمن عليه أن يطلب حساب مدة ضمن مدة اشتراكه فى تأمين الشيخوخة والعجز والوفاة إذا توافرت فى شأنها الشروط الآتية :
1 - أن تكون المدة تالية لسن بداية الخضوع لأحكام هذا القانون .
2 - أن تكون سنوات كاملة .
3 - أن تكون سابقة على مدة الاشتراك الأخيرة وغير خاضعة لنظام التأمين الاجتماعى .
وتقدر تكلفة حساب هذه المدة وفقا للجدول رقم ( 3 ) المرافق لهذا القانون .
ويكون للمؤمن عليه أداء المبالغ المطلوبة منه لحساب المدة وفقا لإحدى الطرق الآتية :
1 - دفعة واحدة خلال سنة من تاريخ طلب الحساب بما لا يجاوز تاريخ انتهاء الخدمة .
2 - بالتقسيط وفقا للجدول رقم ( 4 ) المرافق لهذا القانون ، ولا يعتبر المؤمن عليه مشتركا إلا إذا تم سداد أول قسط للهيئة قبل تاريخ انتهاء الخدمة .
وفى جميع الأحوال ، لا يجوز لأى سبب من الأسباب العدول عن طلب حساب المدة .$m254$,'5d326797828630bca06c958c181cf8a0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(21,0,1,$m254$يستحق المعاش فى الحالات الآتية :
1 - بلوغ سن الشيخوخة مع توافر مدة اشتراك فى تأمين الشيخوخة والعجز والوفاة لا تقل عن 120 شهرا فعلية على الأقل ، وتكون المدة 180 شهرا فعلية بعد خمس سنوات من تاريخ العمل بهذا القانون .
2 - انتهاء خدمة المؤمن عليه من الفئات المشار إليها بالبند أولا من المادة ( 2 ) من هذا القانون للوفاة أو العجز الكامل أو العجز الجزئى المستديم متى ثبت عدم وجود عمل آخر له لدى صاحب العمل .
ويثبت عدم وجود عمل آخر لدى صاحب العمل فى حالة ثبوت العجز الجزئى المشار إليه بقرار من لجنة يصدر بتشكيلها قرار من رئيس الهيئة بالاتفاق مع الوزراء المختصين ، ويكون من بين أعضائها ممثل عن التنظيم النقابى أو العاملين بحسب الأحوال وممثل عن الهيئة ، ويحدد القرار قواعد وإجراءات ونظام عمل اللجنة .
ويستثنى من شرط عدم وجود عمل آخر الحالات التى يصدر بها قرار من رئيس الهيئة بناء على موافقة مجلس الإدارة .
3 - العجز الكامل أو الوفاة أثناء مزاولة العمل أو النشاط حسب الأحوال بالنسبة للفئات المشار إليها بالبنود ثانيا وثالثا ورابعا من المادة ( 2 ) من هذا القانون .
4 - العجز الكامل أو الوفاة خلال سنة من تاريخ انتهاء خدمة أو عمل أو نشاط المؤمن عليه ، وبشرط عدم تجاوز سن الشيخوخة وعدم صرف تعويض الدفعة الواحدة .
5 - العجز الكامل أو الوفاة بعد انقضاء سنة من تاريخ انتهاء خدمة أو عمل أو نشاط المؤمن عليه متى كانت مدة اشتراكه فى التأمين لا تقل عن 120 شهرا فعلية على الأقل ، وتكون المدة 180 شهرا فعلية بعد خمس سنوات من تاريخ العمل بهذا القانون ، وبشرط عدم تجاوز سن الشيخوخة وعدم صرف تعويض الدفعة الواحدة .
6 - انتهاء خدمة أو عمل أو نشاط المؤمن عليه لغير بلوغ سن الشيخوخة أو العجز أو الوفاة مع توافر الشروط الآتية :
( أ ) توافر مدد اشتراك فى تأمين الشيخوخة والعجز والوفاة تعطى الحق فى معاش لا يقل عن ( 50٪ ) من أجر أو دخل التسوية الأخير ، وبما لا يقل عن الحد الأدنى للمعاش المشار إليه بالفقرة الأخيرة من المادة ( 24 ) من هذا القانون .
( ب ) أن تتضمن مدة الاشتراك المشار إليها بالبند ( أ ) مدة اشتراك فعلية لا تقل عن 240 شهرا ، وتكون المدة 300 شهرا فعلية بعد خمس سنوات من تاريخ العمل بهذا القانون .
( ج ) تقديم طلب الصرف .
( د ) ألا يكون خاضعا لتأمين الشيخوخة والعجز والوفاة فى تاريخ تقديم طلب الصرف .
ويشترط لاستحقاق المعاش فى الحالات الواردة بالبنود ( 2 ، 3 ، 4 ) أن تكون للمؤمن عليه مدة اشتراك لا تقل عن ثلاثة أشهر متصلة أو ستة أشهر متقطعة ، ولا يسرى هذا الشرط فى الحالات الآتية :
( أ ) المؤمن عليهم المنصوص عليهم فى ( 1 ، 2 ) من البند أولا من المادة ( 2 ) من هذا القانون .
( ب ) المؤمن عليهم المنصوص عليهم فى ( 3 ) من البند أولا من المادة ( 2 ) الذين يخضعون للوائح توظف صادرة بناء على قانون أو حددت أجورهم وعلاواتهم وترقياتهم بمقتضى اتفاقات جماعية أبرمت وفقا لقانون العمل متى وافق رئيس الهيئة على هذه اللوائح أو الاتفاقات .
( ج ) انتقال المؤمن عليه من العاملين المشار إليهم فى ( 1 ، 2 ) من البند أولا من المادة ( 2 ) من هذا القانون إلى الفئة المشار إليها فى ( 3 ) من ذات البند ، أو إلى أى من البنود الأخرى من ذات المادة .
( د ) ثبوت العجز أو وقوع الوفاة نتيجة إصابة عمل .
ويجوز تخفيض سن الشيخوخة بالنسبة للمؤمن عليهم من العاملين فى الأعمال الصعبة أو الخطرة التى تحدد بقرار من رئيس مجلس الوزراء بناء على عرض رئيس الهيئة ، ويجب أن يتضمن هذا القرار ما يأتى :
( أ ) تحديد السن المشار إليها بالنسبة لكل من تلك الأعمال .
( ب ) رفع النسب التى يحسب على أساسها المعاش بالقدر الذى يعوض المؤمن عليه عن تخفيض السن .
( ج ) زيادة نسبة الاشتراكات التى يتحملها صاحب العمل لمواجهة الأعباء الناتجة عن المزايا التى تتقرر للعاملين المشار إليهم .$m254$,'4ab84cc89e9ad362d0fd6b4580ec0489',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(22,0,1,$m254$يحدد أجر أو دخل التسوية عن مدة الاشتراك التى تبدأ من تاريخ العمل بأحكام هذا القانون على أساس المتوسط الشهرى للأجور أو الدخول التى أديت على أساسها الاشتراكات عن هذا الأجر أو الدخل .
ويراعى فى حساب المتوسط الشهرى ما يأتى :
1 - لا يدخل شهر البداية ضمن فترة المتوسط إلا إذا كان شهرا كاملا ويدخل الشهر الذى انتهت فيه الخدمة كاملا ضمن فترة المتوسط .
2 - يزاد المتوسط بنسبة تساوى متوسط نسب التضخم خلال المدة من بداية الاشتراك وحتى تحقق واقعة استحقاق الحقوق التأمينية عن كل سنة كاملة من سنوات مدة الاشتراك الفعلية عن هذا الأجر بشرط ألا يزيد المتوسط بعد إضافة هذه الزيادة على الحد الأقصى لأجر الاشتراك .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام تنفيذ هذه المادة .$m254$,'c1f6b5b9f012c9229ba346441180bc6b',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(23,0,1,$m254$مدة اشتراك المؤمن عليه فى تأمين الشيخوخة والعجز والوفاة هى :
1 - مدد الاشتراك وفقا لقوانين التأمين الاجتماعى السابقة على تاريخ الانتفاع بأحكام هذا القانون ويجبر كسر الشهر شهرا فى مجموع حساب هذه المدد ، وذلك مع عدم الإخلال بأحكام المادة ( 159 ) من هذا القانون .
2 - المدة التى تبدأ من تاريخ الانتفاع بأحكام هذا القانون .
3 - المدد التى ضمت لمدة اشتراك المؤمن عليه فى هذا التأمين بناء على طلبه .
4 - المدد المضافة بقوانين وقرارات خاصة ، على أن تحسب هذه المدد فى المعاش ضمن مدة الاشتراك بواقع الربع وتتحمل الخزانة العامة بالتكلفة المترتبة على إضافة هذه المدة .
ويجبر كسر الشهر شهرا فى مجموع حساب المدد المشار إليها ، كما يجبر كسر السنة سنة كاملة فى هذا المجموع إذا كان من شأن ذلك استحقاق المؤمن عليه معاشا .$m254$,'a55d6371ca1f6299179658e654c447e9',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(24,0,1,$m254$يسوى المعاش عن مدة الاشتراك فى تأمين الشيخوخة والعجز والوفاة التى تبدأ من تاريخ العمل بهذا القانون بواقع جزء واحد من المعامل المناظر لسن المؤمن عليه المحدد بالجدول رقم ( 5 ) المرافق لهذا القانون عن كل سنة ، بحد أقصى مقداره ( 80٪ ) من أجر أو دخل التسوية .
ويسوى المعاش عن مدة الاشتراك السابقة على تاريخ العمل بهذا القانون بواقع المعامل المنصوص عليه بالفقرة الأولى ، وأجر التسوية المشار إليه بالمادة ( 156 ) من هذا القانون ، بحد أقصى مقداره ( 80٪ ) من أجر التسوية .
ويربط المعاش بمجموع المعاشات المستحقة بما لا يجاوز ( 80٪ ) من أجر التسوية الأكبر وفقا للفقرتين الأولى والثانية من هذه المادة .
وإذا قل إجمالى المعاش المستحق فى حالة استحقاقه وفقا للبنود ( 2 ، 3 ، 4 ) من المادة ( 21 ) من هذا القانون عن ( 65٪ ) من أجر أو دخل التسوية الأكبر رفع إلى هذا المقدار .
وفى جميع الأحوال ، يتعين ألا يزيد إجمالى المعاش على ( 80٪ ) من الحد الأقصى لأجر الاشتراك فى تاريخ الاستحقاق .
وفى حالات استحقاق المعاش وفقا للبنود ( 1 ، 2 ، 3 ، 4 ، 5 ) من المادة ( 21 ) من هذا القانون يجب ألا يقل إجمالى المعاش المستحق عن 65٪ من الحد الأدنى لأجر الاشتراك فى تاريخ استحقاق المعاش .$m254$,'b64179bb8ce8877e363a8af6284da4ec',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(25,0,1,$m254$يستحق المعاش اعتبارا من أول الشهر الذى نشأ فيه سبب الاستحقاق ، ويستحق المعاش لتوافر الحالة المنصوص عليها فى البند ( 6 ) من المادة ( 21 ) من أول الشهر الذى قدم فيه طلب الصرف ، وفى حالة عدم تقديم طلب الصرف حتى بلوغ المؤمن عليه سن الشيخوخة أو ثبوت العجز الكامل أو وقوع الوفاة ، فيستحق المعاش اعتبارا من أول الشهر الذى تحققت فيه إحدى الوقائع المشار إليها .$m254$,'61d10822321c37272c0167af3f2e9b92',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(26,0,1,$m254$فى حالة انتهاء خدمة أو نشاط أو عمل المؤمن عليه ، ولم تتوافر فى شأنه شروط استحقاق المعاش ، يستحق تعويض الدفعة الواحدة عن مدد اشتراكه فى تأمين الشيخوخة والعجز والوفاة .
ويحسب هذا التعويض بنسبة ( 15٪ ) من الأجر السنوى عن كل سنة من سنوات مدة الاشتراك فى التأمين .
ويقصد بالأجر السنوى أجر أو دخل التسوية وفقا للمادة ( 22 ) من هذا القانون مضروبا فى اثنى عشر .
ويصرف هذا التعويض فى الحالات الآتية :
1 - مغادرة الأجنبى للبلاد نهائيا أو اشتغاله فى الخارج بصفة دائمة أو التحاقه بالبعثة الدبلوماسية فى سفارة أو قنصلية دولته .
2 - هجرة المؤمن عليه .
3 - الحكم نهائيا على المؤمن عليه بالسجن بقدر المدة الباقية لبلوغه سن الشيخوخة .
4 - إذا نشأ لدى المؤمن عليه خلال مدة سجنه عجز جزئى مستديم يمنعه من مزاولة العمل .
5 - انتظام المؤمن عليه فى سلك الرهبنة .
6 - عجز المؤمن عليه عجزا كاملا .
7 - وفاة المؤمن عليه ، وفى هذه الحالة تصرف المبالغ المستحقة بأكملها إلى مستحقى المعاش عنه حكما موزعة عليهم بنسبة أنصبتهم فى المعاش ، فإذا لم يوجد سوى مستحق واحد للمعاش أديت إليه هذه المبالغ بالكامل ، فإذا لم يوجد أى مستحق للمعاش صرفت للورثة الشرعيين .
8 - بلوغ المؤمن عليه سن الشيخوخة .
ويستثنى من تطبيق شرط انتهاء النشاط الحالات المنصوص عليها بالبنود ( 5 ، 6 ، 7 ، 8 ) بالنسبة للمؤمن عليهم المنصوص عليهم بالبند ثانيا من المادة ( 2 ) من هذا القانون .
وفى الحالات المنصوص عليها فى البنود ( 6 ، 7 ، 8 ) يصرف مبلغ التعويض مضافا إليه مبلغ يحسب بنسبة تساوى متوسط سعر أذون الخزانة خلال المدة من نهاية الاشتراك وحتى نهاية الشهر السابق على تاريخ تحقق واقعة استحقاق الصرف من مبلغ التعويض .$m254$,'04796a2ae0a6d67a5d267fc77c6c4b11',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(27,0,1,$m254$يسوى معاش كل من يشغل فعليا منصب نائب رئيس الجمهورية ورئيس مجلس النواب ورئيس مجلس الشيوخ ورئيس مجلس الوزراء ونوابه والوزراء ونوابهم والمحافظين ونوابهم بواقع جزء من عشرة أجزاء من أجر التسوية عن كل سنة خدمة قضيت فى المنصب ، وذلك بمراعاة الآتى :
1 - يقصد بأجر التسوية آخر مكافأة لرئيس مجلس النواب ورئيس مجلس الشيوخ أو آخر راتب بالنسبة لباقى الفئات وبما لا يجاوز صافى الحد الأقصى للأجور فى تاريخ انتهاء شغل المنصب .
2 - يكون الحد الأقصى للمعاش بواقع ( 80٪ ) من أجر التسوية المشار إليه بالبند السابق .
3 - إذا قل المعاش عن ( 25٪ ) من أجر التسوية المشار إليه فى البند ( 1 ) من هذه المادة رفع إلى هذا القدر ، وإذا انتهى شغل المنصب بسبب الوفاة الإصابية أو العجز الكلى الإصابى فيكون المعاش بواقع ( 80٪ ) من أجر التسوية المشار إليه فى البند ( 1 ) من هذه المادة .
4 - يجبر كسر الشهر إلى شهر فى حساب المدد المشار إليها .
5 - لا يسرى حكم هذه المادة على من هم فى درجة وزير .
وفى حالة تكرار الانتفاع بأحكام هذه المادة يكون الجمع بين المعاشات المستحقة وفقا لأحكامها بما لا يجاوز الحد الأقصى للمعاش المشار إليه بالبند ( 2 ) من الفقرة السابقة .
وتتحمل الخزانة العامة بالمعاش المستحق وفقا لهذه المادة من هذا القانون .
ولا يستفيد من أحكام هذه المادة من صدر ضده حكم بات فى جناية أو حكم عليه فى إحدى جرائم الإرهاب أو فى إحدى الجرائم المضرة بأمن الدولة .
وفى جميع الأحوال ، لا يجوز أن تزيد المعاشات والزيادات التى تستحق عليها ، والمستحقة وفقا لهذا القانون أو أى قانون آخر ، على صافى الحد الأقصى للأجور المشار إليه بالقانون رقم 100 لسنة 1987 بتحديد المعاملة المالية لرئيس مجلس النواب ورئيس مجلس الوزراء وأعضاء الحكومة والمحافظين ونوابهم .
وتحدد اللائحة التنفيذية لهذا القانون قواعد تنفيذ هذه المادة .$m254$,'a5559660404f99718e1754b20eb0a542',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(28,0,1,$m254$تضم مدة الخدمة بالقوات المسلحة إلى مدة الاشتراك فى تأمين الشيخوخة والعجز والوفاة وذلك بالنسبة إلى المنقولين إلى الخدمة المدنية من الضباط أو ضباط الشرف أو المساعدين أو ضباط الصف أو الجنود المتطوعين أو مجددى الخدمة ذوى الرواتب العالية أو الصناع العسكريين .
وتسوى حقوق المؤمن عليه المشار إليه بالفقرة السابقة عند انتهاء خدمته وفقا لأحكام هذا القانون مع مراعاة الآتى :
1 - إذا لم يكن قد اكتسب حقا فى المعاش عن مدة خدمته العسكرية فتسوى حقوقه باعتبار مدتى خدمته متصلة وفقا للأحكام المنصوص عليها فى هذا القانون .
2 - إذا كان قد اكتسب حقا فى المعاش عن مدة خدمته العسكرية فيسوى المعاش وفقا لأفضل إحدى الطريقتين الآتيتين له .
الطريقة الأولى - يسوى المعاش عن مدة خدمته العسكرية على أساس آخر أجر مستقطع منه احتياطى المعاش بواقع 1/36 من هذا الأجر عن كل سنة من سنواتها ، ويسوى المعاش عن مدة الاشتراك المدنية وفقا لأحكام هذا القانون .
الطريقة الثانية - يسوى معاشه باعتبار مدة خدمته العسكرية متصلة بالمدة المدنية وفقا للأحكام المنصوص عليها فى هذا القانون .
وفى جميع الحالات المنصوص عليها فى هذا البند يراعى ما يأتى :
( أ ) تحسب مدة الخدمة العسكرية وفقا لقانون التقاعد والتأمين والمعاشات للقوات المسلحة الذى انتهت هذه الخدمة فى ظله .
( ب ) يكون الجمع بين المعاش المستحق عن المدة العسكرية والمعاش المستحق عن المدة المدنية بما لا يجاوز ( 80٪ ) من الحد الأقصى لأجر الاشتراك فى هذا القانون .
( ج ) يلتزم الصندوق المشار إليه بالمادة ( 5 ) من هذا القانون بمستحقاته عن جميع مدد اشتراك المؤمن عليه وفقا لهذا القانون ، وتتحمل الخزانة العامة بنصيبها فى المعاش أو التعويض بنسبة المدة التى قضاها المؤمن عليه بالقوات المسلحة إلى مدة الاشتراك الكلية .
3 - إذا كان قد قرر له معاش عن مدة خدمته العسكرية تسوى حقوقه وفقا لأحكام المادة ( 29 ) من هذا القانون ويصرف المعاش النهائى من إدارة التأمين والمعاشات للقوات المسلحة .$m254$,'1fd1f354251469ca9c139794d25b4102',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(29,0,1,$m254$إذا انتهت الخدمة العسكرية لأحد المنصوص عليهم فى المادة السابقة ثم التحق بعمل يخضعه لأحكام هذا القانون يطبق عليه ما يأتى :
1 - إذا كان قد استحق مكافأة ومدفوعات عن مدة خدمته العسكرية ولم يكن قد صرفها ، فتحسب هذه المدة ضمن مدة اشتراكه فى هذا التأمين دون أداء أى مبالغ عنها .
فإذا كان قد صرفها ويرغب فى حساب المدة المشار إليها ضمن مدة اشتراكه فى هذا التأمين ، فيتعين عليه ردها إلى الصندوق المنصوص عليه بالمادة ( 5 ) من هذا القانون دفعة واحدة نقدا خلال ثلاث سنوات من تاريخ انتفاعه بأحكام هذا القانون .
وعند انتهاء خدمته المدنية تسوى حقوقه عن المدة العسكرية التى حسبت ضمن مدة اشتراكه فى هذا التأمين والمدة المدنية باعتبارهما وحدة واحدة وفقا لأحكام هذا القانون .
2 - إذا كان صاحب معاش عسكرى فتعتبر مدة اشتراكه الجديدة مدة قائمة بذاتها وتتحدد حقوقه التأمينية عنها وفقا لأحكام هذا القانون وذلك بمراعاة الآتى :
( أ ) عدم تكرار الانتفاع بالحد الأدنى للمعاش .
( ب ) يكون الجمع بين المعاش العسكرى المستحق فى تاريخ انتهاء الخدمة العسكرية والمعاش المستحق عن المدة الأخيرة بما لا يجاوز الحد الأقصى للمعاش المنصوص عليه بالفقرة الخامسة من المادة ( 24 ) من هذا القانون فى تاريخ الاستحقاق عن المدة الأخيرة .
( ج ) يكون الجمع بين المعاش العسكرى للمصابين بسبب العمليات الحربية أو بسبب الخدمة والمعاش المستحق عن المدة الأخيرة دون حدود .
( د ) يكون الجمع بين المعاش العسكرى ومعاش الإصابة دون حدود .
( هـ ) يصرف المعاش النهائى من إدارة التأمين والمعاشات للقوات المسلحة .$m254$,'d68321cdaf191feb4299ec0ee1e1114d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(30,0,1,$m254$إذا استحق المؤمن عليه صاحب المعاش العسكرى المجند أو المستبقى أو المستدعى بالخدمة العسكرية أو المكلف معاشا بسبب العمليات الحربية أو الخدمة العسكرية أو إحدى الحالات المذكورة بالمادة ( 31 ) من قانون التقاعد والتأمين والمعاشات للقوات المسلحة الصادر بالقانون رقم 90 لسنة 1975 ، وتوافرت فى شأنه إحدى حالات استحقاق المعاش عن مدة خدمته المدنية ، فيتم حساب معاش عن كامل مدة اشتراكه المدنية وفقا لأحكام هذا القانون ويضاف للمعاش العسكرى ويجمع بينهما دون حدود ، وإذا كان استحقاق المعاش العسكرى المشار إليه لوفاة المؤمن عليه كان للمستحقين عنه الحق فى الجمع بين كل من المعاش والحقوق التأمينية المقررة بهذا القانون وبقانون التقاعد والتأمين والمعاشات للقوات المسلحة المشار إليه .
وتسرى فى شأن المؤمن عليه من الفئات المشار إليها بهذه المادة الذى استحق معاش العجز وفقا لأحكام قانون التقاعد والتأمين والمعاشات الصادر بالقانون رقم 90 لسنة 1975 أحكام انتكاس الإصابة أو مضاعفاتها المنصوص عليها بالباب الرابع من هذا القانون .
ويصرف المعاش النهائى من إدارة التأمين والمعاشات للقوات المسلحة .$m254$,'9e73f45bc09bc6581a693fa48bc01234',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(31,0,1,$m254$يستحق مبلغ التعويض الإضافى فى الحالات الآتية :
1 - انتهاء خدمة المؤمن عليه للعجز الكامل أو الجزئى أو الوفاة متى أدى ذلك إلى استحقاقه معاشا .
2 - ثبوت العجز الكامل أو وقوع الوفاة نتيجة إصابة عمل بعد انتهاء الخدمة .
ويكون هذا التعويض معادلا لنسبة من الأجر السنوى تبعا لسن المؤمن عليه فى تاريخ الوفاة وفقا للجدول رقم ( 6 ) المرافق لهذا القانون .
ويقصد بالأجر السنوى فى هذه الحالة أجر تسوية المعاش مضروبا فى اثنى عشر .
وفى جميع الأحوال ، يزاد مبلغ التعويض الإضافى بنسبة ( 50٪ ) فى الحالات الناتجة عن إصابة عمل .
ويضاعف مبلغ التعويض الإضافى فى حالة استحقاقه لانتهاء خدمة المؤمن عليه بالوفاة ولم يوجد مستحقون للمعاش .
ويؤدى مبلغ التعويض الإضافى فى حالات استحقاقه للوفاة لمستحقى المعاش ، فإذا لم يوجد سوى مستحق واحد أدى إليه بالكامل ، فإذا لم يوجد أى مستحق صرف للورثة الشرعيين .$m254$,'65384e0f8ae75dd9ecc7d88ef3d52b79',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(32,0,1,$m254$عند وفاة صاحب المعاش تصرف نفقات جنازة بواقع معاش ثلاثة أشهر ، تصرف للأرمل أو الأرملة ، فإذا لم يوجد صرفت لأرشد الأولاد ، فإذا لم يوجد صرفت لأى شخص يثبت قيامه بصرفها .
ويجب أن يتم صرف هذه النفقات خلال ثلاثة أيام على الأكثر من تاريخ تقديم الطلب .$m254$,'30b1d8947ffb2cf152279fcba8f7ebf8',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(33,0,1,$m254$عند وفاة المؤمن عليه أو صاحب المعاش تستحق منحة عن شهر الوفاة والشهرين التاليين وذلك بالإضافة إلى الأجر المستحق عن أيام العمل خلال شهر الوفاة .
وتقدر المنحة بالأجر أو المعاش المستحق عن شهر الوفاة ، وتلتزم بها الجهة التى كانت تصرف الأجر أو التى تلتزم بصرف المعاش بحسب الأحوال .
ويخصم بها بالنسبة للمؤمن عليهم العاملين بالجهات المشار إليها بالبندين ( 1 ، 2 ) من أولا من المادة ( 2 ) على البند الذى كان يتحمل بالأجر .
وتستحق المبالغ المنصوص عليها فى هذه المادة لمستحقى المعاش فإذا لم يوجد سوى مستحق واحد أديت إليه بالكامل .$m254$,'42fd99d6d9055dcf98528dcf763632f5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(34,0,1,$m254$يصرف للمستحقين فى حالة فقد المؤمن عليه أو صاحب المعاش إعانة شهرية تعادل ما يستحقونه عنه من معاش بافتراض وفاته ، وتصرف اعتبارا من أول الشهر الذى فقد فيه إلى أن يظهر أو تثبت وفاته حقيقة أو حكما .
وإذا كان فقد المؤمن عليه أثناء تأدية عمله ، فتقدر الإعانة بما يعادل المعاش المقرر فى تأمين إصابات العمل والمعاش المقرر فى تأمين الشيخوخة والعجز والوفاة .
وتسرى على الإعانة أحكام المادة ( 35 ) من هذا القانون .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات الواجب اتخاذها لإثبات حالة الفقد ، كما تحدد القواعد والإجراءات الواجب اتخاذها حيال المبالغ التى صرفت للمستحقين فى حالة العثور على المؤمن عليه أو صاحب المعاش حيا .
وبعد فوات أربع سنوات من تاريخ الفقد أو ثبوت الوفاة حقيقة أو حكما ، يعتبر تاريخ الفقد هو تاريخ انتهاء الخدمة وذلك فى تقدير جميع الحقوق التأمينية وفقا لأحكام هذا القانون ، وتعتبر الإعانة السابق صرفها معاشا منذ تاريخ تحقق إحدى الوقائع المشار إليها .
وتصرف المبالغ المنصوص عليها فى المواد ( 31 ، 33 ، 37 ) من هذا القانون للمستحقين لها الموجودين على قيد الحياة فى تاريخ انقضاء مدة الفقد المشار إليها ، أو فى تاريخ ثبوت الوفاة الحقيقية أو الحكمية .$m254$,'7692629294b3f301d11ec20d607d5d4c',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(35,0,1,$m254$تزاد المعاشات المستحقة فى 30 يونيو من كل عام اعتبارا من أول يوليو بنسبة معدل التضخم بحد أقصى لنسبة الزيادة ( 15٪ ) ، ولا تزيد قيمة الزيادة فى المعاش على نسبة الزيادة منسوبة إلى الحد الأقصى لأجر الاشتراك الشهرى فى 30 يونيو من كل عام ، على أن يتحمل صندوق التأمين الاجتماعى المشار إليه بالمادة ( 5 ) من هذا القانون بنسبة الزيادة عن جزء المعاش الذى يلتزم به ، وتتحمل الخزانة العامة بباقى قيمة الزيادة ، وتعتبر الزيادة جزءا من المعاش عند حساب الزيادة التالية .
ويصدر رئيس مجلس إدارة الهيئة قرارا بنسبة الزيادة بناء على تقارير لجنة الخبراء .
على ألا تقل قيمة المعاش بعد الزيادة عن الحد الأدنى المشار إليه بالفقرة الأخيرة من المادة ( 24 ) فى تاريخ تقرير الزيادة ، ولا يسرى حكم هذه الفقرة على معاش العجز الجزئى الإصابى غير المنهى للخدمة .
ومع عدم الإخلال بأحكام هذه المادة يستحق صاحب معاش العجز الكامل المستديم والولد العاجز عن الكسب إعانة عجز تقدر ب ( 20٪ ) شهريا من قيمة ما يستحقه من معاش وزياداته إذا قررت الهيئة المعنية بالتأمين الصحى الشامل أنه يحتاج إلى المعاونة الدائمة من شخص آخر للقيام بأعباء حياته اليومية ، وتقطع هذه الإعانة فى حالة الالتحاق بعمل ، أو زوال الحالة وفقا لما تقرره الهيئة المشار إليها أو وفاته .$m254$,'31f3f8735804d99225aa907ab804d506',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(36,0,1,$m254$يخضع لنظام المكافأة المؤمن عليهم الوارد ذكرهم فى البند أولا من المادة ( 2 ) من هذا القانون .
ويمول نظام المكافأة مما يأتى :
1 - حصة يلتزم بها المؤمن عليه بواقع ( 1٪ ) من أجر الاشتراك شهريا .
2 - حصة يلتزم بها صاحب العمل بواقع ( 1٪ ) من أجر اشتراك المؤمن عليه لديه شهريا .
وتودع المبالغ المذكورة فى حساب شخصى خاص بالمؤمن عليه ، ويستحق عن المبالغ الفعلية المودعة فى هذا الحساب عائد استثمار عن المدة من أول الشهر التالى لإيداع المبالغ فى الحساب وحتى نهاية الشهر السابق على تاريخ استحقاق الحقوق التأمينية .
وتقوم الهيئة باستثمار أموال هذا الحساب ، وتحدد اللائحة التنفيذية لهذا القانون القواعد والإجراءات المنظمة لإيداع المبالغ وحساب عائد استثمار أموال هذا الحساب وكيفية إضافته للرصيد .$m254$,'c0336cd1922fd7365118cacc2b1fc32c',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(37,0,1,$m254$يصرف للمؤمن عليه الخاضع لنظام المكافأة الرصيد المتوافر فى حسابه الشخصى عند تحقق واقعة استحقاق الحقوق التأمينية وفقا لأحكام المادتين ( 21 ، 26 ) من هذا القانون .
وفى حالة وفاته يصرف هذا الرصيد لمستحقى المعاش أو تعويض الدفعة الواحدة وفقا لأنصبتهم المحددة بالجدول رقم ( 7 ) المرافق لهذا القانون ، فإذا لم يوجد سوى مستحق واحد أدى إليه بالكامل ، وفى حالة عدم وجود مستحقين للمعاش يصرف هذا الرصيد للورثة الشرعيين .$m254$,'e4e160c8879388999e120bc002953705',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(38,0,1,$m254$يجوز للمؤمن عليه الذى يزيد أجره على الحد الأقصى لأجر الاشتراك التأمينى أن يطلب الحصول على معاش إضافى من الهيئة مقابل الاشتراك عن الجزء الزائد عن الحد الأقصى لأجر الاشتراك التأمينى بما لا يجاوز ( 100٪ ) من الحد الأقصى لأجر الاشتراك .
ويتم إنشاء حساب شخصى فى صندوق التأمين الاجتماعى المنصوص عليه فى المادة ( 5 ) مقابل الحصول على معاش إضافى للمؤمن عليه المشار إليه بالفقرة السابقة .
وتحدد اللائحة التنفيذية لهذا القانون النظام التأمينى المكمل ونسبة الاشتراكات التى يلتزم بها المؤمن عليه ، وشروط وقواعد الانتفاع بهذه المادة .$m254$,'37e46df0981af1c4d9563fb5664f260d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(39,0,1,$m254$تؤدى الاشتراكات الشهرية على أساس أجر أو دخل الاشتراك الزائد عن الحد الأقصى لأجر الاشتراك التأمينى بما لايجاوز ( 100٪ ) من الحد الأقصى لأجر الاشتراك وفقا لإجمالى نسبة الاشتراكات المستحقة عن تأمين الشيخوخة والعجز والوفاة .
وتسرى على هذا الحساب أحكام الفقرتين الثالثة والرابعة من المادة ( 36 ) من هذا القانون .$m254$,'61239886948d7c5b1602690bb5f9a8c5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(40,0,1,$m254$يستحق المعاش الإضافى فى حالة استحقاق المؤمن عليه معاشا وفقا لأحكام المادة ( 21 ) من هذا القانون .
ويحسب المعاش الإضافى بقسمة رصيد الحساب الشخصى المشار إليه بالمادة ( 38 ) من هذا القانون على دفعة الحياة ، ويضاف هذا المعاش إلى المعاش المستحق وفقا لأحكام هذا القانون ، ويدخل هذا المعاش فى وعاء حساب زيادة المعاش المشار إليها بالمادة ( 35 ) من هذا القانون .
ويتم تحديد دفعة الحياة من خلال لجنة الخبراء ، ويصدر بها قرار من رئيس الهيئة بعد موافقة مجلس الإدارة ، على أن يعاد النظر فيها كل خمس سنوات .
وفى حالة استحقاق تعويض الدفعة الواحدة وفقا لأحكام المادة ( 26 ) من هذا القانون ، يصرف الرصيد المتوافر فى الحساب .
وفى حالة وفاة المؤمن عليه وعدم استحقاق معاش يصرف هذا الرصيد لمستحقى المعاش أو تعويض الدفعة الواحدة وفقا لأنصبتهم المحددة بالجدول رقم ( 7 ) المرافق لهذا القانون ، فإذا لم يوجد سوى مستحق واحد أدى إليه بالكامل ، وفى حالة عدم وجود مستحقين للمعاش يصرف هذا الرصيد للورثة الشرعيين .$m254$,'2dd08535715a6c0930a8f4ae6473cf71',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(41,0,1,$m254$يصدر رئيس مجلس الوزراء بناء على عرض الوزير المختص بالتأمينات قرارا بتوحيد سن الشيخوخة تدريجيا ليكون الخامسة والستين اعتبارا من أول يوليو 2040$m254$,'a019c22f9363ad9558ea48b80b0d404f',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(42,0,1,$m254$يفترض عدم انتهاء خدمة أو عمل أو نشاط المؤمن عليه فى حالة انتقاله بين الفئات أو البنود المنصوص عليها بالمادة ( 2 ) من هذا القانون ، وتسوى حقوقه عند انتهاء خدمته عن مجموع مدد اشتراكه المختلفة كوحدة واحدة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام تطبيق هذه المادة .$m254$,'9b7b56e5048e7b0a46575fad06d778e7',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(43,0,1,$m254$فى حالة عدم تنفيذ صاحب العمل لقرار اللجنة المشار إليها بالبند ( 2 ) من المادة ( 21 ) من هذا القانون ، يكون ملزما بأداء الأجر المستحق حتى تاريخ التحاق المؤمن عليه بعمل آخر ، ويتعين لإفادة المؤمن عليه من هذه الأحكام تنفيذ الشروط المنصوص عليها بالبند ( 4 ) من المادة ( 87 ) من هذا القانون ، ويسقط حق المؤمن عليه فى الأجر إذا رفض الالتحاق بالعمل المناسب .
ومع عدم الإخلال بأحكام قانون العمل ، لا يجوز لصاحب العمل إنهاء خدمة العامل خلال فترة عرضه على اللجنة المشار إليها بالفقرة السابقة وحتى صدور قرارها ، كما يعتبر عقد العمل ممتدا خلال الفترة المشار إليها وحتى صدور قرار اللجنة .
ويكون قرار الهيئة باستحقاق المؤمن عليه الأجر فى هذه الحالة بمثابة سند تنفيذى .$m254$,'e8dea8a0c7c91673d054875cb14b144a',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(44,0,1,$m254$إذا عاد صاحب المعاش المستحق وفقا لتأمين الشيخوخة والعجز والوفاة ، إلى عمل أو نشاط يخضعه لأحكام هذا التأمين ، فتعتبر مدة اشتراكه الجديدة مدة قائمة بذاتها ، وتتحدد حقوقه التأمينية عنها وفقا لأحكام هذا الباب .
ويراعى فى حالة استحقاق معاش عن المدة الأخيرة عدم تكرار الانتفاع بالحد الأدنى للمعاش فى تاريخ الاستحقاق .
ولا تسرى أحكام تأمين الشيخوخة والعجز والوفاة فى شأن المؤمن عليه إذا تجاوزت سنه سن الشيخوخة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام تنفيذ هذه المادة .$m254$,'b325a24d869fd6be79f4be4b35328f6f',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(45,0,1,$m254$تسرى أحكام هذا الباب على المؤمن عليهم الوارد ذكرهم فى البند أولا من المادة ( 2 ) بالإضافة إلى الفئات الآتية :
1 - العاملين بالقطاع الخاص الذين تقل أعمارهم عن 18 سنة .
2 - المتدرجين والتلاميذ الصناعيين .
3 - الطلاب المشتغلين فى مشروعات التشغيل الصيفى .
4 - المكلفين بالخدمة العامة .
5 - الملتحقين بعمل بعد سن التقاعد ولا تسرى فى شأنهم أحكام تأمين الشيخوخة والعجز والوفاة .$m254$,'e48d7010f0ae8e9ebe9e9e7403feb70b',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(46,0,1,$m254$مع عدم الإخلال بأحكام قانون نظام التأمين الصحى الشامل الصادر بالقانون رقم 2 لسنة 2018 يمول تأمين إصابات العمل مما يأتى :
1 - اشتراك شهرى يؤديه صاحب العمل يتحدد بواقع ( 1٪ ) من أجر الاشتراك للعاملين لديه بالنسبة لغير الخاضعين لأحكام قانون نظام التأمين الصحى الشامل المشار إليه يؤدى إلى الهيئة المعنية بالتأمين الصحى مقابل العلاج والرعاية الطبية .
2 - اشتراك شهرى يؤديه صاحب العمل يتحدد بواقع ( 0.5٪ ) من أجر الاشتراك للعاملين لديه مقابل الحقوق المالية التى تلتزم بها الهيئة ، وتتم زيادة نسبة الاشتراك الشهرى حتى تصل إلى ( 1٪ ) تبعا لمخاطر نشاط المنشأة وفقا لما تحدده اللائحة التنفيذية لهذا القانون فى هذا الشأن .
وتلتزم وحدات الجهاز الإدارى للدولة والهيئات العامة وغيرها من الأشخاص الاعتبارية العامة ووحدات القطاع العام وقطاع الأعمال العام بصرف تعويض الأجر ومصاريف الانتقال فى حالة الإصابة مقابل تخفيض نسبة الاشتراكات التى تلتزم بها وفقا للبند ( 2 ) من هذه المادة بواقع النصف .
وللهيئة الموافقة على قيام صاحب العمل فى غير الجهات المشار إليها بالفقرة السابقة من هذه المادة بأداء تعويض الأجر ومصاريف الانتقال مقابل تخفيض نسبة الاشتراكات التى تلتزم بها وفقا للبند ( 2 ) من هذه المادة بواقع النصف .
3 - ريع استثمار الاشتراكات المشار إليها .
ويعفى أصحاب الأعمال من أداء الاشتراكات عن المؤمن عليهم المشار إليهم بالبنود ( 1 ، 2 ، 3 ، 4 ) من المادة ( 45 ) من هذا القانون إذا كانوا لا يتقاضون أجرا .$m254$,'c91b62cd884a7ef4cc7fb2f72eee0d68',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(47,0,1,$m254$يقصد بالعلاج والرعاية الطبية ما ورد بالمادة ( 3 ) من قانون نظام التأمين الصحى الشامل الصادر بالقانون رقم 2 لسنة 2018$m254$,'1e182863b1421af3b6d5af28f5cc6d32',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(48,0,1,$m254$مع عدم الإخلال بأحكام قانون نظام التأمين الصحى الشامل الصادر بالقانون رقم ( 2 ) لسنة 2018 ، تتولى الهيئة المعنية بالتأمين الصحى علاج المصاب ورعايته طبيا .
ويجوز للمصاب العلاج فى درجة أعلى من الدرجة التأمينية على أن يتحمل فروق التكاليف أو يتحملها صاحب العمل إذا وجد اتفاق بذلك .
ويجوز لصاحب العمل علاج المصاب ورعايته طبيا متى صرحت له الهيئة المعنية بالتأمين الصحى بذلك وفقا للشروط والأوضاع التى يصدر بها قرار من رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى بالاتفاق مع رئيس الهيئة .$m254$,'08ee5244f233a638e9508da21050f8a3',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(49,0,1,$m254$إذا حالت الإصابة بين المؤمن عليه وبين أداء عمله تؤدى الجهة المختصة بصرف تعويض الأجر خلال فترة تخلفه عن عمله بسببها تعويضا عن أجره يعادل كامل أجره المسدد عنه الاشتراك ، ويصرف هذا التعويض للمصاب فى مواعيد صرف الأجور بالنسبة لمن يتقاضون أجورهم بالشهر ، وأسبوعيا بالنسبة لغيرهم .
ويستمر صرف هذا التعويض طوال مدة عجز المصاب عن أداء عمله أو حتى ثبوت العجز المستديم أو حدوث الوفاة .
وتعتبر فى حكم الإصابة كل حالة انتكاس أو مضاعفة تنشأ عنها .
ويتحمل صاحب العمل أجر يوم الإصابة أيا كان وقت وقوعها ، ويقدر التعويض اليومى على أساس الأجر الشهرى مقسوما على ثلاثين .$m254$,'8b3630e94796278de086f19ef4e9fe73',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(50,0,1,$m254$يلتزم صاحب العمل عند حدوث الإصابة بنقل المصاب إلى مكان العلاج ، وتتحمل الجهة المختصة بصرف تعويض الأجر بأداء مصاريف انتقال المصاب بوسائل الانتقال العادية من محل الإقامة إلى مكان العلاج إذا كان يقع خارج المدينة التى يقيم بها وبأداء مصاريف الانتقال بوسائل الانتقال الخاصة داخل المدينة أو خارجها متى قرر الطبيب المعالج أن حالة المصاب لا تسمح باستعماله وسائل الانتقال العادية .
ويتبع فى تنظيم الانتقال ومصاريفه ما تقضى به القواعد التى تتضمنها اللائحة التنفيذية لهذا القانون فى هذا الشأن .$m254$,'e04f492ca44ec682fbb54dcebfd065c1',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(51,0,1,$m254$إذا نشأ عن إصابة العمل عجز كامل أو وفاة سوى المعاش بنسبة ( 80٪ ) من الأجر المنصوص عليه فى المادة ( 22 ) من هذا القانون .
ويزاد هذا المعاش بنسبة ( 1٪ ) سنويا حتى بلوغ المؤمن عليه سن الستين حقيقة أو حكما إذا كان العجز أو الوفاة سببا فى إنهاء خدمة المؤمن عليه ، وتعتبر كل زيادة جزءا من المعاش عند تحديد مبلغ الزيادة التالية .$m254$,'0563db4373cb0cd4b5e441aa2a3a4e81',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(52,0,1,$m254$إذا نشأ عن الإصابة عجز جزئى مستديم تقدر نسبته ب ( 35٪ ) فأكثر ، استحق المصاب معاشا يساوى نسبة ذلك العجز من المعاش المنصوص عليه بالمادة ( 51 ) من هذا القانون .
وإذا أدى هذا العجز إلى إنهاء خدمة المؤمن عليه لثبوت عدم وجود عمل آخر له لدى صاحب العمل وفقا للقواعد المنصوص عليها بالبند ( 2 ) من المادة ( 21 ) من هذا القانون ، يزاد معاشه وفقا لحكم الفقرة الأخيرة من المادة ( 51 ) من هذا القانون .$m254$,'0f0636bdd671e27504293bcc833fb5dd',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(53,0,1,$m254$مع مراعاة حكم البند ( 2 ) من المادة ( 21 ) ، إذا نشأ عن الإصابة عجز جزئى مستديم ، لا تصل نسبته إلى ( 35٪ ) استحق المصاب تعويضا بنسبة ذلك العجز مضروبا فى قيمة معاش العجز الكامل المنصوص عليه بالمادة ( 51 ) من هذا القانون وذلك عن 4 سنوات ، ويؤدى هذا التعويض دفعة واحدة .$m254$,'cd19fcd4a0c75f6ed8019afc00e8cfbd',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(54,0,1,$m254$يكون معاش الوفاة أوالعجز الكامل لمن لا يتقاضى أجرا من الفئات المنصوص عليها بالبنود ( 1 ، 2 ، 3 ، 4 ) من المادة ( 45 ) من هذا القانون بواقع الحد الأدنى للمعاش المنصوص عليه بالفقرة الأخيرة من المادة ( 24 ) من هذا القانون ، وبما لا يقل عن الحد الأدنى الرقمى للمعاش المشار إليه بالمادة ( 163 ) من هذا القانون .
وإذا نشأ عن الإصابة عجز جزئى مستديم تقدر نسبته ب ( 35٪ ) فأكثر ، استحق المصاب معاشا يساوى نسبة ذلك العجز من المعاش المنصوص عليه بالفقرة السابقة .
ويسرى فى شأن هذا المعاش حكم الفقرة الأخيرة من المادة ( 51 ) من هذا القانون .
وإذا نشأ عن الإصابة عجز جزئى مستديم لا تصل نسبته إلى ( 35٪ ) استحق المصاب تعويضا يقدر بنسبة ذلك العجز مضروبا فى قيمة المعاش المنصوص عليه بالفقرة الأولى من هذه المادة وذلك عن 4 سنوات ، ويؤدى هذا التعويض دفعة واحدة .$m254$,'d92cb3b8eb5ff05a9998ed577083bc19',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(55,0,1,$m254$تقدر نسبة العجز الجزئى المستديم وفقا للقواعد الآتية :
1 - إذا كان العجز مبينا بالجدول رقم ( 2 ) المرافق لهذا القانون ، روعيت النسبة المئوية من درجة العجز الكلى المبينة به .
2 - إذا لم يكن العجز مما ورد بالجدول المذكور ، فتقدر نسبته بنسبة ما أصاب العامل من عجز فى قدرته على الكسب على أن تبين تلك النسبة فى الشهادة الطبية .
3 - إذا كان للعجز المتخلف تأثير خاص على قدرة المصاب على الكسب فى مهنته الأصلية فيجب توضيح نوع العمل الذى يؤديه المصاب تفصيلا مع بيان تأثير ذلك فى زيادة درجة العجز فى تلك الحالات على النسب المقررة لها فى الجدول رقم ( 2 ) المرافق لهذا القانون .
ولرئيس الهيئة زيادة النسب الواردة فى الجدول المذكور أو إضافة حالات جديدة إليه بناء على اقتراح مجلس الإدارة ، ويحدد القرار تاريخ العمل به .$m254$,'95c91a8967be35422f2d8cc117800686',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(56,0,1,$m254$إذا كان المصاب قد سبق أن أصيب بإصابة عمل ، روعيت فى تعويضه القواعد الآتية :
1 - إذا كانت نسبة العجز الناشئ عن الإصابة الحالية والإصابة السابقة أقل من ( 35٪ ) عوض المصاب عن إصابته الأخيرة على أساس نسبة العجز المتخلف عنها وحدها والأجر المشار إليه بالمادة ( 22 ) من هذا القانون وقت ثبوت العجز الأخير .
2 - إذا كانت نسبة العجز الناشئ عن الإصابة الحالية والإصابات السابقة تساوى ( 35٪ ) أو أكثر فيعوض على الوجه الآتى :
( أ ) إذا كان المصاب قد عوض عن إصابته السابقة تعويضا من دفعة واحدة يقدر معاشه على أساس نسبة العجز المتخلف عن إصاباته جميعها والأجر المشار إليه بالمادة ( 22 ) من هذا القانون وقت ثبوت العجز المتخلف عن الإصابة الأخيرة .
( ب ) إذا كان المصاب مستحقا لمعاش العجز يقدر معاشه على أساس نسبة العجز المتخلف عن إصاباته جميعها والأجر المشار إليه بالمادة ( 22 ) من هذا القانون وقت ثبوت العجز عن الإصابة الأخيرة بشرط ألا يقل ذلك المعاش عن معاشه عن الإصابة السابقة .$m254$,'f5a0c798736dbb3fb0c7b3345ecceaa4',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(57,0,1,$m254$لا يستحق تعويض الأجر وتعويض الإصابة فى الحالات الآتية :
1 - إذا تعمد المؤمن عليه إصابة نفسه .
2 - إذا حدثت الإصابة بسبب سوء سلوك فاحش ومقصود من جانب المصاب .
ويعتبر فى حكم ذلك :
كل فعل يأتيه المصاب تحت تأثير الخمر أو المخدرات .
كل مخالفة صريحة لتعليمات الوقاية المعلقة فى أمكنة ظاهرة فى محل العمل .
وذلك كله ما لم ينشأ عن الإصابة وفاة المؤمن عليه أو تخلف عنها عجز مستديم تزيد نسبته على ( 25٪ ) من العجز الكامل .
ولا يجوز التمسك بإحدى الحالتين ( 1 و 2 ) إلا إذا ثبت ذلك من التحقيق الذى يجرى فى هذا الشأن وفقا لحكم المادتين ( 61 ، 62 ) من هذا القانون .$m254$,'4a6217f63c765f047c48968f7aebc0fa',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(58,0,1,$m254$يجوز لكل من المصاب وجهة العلاج والهيئة طلب إعادة الفحص الطبى مرة كل ستة أشهر خلال السنة الأولى من تاريخ ثبوت العجز ، ومرة كل سنة خلال الثلاث سنوات التالية ، وعلى جهة العلاج أن تعيد تقدير درجة العجز فى كل مرة .
ومع عدم الإخلال بحق المصاب فى العلاج والرعاية الطبية ، لا يجوز إعادة تقدير درجة العجز بعد انتهاء أربع سنوات من تاريخ ثبوته .
واستثناء من حكم الفقرة السابقة تحدد اللائحة التنفيذية لهذا القانون الحالات التى يثبت طبيا حاجتها لإطالة مدة إعادة تقدير درجة العجز ، ويسرى ذلك على الحالات السابقة مع عدم صرف فروق مالية عن الفترة السابقة .$m254$,'289ba1ba66baa2a6971bd5cbf20f116c',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(59,0,1,$m254$يراعى فى حالة تعديل نسبة العجز عند إعادة الفحص الطبى وفقا لحكم المادة ( 58 ) من هذا القانون القواعد الآتية :
1 - إذا كان المؤمن عليه صاحب معاش ، يعدل معاش العجز اعتبارا من أول الشهر التالى لثبوت درجة العجز الأخيرة أو يوقف تبعا لما يتضح من إعادة الفحص الطبى وذلك وفقا لما يطرأ على درجة العجز زيادة أو نقصا ، وإذا نقصت درجة العجز عن ( 35٪ ) أوقف صرف المعاش نهائيا ويمنح المصاب تعويضا من دفعة واحدة وفقا لأحكام المادة ( 53 ) من هذا القانون .
2 - إذا كان المؤمن عليه قد سبق أن عوض عن درجة العجز الثابتة أولا تعويضا من دفعة واحدة يراعى ما يأتى :
( أ ) إذا كانت درجة العجز المقدرة عند إعادة الفحص تزيد على الدرجة المقدرة من قبل وتقل عن ( 35٪ ) ، استحق المصاب تعويضا محسوبا على أساس النسبة الأخيرة والأجر عند ثبوت العجز فى المرة الأولى مخصوما منه التعويض السابق صرفه ، ولا يترتب على نقصان نسبة العجز عن النسبة المقدرة من قبل أى آثار .
( ب ) إذا كانت درجة العجز المقدرة عند إعادة الفحص تبلغ ( 35٪ ) أو أكثر ، استحق المصاب معاش العجز محسوبا وفقا لأحكام المادة ( 52 ) من هذا القانون على أساس الأجر عند ثبوت العجز فى المرة الأولى ، ويصرف إليه هذا المعاش اعتبارا من أول الشهر التالى لتاريخ ثبوت درجة العجز الأخيرة مخصوما منه الفرق بين التعويض السابق صرفه إليه وقيمة المعاش ، بافتراض استحقاقه له على أساس درجة العجز المقدرة فى المرة الأولى ، وذلك فى الحدود المشار إليها بالمادة ( 133 ) من هذا القانون .$m254$,'a4815a32bbfec71e98c604bf6529d37a',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(60,0,1,$m254$يوقف صرف معاش العجز اعتبارا من أول الشهر التالى للتاريخ المحدد لإعادة الفحص الطبى وذلك إذا لم يتقدم صاحبه لإعادة الفحص الذى تطلبه جهة العلاج أو الهيئة فى الموعد الذى تخطره به .
ويستمر وقف صرف المعاش إلى أن يتقدم صاحبه لإعادة الفحص ، فإذا أسفرت إعادة الفحص عن نقصان درجة العجز عن النسبة السابق تقديرها ، اعتبرت النسبة الجديدة أساسا للتسوية اعتبارا من التاريخ الذى كان محددا لإعادة الفحص الطبى .
ويجوز للهيئة أن تتجاوز عن تخلف المصاب عن إعادة الفحص الطبى إذا قدم أسبابا مقبولة .
ويتبع فى صرف المستحق عن مدة الوقف ما تسفر عنه نتيجة إعادة الفحص الطبى .$m254$,'67c4da55cea55ebe901d7a05ad9e8eec',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(61,0,1,$m254$يلتزم صاحب العمل فى القطاع الخاص أو المسئول الفعلى عن الإدارة لديه بإبلاغ الشرطة عن كل حادث يقع لأحد عماله يعجزه عن العمل وذلك خلال 48 ساعة من تاريخ تغيبه عن العمل ، ويكون البلاغ مشتملا على اسم المصاب وعنوانه وموجز عن الحادث وظروفه والعضو المصاب والجهة التى نقل إليها المصاب لعلاجه .
ويكتفى بمحضر تحقيق إدارى يجرى بمعرفة السلطة المختصة لدى صاحب العمل فى حالة وقوع الحادث داخل دائرة العمل وذلك بالنسبة للمؤمن عليهم المشار إليهم فى البندين ( 1 ، 2 ) من أولا من المادة ( 2 ) من هذا القانون .$m254$,'99a268bec3e4b4eec4079f49c0197a97',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(62,0,1,$m254$تجرى الجهة القائمة بأعمال التحقيق تحقيقا من صورتين فى كل بلاغ ، ويبين فى التحقيق ظروف الحادث بالتفصيل وأقوال الشهود إن وجدوا ، كما يوضح بصفة خاصة ما إذا كان الحادث نتيجة عمد أو سوء سلوك فاحش ومقصود من جانب المصاب طبقا لأحكام المادة ( 57 ) من هذا القانون ، وتبين فيه كذلك أقوال صاحب العمل أو مندوبه وأقوال المصاب إذا سمحت حالته بذلك ، وعلى هذه الجهة موافاة الهيئة بصورة من التحقيق وللهيئة طلب استكمال التحقيق إذا رأت محلا لذلك .$m254$,'746905acd5bcfee47508248d681d862d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(63,0,1,$m254$على صاحب العمل أن يقدم الإسعافات الأولية للمصاب ولو لم تمنعه الإصابة من مباشرة عمله .
وعلى صاحب العمل الذى يستخدم أحد المؤمن عليهم بالبنود ( 3 ، 4 ، 5 ) من أولا من المادة ( 2 ) من هذا القانون أو المسئول الفعلى عن الإدارة لديه إخطار الهيئة على النموذج الذى تعده لهذا الغرض عن كل إصابة عمل تقع بين عماله فور وقوعها ، وأن يسلم المصاب عند نقله لمكان العلاج أو لمرافقه صورة من هذا الإخطار .$m254$,'ee6c5f59eb5714f5108c1e12a6314585',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(64,0,1,$m254$تلتزم الجهة المختصة بجميع الحقوق المقررة وفقا لأحكام هذا الباب حتى ولو كانت الإصابة تقتضى مسئولية شخص آخر خلاف صاحب العمل دون إخلال بما يكون للمؤمن عليه من حق قبل الشخص المسئول .$m254$,'289f809ca1e154a24917d234c212c27a',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(65,0,1,$m254$تلتزم الجهة المختصة بالحقوق التى يكفلها هذا الباب لمدة سنة ميلادية من تاريخ انتهاء خدمة المؤمن عليه وذلك إذا ظهرت عليه أعراض مرض مهنى خلالها ، سواء كان بلا عمل أو كان يعمل فى صناعة لا ينشأ عنها هذا المرض .
ويستمر هذا الالتزام بالنسبة للأمراض التى لا تظهر أعراضها إلا بعد انقضاء المدة المشار إليها والتى تحددها اللائحة التنفيذية لهذا القانون بعد أخذ رأى الهيئة المعنية بالتأمين الصحى .$m254$,'d631e406f711ca07224efe9f7fa7d62e',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(66,0,1,$m254$لا يجوز المصاب أو المستحقين عنه التمسك ضد الهيئة بالتعويضات التى تستحق عن الإصابة طبقا لأى قانون آخر .
كما لا يجوز لهم ذلك أيضا بالنسبة لصاحب العمل إلا إذا كانت الإصابة قد نشأت عن خطأ من جانبه .$m254$,'ec015f485f978e26c2b8e7c7eec5dfb5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(67,0,1,$m254$لا ينتفع المؤمن عليه بأحكام العلاج والرعاية الطبية وتعويض الأجر طوال مدة إعارته أو انتدابه خارج البلاد .$m254$,'98f60925c263d55da93aaffb94bdb73d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(68,0,1,$m254$لرئيس الهيئة بقرار يصدره بناء على اقتراح مجلس الإدارة تعديل الجدول رقم ( 1 ) المرافق لهذا القانون بإضافة حالات جديدة إليه ، ويسرى هذا التعديل على الوقائع السابقة لصدوره .$m254$,'3ddf226e00a73656bbee9511b36a6abc',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(69,0,1,$m254$يجمع المؤمن عليه أو صاحب المعاش أو المستحقون بين المعاشات المقررة فى تأمين إصابات العمل والأجر أو الحقوق الأخرى المقررة بهذا القانون وفقا لما يأتى :
1 - يجمع المؤمن عليه بين معاش الإصابة وأجره دون حدود .
2 - يجمع المؤمن عليه بين معاش الإصابة وتعويض البطالة دون حدود .
3 - يجمع المؤمن عليه أو صاحب المعاش أو المستحقون بين معاش الإصابة والمعاش المنصوص عليه فى تأمين الشيخوخة والعجز والوفاة وذلك دون حدود .$m254$,'e79a570dcc951f078dc013a39680465e',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(70,0,1,$m254$مع عدم الإخلال بأحكام قانون نظام التأمين الصحى الشامل الصادر بالقانون رقم 2 لسنة 2018 يمول تأمين المرض مما يأتى :
1 - الاشتراكات الشهرية للمؤمن عليهم المشار إليهم بالمادة ( 2 ) من هذا القانون وتشمل :
( أ ) حصة صاحب العمل وتقدر على النحو الآتى :
1 - ( 3٪ ) من أجور المؤمن عليهم المشار إليهم بالبندين ( 1 ، 2 ) من البند ( أولا ) من المادة ( 2 ) من هذا القانون وذلك للعلاج والرعاية الطبية ، وتلتزم الجهات المشار إليها بأداء تعويض الأجر ومصاريف الانتقال المنصوص عليها فى هذا الباب .
2 - ( 3.25٪ ) من أجور المؤمن عليهم المنصوص عليهم بالبنود ( 3 ، 4 ، 5 ) من البند أولا من المادة ( 2 ) من هذا القانون .
( ب ) حصة المؤمن عليهم وتقدر على النحو الآتى :
1 - ( 1٪ ) من الأجور بالنسبة للعاملين .
2 - ( 4٪ ) من فئة دخل أو أجر الاشتراك الشهرى للمؤمن عليهم من الفئات المشار إليها بالبنود ثانيا ورابعا من المادة ( 2 ) من هذا القانون .
3 - ( 1٪ ) من المعاش بالنسبة لأصحاب المعاشات المنتفعين بأحكام العلاج والرعاية الطبية الواردة فى هذا الباب .
4 - ( 2٪ ) من المعاش بالنسبة للمستحقين المنتفعين بأحكام العلاج والرعاية الطبية الواردة فى هذا الباب .
وتوزع نسب اشتراكات تأمين المرض وفقا للآتى :
( 4٪ ) للعلاج والرعاية الطبية لغير أصحاب المعاشات .
( 0.25٪ ) لأداء تعويض الأجر ومصاريف الانتقال للمؤمن عليهم المنصوص عليهم بالبنود ( 3 ، 4 ، 5 ) من البند أولا من المادة ( 2 ) من هذا القانون ، ويجوز لرئيس الهيئة أن يعفى صاحب العمل من أداء هذا الاشتراك مقابل التزامه بأداء تعويض الأجر ومصاريف الانتقال .
ويجوز لصاحب العمل علاج المريض ورعايته طبيا بتصريح من الهيئة المعنية بالتأمين الصحى وفقا للشروط والأوضاع التى يتضمنها القرار المنصوص عليه بالمادة ( 48 ) من هذا القانون وذلك مقابل تخفيض نسبة الاشتراكات المخصصة للعلاج والرعاية الطبية إلى ( 1٪ ) من أجور المؤمن عليهم يتحملها صاحب العمل بالإضافة إلى نسبة الاشتراكات المخصصة لتعويض الأجر ومصاريف الانتقال والمحددة بواقع ( 0.25٪ ) من أجور المؤمن عليهم .
2 - ريع استثمار أموال هذا التأمين .$m254$,'755cb140a90ed7c7b1bbeaa514a9369e',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(71,0,1,$m254$تسرى أحكام هذا الباب تدريجيا على المؤمن عليهم الذين يصدر بتحديدهم قرار من رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى ، وذلك دون الإخلال بحقوق المؤمن عليهم الذين انتفعوا بتأمين المرض وفقا لأحكام قانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975
وتحدد اللائحة التنفيذية لهذا القانون قواعد وإجراءات تحصيل الاشتراكات وتوريدها للهيئة بالنسبة للمؤمن عليهم من الفئات المشار إليها بالبنود ثانيا ورابعا من المادة ( 2 ) من هذا القانون .$m254$,'ece36b4647362a408665a791ee61f430',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(72,0,1,$m254$تسرى أحكام هذا الباب على فئات أصحاب المعاشات والمستحقين وفقا للقواعد والأولويات التى يصدر بها قرار من رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى بعد الاتفاق مع رئيس الهيئة ، وذلك دون الإخلال بحقوق فئة أصحاب المعاشات والمستحقين الذين انتفعوا بتأمين المرض وفقا لأحكام قانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975$m254$,'3c2e989bf2ef977db6c3b43f3fadd45d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(73,0,1,$m254$يشترط لانتفاع المريض بمزايا هذا التأمين أن يكون مشتركا فيه لمده ثلاثة أشهر متصلة أو ستة أشهر متقطعة بحيث يكون الشهران الأخيران متصلين ، ويدخل فى حساب هذه المدة مدد انتفاعه بمزايا العلاج التى يقدمها صاحب العمل على نفقته .
ولا يسرى الشرط المنصوص عليه فى الفقرة السابقة على الفئات المشار إليها بالبندين ( 1 ، 2 ) من البند أولا من المادة ( 2 ) من هذا القانون ، كما لا يسرى فى شأن أصحاب المعاشات .$m254$,'b535d25fbee4997e30288fa1fe2f5ffe',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(74,0,1,$m254$مع عدم الإخلال بأحكام قانون نظام التأمين الصحى الشامل الصادر بالقانون رقم ( 2 ) لسنة 2018 ، يوقف سريان أحكام هذا التأمين خلال المدد الآتية :
1 - مدة عمل المؤمن عليه لدى جهة لا تخضع لهذا التأمين .
2 - مدة التجنيد الإلزامى والاستبقاء والاستدعاء للقوات المسلحة .
3 - مدد الإجازات الخاصة والإعارات والإجازات الدراسية والبعثات العلمية ، التى يقضيها المؤمن عليه خارج البلاد .$m254$,'c1a38e087ce5b2b32c81f3e73d123e37',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(75,0,1,$m254$تتولى الهيئة المعنية بالتأمين الصحى علاج المصاب أو المريض ورعايته طبيا إلى أن يشفى أو يثبت عجزه ، وللهيئة الحق فى ملاحظة المصاب أو المريض حيثما يجرى علاجه .
ويقصد بالعلاج والرعاية الطبية ما هو منصوص عليه فى المادة ( 47 ) من هذا القانون ، وكذلك الرعاية الطبية والعلاج للمؤمن عليهن أثناء الحمل والولادة .$m254$,'241be74ff5259e4e4bceb1115b933506',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(76,0,1,$m254$إذا حال المرض بين المؤمن عليه وبين أداء عمله ، تلتزم الجهة المختصة بصرف تعويض الأجر أن تؤدى له خلال فترة مرضه تعويضا يعادل ( 75٪ ) من أجره اليومى المسدد عنه الاشتراكات لمدة تسعين يوما ويزاد بعدها إلى ما يعادل ( 85٪ ) من الأجر المذكور .
ويشترط ألا يقل التعويض فى جميع الأحوال عن الحد الأدنى المقرر قانونا للأجر .
ويستمر صرف التعويض طوال مدة مرضه أو حتى ثبوت العجز الكامل أو حدوث الوفاة بحيث لا تجاوز مدة 180 يوما فى السنة الميلادية الواحدة .
واستثناء من الأحكام المتقدمة ، يمنح المريض بأحد الأمراض المزمنة تعويضا يعادل أجر الاشتراك طوال مدة مرضه إلى أن يشفى أو تستقر حالته استقرارا يمكنه من العودة إلى مباشرة عمله أو يتبين عجزه عجزا كاملا .
ويجوز للجهة الملتزمة بتعويض الأجر أن تقرر وقف صرفه عن المدة التى يخالف فيها المؤمن عليه تعليمات العلاج .
وعلى وحدات الجهاز الإدارى للدولة والهيئات العامة ووحدات القطاع العام ووحدات قطاع الأعمال العام تنفيذ هذا النص دون حاجة إلى صدور قرار رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى المشار إليه فى المادة ( 70 ) من هذا القانون .$m254$,'dd3c20664e3883b77e596a7a8701d346',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(77,0,1,$m254$تستحق المؤمن عليها فى حالة الحمل والوضع تعويضا عن الأجر يعادل ( 75٪ ) من الأجر المشار إليه فى الفقرة الأولى من المادة ( 76 ) من هذا القانون تؤديه الجهة المختصة بصرف تعويض الأجر ، وذلك عن مدة إجازة الحمل والوضع المنصوص عليها بقانون الطفل أو بقانون العمل أو بأنظمة العاملين المدنيين بالدولة أو بالقطاع العام أو بقطاع الأعمال العام بحسب الأحوال ، بشرط ألا تقل مدة اشتراكها فى التأمين عن عشرة أشهر .$m254$,'db73197b6763ecd135b350e46cc7d2ec',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(78,0,1,$m254$تتحمل الجهة المختصة بصرف تعويض الأجر مصاريف انتقال المريض بوسائل الانتقال العادية من محل الإقامة إلى مكان العلاج إذا كان يقع خارج المدينة التى يقيم بها ، وبوسائل الانتقال الخاصة متى قرر الطبيب المعالج أن حالة المريض الصحية لا تسمح باستعماله وسائل الانتقال العادية .
وتتبع فى تنظيم الانتقال ومصاريفه القواعد التى يصدر بها قرار من رئيس الهيئة بناء على موافقة مجلس الإدارة .
وفى جميع الأحوال ، لا تسرى أحكام تعويض الأجر ومصاريف الانتقال على أصحاب المعاشات أو المستحقين .$m254$,'5117ea74f51c8482247fbd27c69cdce6',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(79,0,1,$m254$لا تخل أحكام هذا التأمين بما قد يكون للمصاب أو المريض من حقوق مقررة بمقتضى القوانين أو اللوائح أو النظم الخاصة أو العقود المشتركة أو الاتفاقيات أو غيرها فيما يتعلق بتعويض الأجر ومستويات الخدمة وذلك بالنسبة للقدر الزائد عن الحقوق المقررة فى هذا التأمين .$m254$,'8f5c9bd9fe514dd510ac0375e725ea94',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(80,0,1,$m254$مع مراعاة أحكام المادة ( 47 ) من هذا القانون ، يكون علاج المصاب أو المريض ورعايته طبيا فى جهات العلاج التى تحددها لهم الهيئة المعنية بالتأمين الصحى ، ولا يجوز لهذه الهيئة أن تجرى ذلك العلاج أو تقدم الرعاية الطبية فى العيادات أو المصحات النوعية أو المستشفيات العامة أو المراكز المتخصصة إلا بمقتضى اتفاقيات خاصة تعقد لهذا الغرض ، ويحدد فى هذه الاتفاقيات الحد الأدنى لمستويات الخدمة الطبية وأجرها ، ولا يجوز أن يقل مستوى الخدمة الطبية فى هذه الحالة عن الحد الأدنى الذى يصدر به قرار من رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى بالاتفاق مع رئيس الهيئة .$m254$,'4bfc6f640199c27e984aeea47b1116ca',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(81,0,1,$m254$تلتزم الهيئة المعنية بالتأمين الصحى بفحص العاملين المعرضين للإصابة بأحد الأمراض المهنية المبينة فى الجدول رقم ( 1 ) المرافق لهذا القانون ، وذلك مقابل تحصيلها مقابل خدمة مقداره خمسون جنيها عن كل مؤمن عليه معرض للإصابة بالأمراض المذكورة ويتحمل به صاحب العمل .$m254$,'800839bfab2a652242b0cf5422ea0ec1',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(82,0,1,$m254$تلتزم جهة العلاج بإخطار المصاب أو المريض بانتهاء العلاج وبما يكون قد تخلف لديه من عجز ونسبته ، وللمريض أن يطلب إعادة النظر فى تقرير انتهاء العلاج أو تخلف العجز وفقا لأحكام التحكيم الطبى المنصوص عليه فى المادة ( 140 ) من هذا القانون .
كما تلتزم جهة العلاج بالإخطار المشار إليه فى الفقرة السابقة بالنسبة لكل من صاحب العمل والهيئة مع بيان أيام التخلف عن العلاج إن وجدت ، وذلك كله وفقا للشروط والأوضاع التى يصدر بها قرار من رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى بالاتفاق مع رئيس الهيئة .
ويكون قرار جهة العلاج بمدة الإجازة المرضية ملزما لصاحب العمل .$m254$,'17a65b3ea1dca871db7a753110bd15d3',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(83,0,1,$m254$تثبت حالات العجز المنصوص عليها فى هذا القانون بشهادة من الهيئة المعنية بالتأمين الصحى ، يحدد بياناتها قرار من رئيس الهيئة بناء على موافقة مجلس الإدارة .
ويكون للهيئة المعنية بالتأمين الصحى أن تفوض المجالس الطبية فى إثبات حالات العجز المشار إليها .
وفى حالة تعارض قرار الهيئة المعنية بالتأمين الصحى مع قرار مجلس طبى آخر مختص ، يرفع الأمر إلى لجنة يصدر بتشكيلها وتنظيم عملها قرار من رئيس الهيئة بالاتفاق مع رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى ، ويكون قرارها فى هذه الحالة ملزما للجانبين .$m254$,'a7dbda8c3a399e7a34ddaa8a206c804f',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(84,0,1,$m254$يصدر رئيس مجلس إدارة الهيئة المعنية بالتأمين الصحى بالاتفاق مع رئيس الهيئة القرارات المنفذة لأحكام هذا الباب ، إلا فيما ورد فيه نص خاص .$m254$,'471984ba9014803feda404d48730ff87',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(85,0,1,$m254$تسرى أحكام هذا الباب على المؤمن عليهم المنصوص عليهم فى البنود ( 2 ، 3 ) من أولا من المادة ( 2 ) من هذا القانون ، ويستثنى من ذلك العاملون الذين يستخدمون فى أعمال عرضية أو مؤقتة وعلى الأخص عمال المقاولات وعمال التراحيل والعمال الموسميين وعمال الشحن والتفريغ وعمال النقل البرى وعمال الزراعة وعمال الصيد .
ويشترط للانتفاع بهذا التأمين ألا تجاوز سن المؤمن عليه الستين .$m254$,'f18797aef239cb5a1ac95bbeec838151',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(86,0,1,$m254$يمول تأمين البطالة مما يأتى :
1 - الحصة التى يلتزم بها صاحب العمل بواقع ( 1٪ ) من أجور المؤمن عليهم لديه شهريا .
2 - ريع استثمار أموال هذا التأمين .$m254$,'74b54cc6598bbef5f262b679c0675866',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(87,0,1,$m254$يشترط لاستحقاق تعويض البطالة ما يأتى :
1 - ألا يكون المؤمن عليه قد استقال من الخدمة ، ويعتبر فى حكم ذلك حالات الانقطاع عن العمل .
2 - ألا تكون قد انتهت خدمة المؤمن عليه نتيجة لحكم نهائى فى جناية أو جنحة ماسة بالشرف أو الأمانة أو الآداب العامة ، أو انتحاله شخصية غير صحيحة أو تقديمه شهادات أو أوراق مزورة .
3 - أن يكون المؤمن عليه مشتركا فى هذا التأمين لمدة سنة على الأقل منها الستة أشهر السابقة على كل تعطل متصلة .
4 - أن يكون المؤمن عليه قد قيد اسمه فى سجل المتعطلين بمكتب القوى العاملة المختص ، وأن يتردد على مكتب القوى العاملة المسجل فيه اسمه فى المواعيد التى تحدد بقرار من وزير القوى العاملة .$m254$,'4c5fe9a5cf347780fa07b07c7282265a',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(88,0,1,$m254$يستحق تعويض البطالة ابتداء من اليوم الثامن لتاريخ انتهاء الخدمة أو عقد العمل بحسب الأحوال .
ويستمر صرف التعويض إلى اليوم السابق لتاريخ التحاق المؤمن عليه بعمل أو لمدة 12 أسبوعا أيهما أسبق ، وتمتد هذه المدة إلى 28 أسبوعا عند تعطل المؤمن عليه للمرة الأولى إذا كانت مدة الاشتراك فى هذا التأمين تجاوز 36 شهرا .
كما يصرف التعويض خلال فترة التدريب المهنى التى يقررها مكتب القوى العاملة .$m254$,'04b59a47a125c32704c273fb275ccb5c',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(89,0,1,$m254$يقدر تعويض البطالة للمؤمن عليه خلال مدة التعطل وفقا للنسب الآتية من أجر الاشتراك الأخير :
1 - ( 75٪ ) للأربعة أسابيع الأولى .
2 - ( 65٪ ) للأربعة أسابيع الثانية .
3 - ( 55٪ ) للأربعة أسابيع الثالثة .
4 - ( 45٪ ) لباقى الأسابيع .$m254$,'685d8593a692c8dcd2279baedc9f0546',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(90,0,1,$m254$استثناء من حكم المادة ( 89 ) من هذا القانون ، يستحق تعويض البطالة بنسبة ( 40٪ ) من أجر الاشتراك الأخير إذا انتهت خدمة المؤمن عليه لأحد الأسباب الآتية :
1 - ارتكابه خطأ نشأت عنه خسارة جسيمة لصاحب العمل ، وأبلغ عنه صاحب العمل الجهات المختصة خلال 24 ساعة من وقت علمه بوقوعه .
2 - عدم مراعاته التعليمات اللازم اتباعها لسلامة العاملين والمنشأة بشرط أن تكون هذه التعليمات مكتوبة ومعلقة فى مكان ظاهر .
3 - عدم قيامه بتأدية التزامات العمل الجوهرية .
4 - إفشاؤه الأسرار الخاصة بالعمل .
5 - وجوده أثناء العمل فى حالة سكر بين أو متأثرا بما تعاطاه من مادة مخدرة .
6 - اعتداؤه على صاحب العمل أو المدير المسئول ، وكذلك اعتداؤه اعتداء جسيما على أحد رؤسائه فى العمل أثناء العمل أو بسببه .$m254$,'22045dfdd4153a38a5c8cbecee805f1c',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(91,0,1,$m254$يسقط الحق فى صرف تعويض البطالة فى الحالات الآتية :
1 - إذا رفض المؤمن عليه الالتحاق بعمل يراه مكتب القوى العاملة المختص مناسبا له ويعتبر العمل مناسبا إذا توافرت فيه الشروط الآتية :
( أ ) أن يعادل أجره على الأقل ( 75٪ ) من الأجر الذى يؤدى على أساسه تعويض البطالة .
( ب ) أن يكون العمل متفقا مع مؤهلات المؤمن عليه وخبرته وقدراته المهنية والبدنية .
( ج ) أن يكون العمل المرشح له فى دائرة المحافظة التى كان يعمل بها وقت تعطله .
2 - إذا ثبت اشتغال المؤمن عليه لحسابه الخاص .
3 - إذا ثبت اشتغال المؤمن عليه لحساب الغير بأجر يساوى قيمة التعويض أو يزيد عليه .
4 - إذا استحق المؤمن عليه معاشا يساوى قيمة تعويض البطالة أو يزيد عليه ، مع مراعاة أحكام البند ( 2 ) من المادة ( 69 ) من هذا القانون .
5 - إذا هاجر المؤمن عليه أو غادر البلاد نهائيا .
6 - إذا بلغ المؤمن عليه سن التقاعد .$m254$,'8cbc5658147191fa507c79e773166cdb',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(92,0,1,$m254$يوقف صرف تعويض البطالة فى الحالات الآتية :
1 - إذا لم يتردد المؤمن عليه على مكتب القوى العاملة الذى قيد اسمه فيه متعطلا فى المواعيد المحددة ما لم يكن ذلك لأسباب مقبولة .
2 - إذا رفض المؤمن عليه التدريب الذى يقرره مكتب القوى العاملة المختص .
ويعود الحق فى صرف التعويض فى الحالتين السابقتين بزوال سبب الإيقاف وذلك للمدة الباقية من مدة الاستحقاق .
3 - إذا جند المؤمن عليه ويعود إليه الحق فى صرف التعويض بانتهاء مدة التجنيد ، ولا تحسب هذه المدة ضمن مدة استحقاق التعويض .
4 - إذا اشتغل المؤمن عليه لحساب الغير بأجر يقل عن قيمة تعويض البطالة .
5 - إذا استحق المؤمن عليه المتعطل معاشا يقل عن قيمة تعويض البطالة .
ويصرف فى الحالتين المنصوص عليهما فى البندين ( 4 و 5 ) ما يعادل الفرق بين تعويض البطالة المستحق والأجر أو المعاش وذلك للمدة الباقية من مدة الاستحقاق .$m254$,'913b636c2b5b4f8e92363a2159ed8c52',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(93,0,1,$m254$إذا قام نزاع على سبب انتهاء الخدمة يصرف تعويض البطالة بنسبة ( 40٪ ) من الأجر الأخير لمدة أربعة أسابيع يبدى خلالها مكتب علاقات العمل المختص رأيه فى النزاع وفقا للإجراءات التى يبينها قرار من رئيس الهيئة بالاتفاق مع وزير القوى العاملة .
وفى ضوء النتيجة التى ينتهى إليها المكتب المذكور من ظاهر الأوراق يتم الآتى :
1 - صرف التعويض المستحق متى توافرت باقى الشروط المنصوص عليها فى هذا الباب .
2 - استرداد ما سبق صرفه للمؤمن عليه إذا ثبت عدم استحقاقه للتعويض .$m254$,'2700d0b47f5682867b1377b24b5db9a0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(94,0,1,$m254$تسرى أحكام هذا الباب على أصحاب المعاشات الذين يصدر بتحديدهم قرار من رئيس الهيئة بعد موافقة مجلس الإدارة .$m254$,'9904f5e658af820d6edddf016b7018af',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(95,0,1,$m254$ينشأ فى الصندوق المشار إليه بالمادة ( 5 ) من هذا القانون حساب للرعاية الاجتماعية لأصحاب المعاشات ، وتتكون أمواله من الموارد الآتية :
1 - ما قد يخصصه صندوق التأمين الاجتماعى لصالح حساب الرعاية الاجتماعية لأصحاب المعاشات والتى يحددها مجلس إدارة الهيئة .
2 - ما قد تخصصه الخزانة العامة للدولة لصالح حساب الرعاية الاجتماعية لأصحاب المعاشات .
3 - عائد استثمار أموال واحتياطيات حساب الرعاية الاجتماعية لأصحاب المعاشات .
4 - نسبة ( 30٪ ) مما يقضى به من غرامات وفقا لأحكام هذا القانون .
5 - التبرعات والهبات والمنح التى يقبلها مجلس الإدارة .
6 - أى موارد أخرى تخصص لهذا الصندوق .$m254$,'8ac523e87f44c70d3340684878c9b838',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(96,0,1,$m254$يختص مجلس الإدارة باقتراح الأنشطة والخدمات المختلفة التى يتم تقديمها لأصحاب المعاشات ووضع الضوابط والشروط للانتفاع بها ، وعلى الأخص ما يلى :
1 - المساعدة فى توصيل المعاشات إلى المنازل للمرضى والعاجزين وكبار السن من أصحاب المعاشات والمستحقين عنهم .
2 - توفير الوسائل الترفيهية كالرحلات ومشاهدة عروض المسارح والإقامة فى المصايف والمشاتى وزيارة الحدائق العامة .
3 - الاتفاق مع الجهات المختلفة للحصول على مزايا وخدمات لأصحاب المعاشات وتفعيل القوانين والقرارات الخاصة بالحقوق والمزايا الإضافية لأصحاب المعاشات .
4 - أى أنشطة اجتماعية إضافية أخرى تحددها اللائحة التنفيذية لهذا القانون .$m254$,'021c25d7a248e075d59ccf37145506a3',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(97,0,1,$m254$يصدر رئيس مجلس الوزراء بناء على عرض رئيس الهيئة قرارا بمنح أصحاب المعاشات المنتفعين بأحكام هذا الباب تيسيرات خاصة ، وعلى الأخص ما يأتى :
1 - تخفيض نسبى فى تعريفة المواصلات بالسكك الحديدية ، وكذا وسائل المواصلات العامة المملوكة للدولة داخل المدن .
2 - تخفيض فى أسعار دخول النوادى والمتاحف والمعارض ودور السينما والمسارح المملوكة للدولة .
3 - تخفيض نفقات الإقامة فى دور العلاج التابعة للجهاز الإدارى للدولة .
4 - تخفيض نفقات الرحلات التى ينظمها الجهاز الإدارى للدولة أو الهيئات العامة أو المؤسسات العامة أو الوحدات الاقتصادية التابعة لأى منها داخل الجمهورية وخارجها .
ويكون التخفيض فى جميع الأحوال بما لا يجاوز ( 75٪ ) من القيمة الرسمية .
5 - أولويات فى التسهيلات التى يقررها مجلس إدارة شركة مصر للطيران بالنسبة لأجور السفر بطائراتها .
6 - أولويات فى التيسيرات التى تقدمها الهيئة العامة لبنك ناصر الاجتماعى والبنوك والجهات الأخرى .$m254$,'102925b46e7c4a2a6d54d11119dd2dc0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(98,0,1,$m254$إذا توفى المؤمن عليه أو صاحب المعاش كان للمستحقين عنه الحق فى تقاضى معاش وفقا للأنصبة المقررة بالجدول رقم ( 7 ) المرافق لهذا القانون من أول الشهر الذى حدثت فيه الوفاة .
ويقصد بالمستحقين الأرملة والأرمل والأبناء والبنات والوالدان والإخوة والأخوات الذين تتوافر فيهم فى تاريخ وفاة المؤمن عليه أو صاحب المعاش شروط الاستحقاق المنصوص عليها فى هذا الباب .$m254$,'e37351f919e81abd5b8131f4dcbd00fa',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(99,0,1,$m254$يشترط لاستحقاق الأرملة والأرمل أن يكون الزواج موثقا أو ثابتا بحكم قضائى بات ، وألا يكون الأرمل متزوجا بأخرى .
وتحدد اللائحة التنفيذية لهذا القانون الحالات التى يقبل فيها إثبات الزواج بغير الوسائل المحددة بالفقرة السابقة ووسائل هذا الإثبات .$m254$,'1ab9002afe2103e6b0349d465ab911ae',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(100,0,1,$m254$يشترط لاستحقاق الابنة ألا تكون متزوجة .
ويشترط لاستحقاق الابن ألا يكون قد بلغ سن الحادية والعشرين ، ويستثنى من هذا الشرط الحالات الآتية :
1 - العاجز عن الكسب .
2 - الطالب بإحدى مراحل التعليم التى لا تجاوز مرحلة الحصول على مؤهل الليسانس أو البكالوريوس أو ما يعادلها بشرط عدم تجاوزه سن السادسة والعشرين ولم يلتحق بعمل أو لم يزاول مهنة .
3 - من حصل على مؤهل نهائى لا يجاوز المرحلة المشار إليها بالبند السابق ولم يلتحق بعمل أو لم يزاول مهنة ولم يكن قد بلغ سن السادسة والعشرين بالنسبة للحاصلين على مؤهل الليسانس أو البكالوريوس وسن الرابعة والعشرين بالنسبة للحاصلين على المؤهلات الأقل .$m254$,'fcdd39296a6f449f2f2ef2842e36f269',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(101,0,1,$m254$يشترط لاستحقاق الإخوة والأخوات بالإضافة إلى شروط استحقاق الأبناء والبنات أن يثبت إعالة المؤمن عليه أو صاحب المعاش إياهم وفقا للشروط والأوضاع التى تحددها اللائحة التنفيذية .
ويتم إعادة بحث شروط الإعالة المشار إليها بالفقرة السابقة عند كل تعديل يطرأ على حالة المعاش .$m254$,'f320d84daf2332a7ba634a9529530aa5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(102,0,1,$m254$إذا توافرت فى أحد المستحقين شروط الاستحقاق لأكثر من معاش من الهيئة ومن الخزانة العامة فلا يستحق منها إلا معاشا واحدا ، وتكون أولوية الاستحقاق وفقا للترتيب الآتى :
1 - المعاش المستحق عن نفسه .
2 - المعاش المستحق عن الزوج أو الزوجة .
3 - المعاش المستحق عن الوالدين .
4 - المعاش المستحق عن الأولاد .
5 - المعاش المستحق عن الإخوة والأخوات .
وإذا كانت المعاشات مستحقة عن مؤمن عليهم أو أصحاب معاشات من فئة واحدة فيستحق المعاش الأسبق فى الاستحقاق .
وإذا نقص المعاش المستحق وفقا لما تقدم عن المعاش الآخر أدى إليه الفرق من هذا المعاش .
على أن يتم تحديد مدى استحقاق الفرق من المعاش الآخر وقيمته فى ضوء تطور قيمة كل من المعاشين فى أى تاريخ لاحق إعمالا لنصوص هذا الباب ، وتحدد اللائحة التنفيذية لهذا القانون ضوابط وإجراءات تطبيق هذه المادة .$m254$,'578e52149b4dd4bb0e504ea25645667d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(103,0,1,$m254$يوقف صرف معاش المستحق فى الحالات الآتية :
1 - الالتحاق بأى عمل والحصول منه على دخل صاف يساوى قيمة المعاش أو يزيد عليه ، فإذا نقص الدخل عن المعاش صرف إليه الفرق فى تاريخ التحاقه بالعمل ثم فى يناير من كل سنة ، وتحدد اللائحة التنفيذية لهذا القانون المقصود بالدخل الصافى .
2 - مزاولة مهنة تجارية أو غير تجارية منظمة بقوانين أو لوائح لمدة تزيد على خمس سنوات متصلة أو متقطعة ، ويعود الحق فى صرف المعاش فى حالة ترك مزاولة هذه المهنة اعتبارا من أول الشهر التالى لتاريخ ترك المهنة ، وتحدد اللائحة التنفيذية لهذا القانون حالات وشروط مزاولة المهنة .$m254$,'0d1e4af504e2060cccda74418be4163e',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(104,0,1,$m254$استثناء من أحكام حظر الجمع المنصوص عليها فى المادتين ( 102 ، 103 ) يجمع المستحق بين المعاشات أو بين الدخل من العمل أو المهنة والمعاش فى الحدود الآتية :
1 - يجمع المستحق بين المعاشات فى حدود قيمة الحد الأدنى للمعاش المقرر بالفقرة الأخيرة من المادة ( 24 ) من هذا القانون ، ويكمل المعاش إلى هذا المقدار وفقا للترتيب المنصوص عليه فى المادة ( 102 ) من هذا القانون .
2 - يجمع المستحق بين الدخل والمعاش فى حدود قيمة الحد الأدنى للمعاش المقرر بالفقرة الأخيرة من المادة ( 24 ) من هذا القانون .
3 - تجمع الأرملة بين معاشها عن زوجها وبين معاشها بصفتها منتفعة بأحكام هذا القانون ، كما تجمع بين معاشها عن زوجها وبين دخلها من العمل أو المهنة وذلك دون حدود .
4 - يجمع الأرمل بين معاشه عن زوجته وبين معاشه بصفته منتفعا بأحكام هذا القانون ، كما يجمع بين معاشه عن زوجته وبين دخله من العمل أو المهنة وذلك دون حدود .
5 - يجمع الأولاد بين المعاشين المستحقين عن والديهم دون حدود .
6 - يجمع المستحق بين المعاشات المستحقة له عن شخص واحد وذلك بدون حدود .$m254$,'1826a2c8f5eb5de6a384706f244d8b95',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(105,0,1,$m254$يقطع معاش المستحق من أول الشهر التالى للشهر الذى تتحقق فيه إحدى الحالات الآتية :
1 - وفاة المستحق .
2 - زواج الأرملة أو الأرمل أو البنت أو الأخت .
3 - بلوغ الابن أو الأخ سن الحادية والعشرين ويستثنى من ذلك الحالات الآتية :
( أ ) العاجز عن الكسب حتى زوال حالة العجز .
( ب ) الطالب حتى تاريخ التحاقه بعمل أو مزاولته مهنة أو تاريخ بلوغه سن السادسة والعشرين أيهما أقرب ، ويستمر صرف معاش الطالب الذى يبلغ سن السادسة والعشرين خلال السنة الدراسية حتى نهاية تلك السنة .
( ج ) الحاصل على مؤهل نهائى حتى تاريخ التحاقه بعمل أو مزاولته مهنة أو تاريخ بلوغه سن السادسة والعشرين بالنسبة للحاصلين على الليسانس أو البكالوريوس وسن الرابعة والعشرين بالنسبة للحاصلين على المؤهلات النهائية الأقل ، أى التاريخين أقرب .
4 - توافر شروط استحقاق معاش آخر بمراعاة أحكام المادتين ( 102 ، 104 ) من هذا القانون .
وتصرف للابن أو الأخ فى حالة قطع المعاش لغير الوفاة أو استحقاق معاش ذى أولوية أعلى ، وللابنة أو الأخت فى حالة قطع المعاش للزواج ، منحة تساوى معاش سنة بحد أدنى مقداره خمسمائة جنيه ، ولا تصرف هذه المنحة إلا لمرة واحدة وتحدد اللائحة التنفيذية لهذا القانون قواعد وإجراءات صرف هذه المنحة .$m254$,'f27314b7210234985aaca852013c5165',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(106,0,1,$m254$فى حالة إيقاف أو قطع معاش أحد المستحقين كله أو بعضه يئول إلى باقى المستحقين من فئة هذا المستحق ، وفى حالة عدم وجود مستحقين آخرين من هذه الفئة يتم الرد على باقى المستحقين بالفئات الأخرى فإذا زاد نصيب المردود عليه على أقصى نصيب له بالجدول رقم ( 7 ) المرافق لهذا القانون وفقا للحالة فى تاريخ الرد رد الباقى على الفئة التالية وذلك بمراعاة الترتيب الذى يرد باللائحة التنفيذية لهذا القانون فى هذا الشأن .
وفى حالة زوال سبب إيقاف المعاش كله أو بعضه لأحد المستحقين يعاد توزيع المعاش بين جميع المستحقين فى تاريخ زوال السبب .
ويتحدد نصيب المستحق الذى يرد عليه جزء من المعاش بما لا يجاوز الحد الأقصى للنصيب المحدد بالجدول رقم ( 7 ) المرافق لهذا القانون .
وفى حالة قطع معاش الوالدين فى الحالة رقم ( 2 ) من الجدول رقم ( 7 ) المرافق يئول الباقى من نصيبهما بعد الرد على فئة الأرامل إلى الأخوة والأخوات الذين تتوافر فى شأنهم شروط استحقاق المعاش فى هذا التاريخ وذلك فى حدود الربع .
وفى حالة قطع معاش فئة الأرامل فى الحالة المشار إليها بالفقرة السابقة يئول ربع معاش المورث إلى الإخوة والأخوات الذين تتوافر فى شأنهم شروط استحقاق المعاش فى هذا التاريخ .$m254$,'1bc3cc7c148758da64fd7ffeb4a5cf08',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(107,0,1,$m254$يعاد توزيع المعاش بين المستحقين من أول الشهر التالى لتحقق إحدى الوقائع الآتية :
1 - طلاق أو ترمل البنت أو الأخت .
2 - عجز الابن أو الأخ عن الكسب .
وتتضمن اللائحة التنفيذية لهذا القانون قواعد وإجراءات تنفيذ أحكام هذا الباب .$m254$,'166ef139c81cc07ac69258ed9bb62808',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(108,0,1,$m254$تسرى أحكام هذا الباب على المستحقين عن المعاملين بقوانين المعاشات الخاصة وذلك فيما لم يرد بشأنه نص خاص .$m254$,'8e98bd96ba3da432fa6120df746f4ae0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(109,0,1,$m254$أموال صندوق التأمين الاجتماعى المشار إليه بالمادة ( 5 ) من هذا القانون أموال خاصة ، وتتمتع بجميع أوجه وأشكال الحماية المقررة للأموال العامة ، وهى وعوائدها حق للمستفيدين منها ، ويجب على الهيئة وجميع جهات الدولة أن تتعامل معها على أنها أموال خاصة ، ولا يجوز الصرف منها إلا فى الأغراض التى أنشئت من أجلها وحددت بموجب هذا القانون .$m254$,'9cebd564ba0eaef53282c722c60be40a',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(110,0,1,$m254$الحقوق التى تقرر طبقا لأحكام هذا القانون هى وحدها التى يلتزم بها صندوق التأمين الاجتماعى المشار إليه بالمادة ( 5 ) من هذا القانون ، فإذا استحق المؤمن عليه أو صاحب المعاش أو المستحقين عن أيهما زيادة عليها تطبيقا لقوانين أو قرارات خاصة ، فتلتزم الخزانة العامة بتلك الزيادة .
ويجوز للخزانة العامة تفويض الهيئة فى الصرف نيابة عنها على أن تسدد ما قامت الهيئة بصرفه وذلك خلال ثلاثين يوما من تاريخ الصرف ، وفى حالة التأخير تلتزم الخزانة العامة بسداد فائدة على المبالغ التى لم تسدد عن المدة من تاريخ الصرف حتى تاريخ السداد ، وتحسب الفائدة بواقع متوسط العائد على إصدارات الخزانة من الأذون والسندات خلال ذات المدة .$m254$,'51759be3c77ecbc1fc434ab080c1869d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(111,0,1,$m254$تلتزم الخزانة العامة بسداد قسط سنوى للهيئة بواقع 160.5 مليار جنيه ، يزاد بنسبة ( 5.7٪ ) مركبة سنويا ، ويؤدى هذا القسط لمدة خمسين سنة ، وذلك مقابل قيام صندوق التأمين الاجتماعى المنصوص عليه بالمادة ( 5 ) من هذا القانون بتحمل ما يلى :
1 - التزامات الخزانة العامة فى المعاشات المستحقة حتى تاريخ العمل بهذا القانون .
2 - التزامات الخزانة العامة المقررة بموجب أحكام هذا القانون المنصوص عليها فى المادتين الثانية والثالثة من قانون الإصدار ، والمواد أرقام 19 ( بند ب من البند 3 ) ، 23 ( بند 4 ) ، 27 ، 28 ( بند ج ) ، 29 ، 35 ، 159 ، 163 من هذا القانون .
3 - مساهمة الخزانة العامة بالنسبة للفئات المشار إليها بالبند رابعا من المادة ( 2 ) من هذا القانون .
4 - المبالغ المودعة لحساب صندوقى التأمين الاجتماعى لدى بنك الاستثمار القومى فى تاريخ العمل بأحكام هذا القانون .
5 - مبالغ الصكوك التى صدرت من وزارة المالية لصندوقى التأمين الاجتماعى قبل تاريخ العمل بأحكام هذا القانون .
6 - كامل المديونية المستحقة على الخزانة العامة لصندوقى التأمين الاجتماعى قبل تاريخ العمل بأحكام هذا القانون .
7 - العجز الإكتوارى فى نظام التأمين الاجتماعى الحالى فى تاريخ العمل بهذا القانون . ولا يشمل القسط السنوى المشار إليه ما يلى :
1 - المعاشات الاستثنائية المقررة بقرار رئيس الجمهورية بالقانون رقم 71 لسنة 1964 والتى تتقرر اعتبارا من تاريخ العمل بهذا القانون .
2 - أى مزايا إضافية تتقرر بعد تاريخ العمل بهذا القانون وتتحمل بها الخزانة العامة سواء بزيادة المزايا أو استحداث مزايا إضافية لبعض الفئات .
وعلى الخزانة العامة بعد انتهاء مدة الخمسين سنة المنصوص عليها بالفقرة الأولى من هذه المادة أداء المستحقات المالية المقررة وفقا لأحكام هذا القانون إلى الهيئة .
ويصدر قرار من رئيس مجلس الوزراء بناء على عرض وزير المالية والوزير المختص بالتأمينات الاجتماعية بقواعد وأحكام تنفيذ هذه المادة .$m254$,'aad56464ea6ef43dbed30b8a7d0ff5ec',DATE '2019-08-20',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. يُعمل بالمواد 111 إلى 114 من اليوم التالى لتاريخ النشر (المادة 7 من قانون الإصدار)، وتاريخ بدء السريان هنا 2019-08-20 على فرض أن النشر فى 19 أغسطس 2019.$m254$),
(112,0,1,$m254$يعاد النظر فى مدى كفاية قيمة القسط المستحق على الخزانة العامة بعد ثلاثين عاما من تاريخ العمل بهذا القانون ، وذلك من خلال إعداد دراسة مالية وإكتوارية لنظام التأمين الاجتماعى بمعرفة لجنة الخبراء ، وإذا انتهت الدراسة إلى زيادة قيمة القسط يتم اتخاذ الإجراءات التشريعية اللازمة لتنفيذ ذلك .$m254$,'4ea0791afd742dadf265e083bb28889c',DATE '2019-08-20',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. يُعمل بالمواد 111 إلى 114 من اليوم التالى لتاريخ النشر (المادة 7 من قانون الإصدار)، وتاريخ بدء السريان هنا 2019-08-20 على فرض أن النشر فى 19 أغسطس 2019.$m254$),
(113,0,1,$m254$تلتزم الخزانة العامة بسداد القسط السنوى المشار إليه بالمادة ( 112 ) من هذا القانون بواقع جزء من اثنى عشر جزءا خلال السنة المستحق عنها القسط ، على أن يتم سداد جزء القسط المستحق خلال شهر الاستحقاق بما لا يجاوز نهايته ، وفى حالة التأخير تلتزم الخزانة العامة بسداد فائدة على المبالغ التى لم تسدد عن المدة من تاريخ الصرف حتى تاريخ السداد ، وتحسب الفائدة بواقع متوسط العائد على إصدارات الخزانة من الأذون والسندات خلال ذات المدة .
وفى حالة التأخير عن السداد لمدة ثلاثة أشهر متصلة ، يلتزم رئيس الهيئة بعرض الأمر على مجلس الوزراء لاتخاذ ما يلزم فى هذا الشأن .$m254$,'bd8e1cba60e326d0639c3a5892c71fbf',DATE '2019-08-20',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. يُعمل بالمواد 111 إلى 114 من اليوم التالى لتاريخ النشر (المادة 7 من قانون الإصدار)، وتاريخ بدء السريان هنا 2019-08-20 على فرض أن النشر فى 19 أغسطس 2019.$m254$),
(114,0,1,$m254$مع عدم الإخلال بأحكام المادة ( 113 ) من هذا القانون تلتزم الخزانة العامة عند عرض مشروع قانون الموازنة العامة على مجلس النواب بتقديم تقرير يفيد قيام الخزانة العامة بأداء المبالغ المنصوص عليها بالمادة ( 111 ) من هذا القانون .
ولا يجوز إقرار مشروع قانون الموازنة العامة للدولة إلا بعد إدراج المبالغ المنصوص عليها بالمادة ( 111 ) من هذا القانون فى المشروع .$m254$,'d47ec7b37f59a3b4bd423c31e8a07a30',DATE '2019-08-20',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه. يُعمل بالمواد 111 إلى 114 من اليوم التالى لتاريخ النشر (المادة 7 من قانون الإصدار)، وتاريخ بدء السريان هنا 2019-08-20 على فرض أن النشر فى 19 أغسطس 2019.$m254$),
(115,0,1,$m254$يلتزم صاحب العمل بأداء الاشتراكات المستحقة عن العاملين لديه وفقا لأحكام هذا القانون ، وتشمل الحصة التى يلتزم بها والحصة التى يلتزم باقتطاعها من أجر المؤمن عليه .
وتحسب الاشتراكات التى يؤديها صاحب العمل بالنسبة للمؤمن عليهم المشار إليهم فى أولا من المادة ( 2 ) وفقا لما يأتى :
( أ ) بالنسبة للبندين ( 1 ، 2 ) : على أساس ما يستحقه المؤمن عليه من أجر خلال كل شهر .
( ب ) بالنسبة لباقى البنود : خلال سنة ميلادية على أساس أجورهم فى شهر يناير من كل عام ، وإذا كان التحاق العامل بالخدمة بعد الشهر المذكور فتحسب الاشتراكات على أساس أجر شهر الالتحاق بالخدمة وذلك حتى يناير التالى ثم يعامل بعد ذلك على الأساس المتقدم .
ويراعى فى حساب الأجر تحديد عدد أيام العمل فى الشهر بثلاثين يوما بالنسبة لمن لايتقاضون أجورهم مشاهرة .
ولا تستحق الاشتراكات عن الشهر الذى تبدأ فيه الخدمة إلا إذا كان شهرا كاملا وتستحق الاشتراكات كاملة عن الشهر الذى تنتهى فيه الخدمة .
ويعفى المؤمن عليه وصاحب العمل من الاشتراكات المستحقة عن مدة التجنيد الإلزامى .$m254$,'600cc012b53fc9f5d15c03abe8ea2dca',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(116,0,1,$m254$مع عدم الإخلال بالحد الأدنى لأجر الاشتراك ، تحدد اللائحة التنفيذية لهذا القانون أجر اشتراك بعض فئات المؤمن عليهم وطريقة حسابه ، وطريقة حساب الاشتراكات والملتزم بها ومواعيد أدائها .$m254$,'2b8128f30bd34c5ab9d1f070d558fce1',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(117,0,1,$m254$يجوز للمؤمن عليه من الفئات المشار إليها بالبنود ثانيا وثالثا من المادة ( 2 ) من هذا القانون طلب تعديل دخل اشتراكه إلى فئة الدخل الأعلى بشرط أن يكون قد أدى جميع المبالغ المستحقة عليه حتى تاريخ تقدمه بطلب التعديل ، كما يجوز له طلب تعديل فئة دخل الاشتراك إلى فئة الدخل الأقل مباشرة بعد تقديم الأسباب المبررة لذلك ، ولا يتم التعديل إلا بعد بحث هذه الأسباب وموافقة الهيئة .
ويسرى تعديل فئة دخل الاشتراك اعتبارا من أول الشهر التالى لتاريخ تقديم طلب التعديل .
ويتعين تعديل دخل الاشتراك الشهرى للمؤمن عليهم المشار إليهم إلى فئة الدخل الأعلى التالية بعد مضى ثلاث سنوات على الأكثر على استمرار الاشتراك بفئة الدخل الأقل .
وتحدد اللائحة التنفيذية لهذا القانون الشروط والإجراءات اللازمة لتنفيذ هذه الأحكام .$m254$,'35d88f87b7094e0ac922593bdc5d5aa0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(118,0,1,$m254$يجوز للمؤمن عليه المشار إليه فى المادة ( 117 ) طلب تعديل دخل مدد اشتراكه الفعلية منذ بدء اشتراكه فى النظام إلى دخل اشتراكه فى تاريخ طلب التعديل أو إلى أى دخل أعلى ، كما يجوز له تعديل بعض فئات اشتراكه والتى تبدأ بالتتابع من أولى المدد إلى فئة أعلى . وفى جميع الأحوال ، يشترط لقبول طلب التعديل توافر الشروط الآتية :
1 - أن يكون قد أدى جميع المبالغ المستحقة عليه للهيئة حتى تاريخ تقديم طلب التعديل .
2 - أن تقرر الجهة الطبية لياقته الصحية ، وتحدد اللائحة التنفيذية لهذا القانون إجراءات تحديد الحالة الصحية للمؤمن عليه .
ويلتزم المؤمن عليه فى حالة طلب التعديل بأداء فروق الاشتراكات ومبلغ إضافى بنسبة متوسط إصدارات الخزانة من الأذون والسندات من إجمالى هذه الفروق وذلك اعتبارا من تاريخ بدء الاشتراك حتى نهاية الشهر السابق على تاريخ الأداء .
ولا يعتبر المؤمن عليه مشتركا بالدخل المعدل إلا إذا تم سداد هذه المبالغ خلال سنة من تاريخ إخطاره بتحديدها وقبل تحقق واقعة استحقاق أى من الحقوق المقررة بهذا القانون .$m254$,'b8fa5e2c560f5b17b817881f249e71c3',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(119,0,1,$m254$تستحق الاشتراكات عن المدد الآتية وذلك وفقا للقواعد والأحكام المبينة قرين كل منها :
1 - مدد الإعارات الخارجية بدون أجر ومدد الإجازات الخاصة للعمل بالخارج : يلتزم المؤمن عليه بحصته وحصة صاحب العمل فى الاشتراكات وتؤدى بإحدى العملات الأجنبية .
وتحدد اللائحة التنفيذية لهذا القانون بعد الاتفاق مع الوزير المختص نوع العملات الأجنبية ، وسعر التحويل ، وكيفية ومواعيد أداء الاشتراكات والمبالغ الإضافية التى تستحق فى حالة التأخير فى السداد ، وذلك وفقا للنسب المقررة فى المادة ( 121 ) من هذا القانون .
2 - مدد الإجازات الخاصة بدون أجر : يلتزم المؤمن عليه بحصته وحصة صاحب العمل فى الاشتراكات إذا رغب فى حسابها ضمن مدة اشتراكه فى التأمين ، وتحدد اللائحة التنفيذية لهذا القانون الأحكام المنظمة لكيفية ومواعيد إبداء الرغبة وأداء الاشتراكات والمبالغ الإضافية التى تستحق فى حالة التأخير فى الأداء ، وذلك وفقا للنسب المقررة فى المادة ( 121 ) من هذا القانون .
وإذا ثبت التحاق المؤمن عليه بعمل خلال مدة الإجازة فيتم الالتزام بسداد حصة المؤمن عليه وحصة صاحب العمل فى الاشتراكات وتحدد اللائحة التنفيذية لهذا القانون مواعيد الأداء والملتزم بها والمبالغ الإضافية وفقا للنسب المقررة فى المادة ( 121 ) من هذا القانون التى تستحق فى حالة التأخير فى الأداء .
3 - مدد الإجازات الدراسية بدون أجر : يلتزم صاحب العمل بحصته فى الاشتراكات وتؤدى فى المواعيد الدورية ويلتزم المؤمن عليه بحصته ، ويؤديها فى المواعيد المحددة باللائحة التنفيذية لهذا القانون .
4 - مدد البعثات العلمية بدون أجر : تلتزم الجهة الموفدة للبعثة بحصة صاحب العمل وحصة المؤمن عليه فى الاشتراكات وتؤدى فى المواعيد الدورية .
5 - مدد الإعارة الداخلية : تلتزم الجهة المعار إليها بحصة صاحب العمل فى الاشتراكات كما تلتزم بخصم حصة المؤمن عليه من أجره ، وتؤدى للجهة المعار منها فى المواعيد المحددة لسدادها للهيئة فى المواعيد الدورية .
ويسرى حكم هذا البند فى شأن حالات الندب الكلى .
6 - مدد الاستدعاء والاستبقاء : تلتزم الجهة التى تؤدى أجر المؤمن عليه خلال تلك المدد بحصة صاحب العمل فى الاشتراكات كما تلتزم هذه الجهة بخصم حصة المؤمن عليه من أجره وتؤدى الحصتان للهيئة فى المواعيد الدورية .$m254$,'94e16cf6d5f008a6de92710cb1c537ac',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(120,0,1,$m254$يلتزم صاحب العمل فى القطاع الخاص بأن يقدم للهيئة بيانات العاملين وأجورهم واشتراكاتهم وذلك وفق النماذج التى تعدها الهيئة وبالشروط والأوضاع المنصوص عليها فى المادة ( 127 ) من هذا القانون .
وتحسب الاشتراكات على أساس البيانات الواردة فى هذه النماذج .
فإذا لم يقدم صاحب العمل البيانات المشار إليها ، يكون حساب الاشتراكات على أساس آخر بيان قدم منه للهيئة أو طبقا لما تسفر عنه تحرياتها ، وفى تلك الحالة تلتزم الهيئة بأن تخطر صاحب العمل بقيمة الاشتراكات والمبالغ الأخرى المستحقة عليه ، ويكون لصاحب العمل الاعتراض على هذه المطالبة لدى المكتب المختص خلال ثلاثين يوما من تاريخ تسلمه الإخطار مع أداء رسم اعتراض قيمته مائة جنيه يرحل إلى الحساب المنصوص عليه فى المادة ( 150 ) من هذا القانون ، ولا يعتبر الاعتراض مقبولا إلا بعد أداء الرسم المشار إليه .
وعلى الهيئة الرد على هذا الاعتراض خلال ثلاثين يوما من تاريخ وروده إليها .
وفى حالة رفض الهيئة اعتراض صاحب العمل يكون له أن يطلب عرض النزاع على لجنة فحص المنازعات المنصوص عليها بالمادة ( 148 ) من هذا القانون ، وتعلن الهيئة صاحب العمل بقرار اللجنة وتعدل المستحقات وفقا لهذا القرار .
ولصاحب العمل الطعن على قرار اللجنة أمام المحكمة المختصة خلال الثلاثين يوما التالية لصدوره ، ويصبح الحساب نهائيا وتكون المستحقات واجبة الأداء بانقضاء موعد الطعن دون طعن ، أو برفض الهيئة لاعتراض صاحب العمل وعدم قيامه بطلب عرض النزاع على لجنة فحص المنازعات خلال ثلاثين يوما من تاريخ استلامه الإخطار بالرفض .$m254$,'425c4a66656d445e3ead268bdb1468c9',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(121,0,1,$m254$يلتزم صاحب العمل بالنسبة للمؤمن عليهم المشار إليهم فى البند أولا من المادة ( 2 ) من هذا القانون كما يلتزم المؤمن عليه وفقا لأحكام البنود ثانيا وثالثا ورابعا من ذات المادة ، بحسب الأحوال ، بأداء المبالغ التالى بيانها فى المواعيد المحددة قرين كل منها :
1 - الاشتراكات المستحقة عن الشهر ، وذلك فى أول الشهر التالى لشهر الاستحقاق .
2 - الأقساط المستحقة على المؤمن عليه ، وذلك فى أول الشهر التالى لشهر الاستحقاق .
3 - الأقساط المستحقة عن المبالغ المتأخرة ، وذلك فى أول الشهر المستحق عنه القسط .
4 - المبالغ التى يقوم بخصمها شهريا من أجر المؤمن عليه فى الحدود الجائز الحجز عليها أو النزول عنها والتى صرفت للمؤمن عليه بدون وجه حق من الهيئة وذلك اعتبارا من أول الشهر التالى لتاريخ إخطار صاحب العمل .
وفى حالة التأخير فى أداء أى من المبالغ المشار إليها يستحق على الملتزم بالأداء ، بما فى ذلك الجهاز الإدارى للدولة والهيئات العامة ، مبلغ إضافى شهرى عن مدة التأخير من تاريخ وجوب الأداء حتى نهاية شهر السداد ، ويحسب المبلغ الإضافى بنسبة تساوى متوسط إصدارات الخزانة من الأذون والسندات فى الشهر السابق للشهر الذى يتعين فيه سداد المبالغ مضافا إليه ( 2٪ ) .
ويتم الإعفاء من المبلغ الإضافى إذا تم السداد خلال خمسة عشر يوما من تاريخ وجوب الأداء .
وفى جميع الأحوال ، يتحمل الملتزم بالأداء بنفقات إرسال الاشتراكات والمبالغ المستحقة إلى الهيئة ، ويجوز للهيئة أن تقوم بالتحصيل مقابل واحد فى الألف من قيمة المبالغ المحصلة بحد أدنى مقداره عشرة جنيهات وبحد أقصى مقداره مائة جنيه ويرحل هذا المبلغ إلى الحساب المنصوص عليه فى المادة ( 150 ) من هذا القانون .
واستثناء من أحكام الفقرات السابقة ، يجوز للهيئة بعد موافقة مجلس الإدارة أن تتبع فى تحصيل الاشتراكات طرقا ووسائل أخرى فى الحالات التى تحتاج فيها إلى ذلك وعلى الأخص ما يأتى :
1 - إسناد تحصيل اشتراكات التأمين الاجتماعى إلى الجهات الإدارية بالاتفاق مع السلطات المختصة ، ويتعين على هذه الجهات تحصيل الاشتراكات وتوريدها فى مواعيدها المحددة فور تحصيلها إلى الهيئة فى ميعاد غايته أول الشهر التالى لشهر التحصيل وذلك مقابل نسبة لا تزيد عن ( 1٪ ) من قيمة المبالغ المحصلة تخصص لحساب العاملين القائمين بالتحصيل ، ويكون لهذه الجهات فى سبيل استيفاء مستحقات الهيئة سلطة توقيع الحجز الإدارى وفقا لحكم المادة ( 132 ) من هذا القانون .
2 - تحديد المبالغ الإضافية التى تستحق على الملتزم بالتحصيل فى حالة التأخر فى التوريد عن المواعيد المقررة وذلك بما لا يجاوز النسب المقررة بهذه المادة .
وتحدد اللائحة التنفيذية لهذا القانون فى جميع الحالات المواعيد والشروط والإجراءات التى تتبع فى تحصيل الاشتراكات والمبالغ المستحقة للهيئة طبقا لأحكام هذا القانون .$m254$,'89dcf9a739fa7a21886a218a74f18726',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(122,0,1,$m254$مع عدم الإخلال بالمادة ( 120 ) من هذا القانون ، يؤدى صاحب العمل فى القطاع الخاص الاشتراكات كاملة إذا كان عقد العمل موقوفا أو كانت أجور المؤمن عليهم لا تكفى لذلك . وتعتبر المبالغ التى يؤديها صاحب العمل عن المؤمن عليهم فى حكم القرض ويكون الوفاء بها طبقا للأحكام التى تحددها اللائحة التنفيذية لهذا القانون .
ويلتزم صاحب العمل فى القطاع الخاص بأن يعلق فى أماكن العمل الشهادة الدالة على سداد اشتراكه فى الهيئة ، وتتضمن اللائحة التنفيذية لهذا القانون البيانات الخاصة بهذه الشهادة .$m254$,'b2ec4e5f7b0487a54e044cc68d6b2b92',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(123,0,1,$m254$للهيئة استخدام الوسائل اللازمة لتحصيل الاشتراكات ومستحقاتها المالية الأخرى وصرف المعاشات وغيرها من الحقوق المقررة فى هذا القانون بما فى ذلك الأدوات المالية والوسائل الإلكترونية واستخدام شبكات السداد والتحصيل الإلكترونى المصرفية والحكومية .$m254$,'915b7a9d72b65070cc45129688b6ff8e',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(124,0,1,$m254$تعفى قيمة الاشتراكات المستحقة وفقا لأحكام هذا القانون من جميع الضرائب والرسوم أيا كان نوعها المفروضة حاليا والتى تفرض مستقبلا .
وتعفى الاستمارات والمستندات والبطاقات والعقود والمخالصات والشهادات والمطبوعات وجميع المحررات التى يتطلبها تنفيذ هذا القانون من رسوم الدمغة .
وتعفى أموال الهيئة الثابتة والمنقولة وجميع عملياتها الاستثمارية مهما كان نوعها من جميع أنواع الضرائب بما فى ذلك الضرائب العامة على القيمة المضافة والضريبة على العقارات المبنية والرسوم المفروضة حاليا أو التى تفرض مستقبلا من الحكومة أو أى سلطة عامة أخرى داخل جمهورية مصر العربية ، وكذا من رسوم التوثيق والشهر والدمغة فى أى عمل من أعمال الشهر أو التوثيق .
كما تعفى العمليات التى تباشرها الهيئة من الخضوع لأحكام القوانين الخاصة بالإشراف والرقابة على هيئات التأمين .
وتعفى الهيئة من أداء الضرائب والرسوم على الأصناف اللازمة لأعمالها التى تستوردها من الخارج .$m254$,'d0cfa84585fdc2a92433a3a528f32946',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(125,0,1,$m254$تعفى جميع الحقوق والمبالغ التى تؤدى وفقا لأحكام هذا القانون من الخضوع للضرائب والرسوم بجميع أنواعها ، كما يسرى هذا الإعفاء على متجمد هذه الحقوق .$m254$,'6873a71513a7e44e541671e389c23435',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(126,0,1,$m254$تعفى من الرسوم القضائية فى جميع درجات التقاضى الدعاوى التى ترفعها الهيئة أو المؤمن عليهم أو أصحاب المعاشات أو المستحقون طبقا لأحكام هذا القانون ، ويكون نظرها على وجه الاستعجال وللمحكمة فى جميع الأحوال الحكم بالنفاذ المعجل وبلا كفالة .$m254$,'abec36ef4710afa75b0344f3d8781587',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(127,0,1,$m254$تقدر الحقوق المقررة وفقا لهذا القانون على أساس البيانات والمستندات الواردة فى ملف التأمين الاجتماعى الخاص بالمؤمن عليه دون الرجوع إلى ملف الخدمة .
وتحدد اللائحة التنفيذية لهذا القانون السجلات والدفاتر التى يلتزم صاحب العمل بحفظها والملفات التى ينشئها لكل مؤمن عليه والمستندات التى تودع بها ، وكذلك البيانات والنماذج التى يلتزم بتقديمها للهيئة عن العاملين لديه وأجورهم واشتراكاتهم ومواعيد تقديم هذه البيانات والنماذج .$m254$,'a7123de91fbb78625070cc845a955dc6',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(128,0,1,$m254$تحدد اللائحة التنفيذية لهذا القانون بناء على اقتراح مجلس إدارة الهيئة الشروط والأوضاع والمستندات اللازمة لتسوية وصرف الحقوق المقررة بهذا القانون .$m254$,'215f699ead293e9b40faef61d6b27835',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(129,0,1,$m254$استثناء من أحكام القانون المدنى ، يجب تقديم طلب صرف المعاش أو التعويض أو أى مبالغ مستحقة طبقا لأحكام هذا القانون فى ميعاد أقصاه خمس سنوات من التاريخ الذى نشأ فيه سبب الاستحقاق ، وإذا قدم الطلب بعد انتهاء الميعاد المشار إليه فيتم صرف المعاش اعتبارا من أول الشهر الذى قدم فيه الطلب بالإضافة إلى قيمة المعاشات المستحقة عن الخمس سنوات السابقة على تاريخ تقديم طلب الصرف ، ويسقط الحق فى صرف باقى الحقوق .
وتعتبر المطالبة بأى من الحقوق المقررة بأحكام هذا القانون شاملة المطالبة بباقى تلك الحقوق .
وينقطع سريان الميعاد المشار إليه بالنسبة إلى المستحقين جميعا إذا تقدم أحدهم فى الموعد المحدد .
ويوقف أداء المعاش الذى لا يتم صرفه لمدة ستة أشهر ، وتسرى أحكام الفقرة الأولى عند تقديم طلب من صاحب الشأن لإعادة صرف المعاش .$m254$,'e6d3b6b5737a3f4c4eb3d2640c0ebac1',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(130,0,1,$m254$على الهيئة أن تتخذ من الوسائل ما يكفل تقدير الحقوق التأمينية وصرفها خلال أربعة أسابيع من تاريخ تقديم المؤمن عليه أو المستحقين طلبا بذلك مشفوعا بجميع المستندات المطلوبة .
فإذا تأخر صرف المبالغ المستحقة عن المواعيد المشار إليها بالفقرة السابقة التزمت الهيئة بناء على طلب صاحب الشأن بدفعها مضافا إليها مبلغ إضافى عن كل شهر يتأخر فيه الصرف عن الميعاد المحدد ، ويحسب المبلغ الإضافى بنسبة تساوى متوسط إصدارات الخزانة من الأذون والسندات وذلك من تاريخ استيفاء المؤمن عليه أو المستفيدين المستندات المطلوبة منهم ، وبما لا يجاوز قيمة أصل المستحقات .
وترجع الهيئة على المتسبب فى تأخير الصرف بقيمة المبالغ الإضافية المشار إليها التى التزمت بها ، ما لم يثبت أن التأخير راجع لخطأ مرفقى .
ولا تستحق المبالغ الإضافية المشار إليها فى حالات المنازعات إلا من تاريخ رفع الدعوى .$m254$,'0981aaafa0e7157bff5a03dc83e6ad32',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(131,0,1,$m254$مع عدم الإخلال بأحكام المادتين ( 56 ، 59 ) من هذا القانون ، لا يجوز للهيئة تعديل الحقوق المقررة بهذا القانون بانقضاء ثلاث سنوات من تاريخ الإخطار بربط الحقوق التأمينية بصفة نهائية ، كما تسقط دعوى المطالبة بتعديل تلك الحقوق بعد انقضاء الميعاد المشار إليه ، وذلك فيما عدا الحالات الآتية :
1 - صدور حكم قضائى بات .
2 - صدور قانون لاحق يقرر زيادة الحقوق التأمينية .
3 - الأخطاء المادية التى تقع فى الحساب عند التسوية .
4 - حالات الغش والتدليس .
5 - الحالات التى لا يكون لصاحب الشأن فيها الأحقية فى أصل الحق التأمينى .
وتحدد اللائحة التنفيذية لهذا القانون نموذج الإخطار المشار إليه فى الفقرة الأولى .
وفى جميع الأحوال ، يسقط الحق فى رفع دعوى المطالبة بتعديل تلك الحقوق بانقضاء خمس عشرة سنة من تاريخ الاستحقاق .$m254$,'775daa0f3eaecf4766ac5bf2d5a85b48',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(132,0,1,$m254$يكون للمبالغ المستحقة للهيئة بمقتضى أحكام هذا القانون امتياز على جميع أموال المدين من منقول وعقار ، وتستوفى قبل المصروفات القضائية . وللهيئة حق تحصيل هذه المبالغ بطريق الحجز الإدارى ، ويجوز لها تقسيط المبالغ المستحقة على صاحب الشأن وذلك بالشروط والأوضاع التى تحددها اللائحة التنفيذية لهذا القانون .$m254$,'ea75a7d769bb29fa57191cae759baff3',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(133,0,1,$m254$لا يجوز الحجز أو النزول عن مستحقات المؤمن عليه أو صاحب المعاش أو المستفيدين لدى الهيئة .
واستثناء من حكم الفقرة السابقة ، يجوز الحجز أو النزول عن المستحقات المشار إليها لسداد الحقوق الآتية :
1 - النفقات بمراعاة أحكام القانون رقم 1 لسنة 2000 بشأن تنظيم بعض أوضاع وإجراءات التقاضى فى مسائل الأحوال الشخصية .
2 - ما تجمد للهيئة من مبالغ على صاحب الشأن .
3 - المبالغ المستحقة للمعاشات العسكرية والضمان الاجتماعى .
ويراعى بالنسبة للمعاش الشهرى أن يكون الخصم فى حدود ( 25٪ ) منه ، وفى حالة التزاحم يبدأ بخصم دين النفقة فى حدود الجزء الجائز الحجز عليه مخصوما منه ثمن المعاش للوفاء بدين الهيئة .
4 - أقساط قروض بنك ناصر الاجتماعى .
5 - الأقساط المستحقة للهيئة .
6 - الحالات التى يوافق عليها مجلس الإدارة نزولا على رغبة صاحب الشأن .
وبمراعاة الفقرة السابقة ، يكون للهيئة خصم ما يكون قد استحق على المؤمن عليه أو صاحب المعاش من مبالغ قبل وفاته من إجمالى الحقوق التأمينية للمستفيدين تقسم بينهم بنسبة ما يصرف لكل منهم .
ويجوز للهيئة قبول أداء المبالغ المستحقة لها على المؤمن عليه بالتقسيط وفقا للجدول رقم ( 4 ) المرفق ، وتسقط الأقساط المتبقية فى حالة استحقاق المعاش للعجز أو الوفاة وفقا لأحكام المادة ( 21 ) من هذا القانون .
ولا يتم صرف المعاش المستحق وفقا للبند رقم ( 6 ) من المادة ( 21 ) من هذا القانون إلا بعد أداء المبالغ المستحقة على المؤمن عليه والقيمة الحالية للأقساط وفقا لجدول القيمة الحالية المرفق باللائحة التنفيذية لهذا القانون .
وفى حالة صرف تعويض الدفعة الواحدة مع عدم استحقاق معاش ، تخصم القيمة الحالية للأقساط المستحقة على المؤمن عليه من المبالغ المستحقة له .
ويوقف سداد الأقساط المستحقة على المؤمن عليه فى جميع الحالات التى لا يستحق عنها أجرا أو تعويضا عن الأجر ويستأنف السداد فور استحقاق الأجر وتزاد مدة التقسيط بقدر المدة التى أوقف فيها سداد الأقساط .
ويجوز للهيئة قبول تقسيط المبالغ المستحقة لها قبل المؤمن عليه أو صاحب المعاش أو المستفيدين على خمس سنوات .
كما يكون للهيئة الحجز على أجر المؤمن عليه لسداد متجمد الاشتراكات ومتجمد المبالغ المستحقة لها وذلك مع مراعاة الحدود والقواعد المنصوص عليها فى الفقرة الثانية من هذه المادة .$m254$,'fab244948134165d1f1b7d0fab76490b',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(134,0,1,$m254$يجوز للمؤمن عليه أو صاحب المعاش أو المستحقين طلب أى بيانات عن حالته التأمينية مقابل أداء مبلغ لا يجاوز عشرة جنيهات عن كل طلب وتحدد اللائحة التنفيذية لهذا القانون قيمة مقابل أداء الخدمة وإجراءات الحصول على البيانات وحالات الإعفاء من المقابل المشار إليه .$m254$,'9a6937fcf5751252895068571722664d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(135,0,1,$m254$يحدد مجلس الإدارة مقابل الانتفاع بالخدمات التأمينية التى تقدمها الهيئة للغير .$m254$,'aa9d13cfc8e68a206facd198788304cc',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(136,0,1,$m254$تلتزم الهيئة بإعطاء أصحاب الأعمال فى القطاع الخاص شهادة مقابل أداء مبلغ لا يتجاوز عشرة جنيهات تدل على انتظامهم فى الاشتراك فى الهيئة عن جميع العاملين لديهم ، وعليهم أن يعلقوا هذه الشهادة فى أماكن ظاهرة بمقر عملهم وتجدد هذه الشهادة سنويا .
ويلتزم كل مؤمن عليه من الفئات المشار إليها بالبند رابعا من المادة ( 2 ) بالتقدم إلى مكتب الهيئة التابع له محل إقامته لتسجيل نفسه لدى الهيئة ، ويعتد فى تحديد مهنته بالمهنة المثبتة ببطاقة الرقم القومى دون غيرها .
وعلى جميع أجهزة الدولة أن تعلق التعامل مع أصحاب الأعمال أو المؤمن عليهم على تقديمهم الشهادة الدالة على الاشتراك بالهيئة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وإجراءات تنفيذ هذه المادة بعد التنسيق مع الوزراء المختصين .$m254$,'394b4440ceac6c7057b4127bcdf32fd7',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(137,0,1,$m254$تئول حصيلة الرسوم وحصيلة مقابل أداء الخدمات المقررة بموجب هذا القانون إلى الحساب المنصوص عليه فى المادة ( 150 ) منه .$m254$,'38a968753275671c13f4ef640bae21db',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(138,0,1,$m254$تضمن المنشأة ، بجميع عناصرها المادية والمعنوية فى أى يد كانت ، جميع مستحقات الهيئة .
ويكون الخلف مسئولا بالتضامن مع أصحاب الأعمال السابقين سواء كانوا ملاكا أو مستأجرين للعين محل النشاط عن الوفاء بجميع الالتزامات المستحقة عليهم .
على أنه فى حالة انتقال أحد عناصر المنشأة إلى الغير بالبيع أو بالإدماج أو بالوصية أو بالإرث أو بالنزول أو بغير ذلك من تصرفات ، فتكون مسئولية الخلف فى حدود قيمة ما آل إليه .
ولا يحول دون دفع المسئولية وفقا لما سبق سوى تقديم من آلت إليه المنشأة أو العين شهادة صادرة من الهيئة فى تاريخ سابق على التعامل على المنشأة تثبت عدم وجود مديونية على المنشأة فى التاريخ الذى آلت إليه المنشأة أو العين .$m254$,'878c9a895a2f05b8bd2023d33c0b6c35',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(139,0,1,$m254$يشترط لصرف الحقوق التأمينية المستحقة للمؤمن عليهم المشار إليهم بالبنود ثانيا وثالثا ورابعا من المادة ( 2 ) من هذا القانون أداء الالتزامات المقررة وفقا لأحكام هذا القانون .$m254$,'7365d42117ab3f9b966ee1a69764ed04',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(140,0,1,$m254$للمؤمن عليه أن يتقدم بطلب إعادة النظر فى قرار جهة العلاج وذلك خلال أسبوع من تاريخ إخطاره بانتهاء العلاج أو بتاريخ العودة إلى العمل أو بعدم إصابته بمرض مهنى ، وخلال شهر من تاريخ إخطاره بعدم ثبوت العجز أو بتقديم نسبته .
كما يكون للابن أو الأخ أن يتقدم بطلب إعادة النظر فى قرار الجهة الطبية بعدم ثبوت عجزه عن الكسب ، وذلك خلال شهر من تاريخ إخطاره بعدم ثبوت العجز .
ويقدم الطلب إلى لجنة التحكيم الطبى بالهيئة مرفقا به الشهادات الطبية المؤيدة لوجهة نظره مع أداء مبلغ عشرين جنيها مقابل أداء خدمة .
وتحدد اللائحة التنفيذية لهذا القانون الأحكام المنظمة لتشكيل لجنة التحكيم الطبى وإجراءات وتنظيم عملها ووسيلة الإخطار بنتيجة قرار اللجنة بعد الاتفاق مع وزير القوى العاملة .$m254$,'ae545bded94af31139ecd9bfc71e112a',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(141,0,1,$m254$تلتزم الهيئة بالوفاء بالتزاماتها المقررة كاملة بالنسبة للمؤمن عليهم والمستحقين حتى ولو لم يقم صاحب العمل بالاشتراك عنهم فى الهيئة وتقدر الحقوق وفقا للأحكام المنصوص عليها فى هذا القانون .
وإذا لم تتثبت الهيئة من صحة البيانات الخاصة بمدة الاشتراك فى التأمين أو الأجر ربط المعاش أو التعويض على أساس المدة والأجر غير المتنازع عليهما .
ويؤدى المعاش أو التعويض على أساس الحد الأدنى المقرر قانونا للأجر فى حالة عدم إمكان التثبت من قيمة الأجر .
واستثناء من قواعد وأحكام الاشتراكات يلتزم صاحب العمل بأن يؤدى إلى صندوق التأمين الاجتماعى القيمة الرأسمالية للمعاش وقيمة المستحقات التأمينية الأخرى المترتبة على ثبوت علاقة العمل .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام حساب القيمة الرأسمالية .$m254$,'e71487e3de8f312640be6b829ed5657a',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(142,0,1,$m254$يلتزم صاحب العمل بموافاة الهيئة ببيان بأسماء العاملين لديه الذين تنتهى خدمتهم بسبب بلوغ سن استحقاق المعاش ، وذلك قبل موعد انتهاء الخدمة بثلاثة أشهر على الأقل .
ويلتزم صاحب العمل فى القطاع الخاص عن كل شهر يتأخر فيه عن إخطار الهيئة بانتهاء خدمة المؤمن عليه بأداء مبلغ إضافى بنسبة ( 20٪ ) من قيمة الاشتراك المستحق عن الشهر الأخير من مدة اشتراك المؤمن عليه ، وذلك فى الحالات وبالشروط والقواعد التى تحددها اللائحة التنفيذية لهذا القانون .$m254$,'18a5f6ce471883b5fa7d35be24114485',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(143,0,1,$m254$يكون لمن تندبه الهيئة من العاملين بها الحق فى دخول محال العمل بما فى ذلك المنشآت المقامة فى المناطق الحرة وغيرها من المناطق ذات الطبيعة القانونية الخاصة فى مواعيد العمل المعتادة لإجراء التحريات اللازمة والاطلاع على السجلات والدفاتر والأوراق والمحررات والملفات والمستندات المالية التى تتعلق بتنفيذ أحكام هذا القانون ، ويحدد وزير العدل بالاتفاق مع رئيس الهيئة العاملين بالهيئة الذين تكون لهم صفة الضبطية القضائية فى تطبيق أحكام هذا القانون .$m254$,'3a257eb905fa80ffb61d4e9569832d5f',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(144,0,1,$m254$يلتزم كل من يعهد بتنفيذ أى أعمال إلى مقاول أن يخطر الهيئة باسم المقاول وعنوانه وبياناته عن العملية قبل بدء العمل بسبعة أيام على الأقل ، وعدم سداد أى مستحقات له قبل أن يقدم ما يفيد سداد اشتراكات التأمين الاجتماعى عن هذه الأعمال ، ويكون مسند الأعمال متضامنا مع المقاول فى الوفاء بالالتزامات المقررة وفقا لأحكام هذا القانون فى حالة إخلاله بالالتزامات المتقدم بيانها .
كما تلتزم الجهات المختصة بإصدار تراخيص البناء أو الهدم أو التى تحرر مخالفاته بموافاة الهيئة ببيانات الترخيص واسم وعنوان المقاول الذى يقوم بتنفيذه أو اسم وعنوان الصادر فى شأنه المخالفات خلال الميعاد المشار إليه بالفقرة السابقة .$m254$,'75d924472f15380f699d6908877514e6',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(145,0,1,$m254$على الجهات والمصالح الحكومية بما فى ذلك مصلحة الضرائب المصرية والإدارة العامة للجوازات والهجرة والجنسية ، وعلى البنوك والنقابات والجمعيات ، موافاة الهيئة بجميع البيانات التى تطلبها فى مجال تطبيق أحكام هذا القانون ، ولا يعتبر ذلك إفشاء لسر المهنة أو إخلالا بمقتضيات الوظيفة .
كما يلتزم قطاع الأحوال المدنية بموافاة الهيئة بجميع البيانات والمعلومات اللازمة لتنفيذ أحكام هذا القانون وعلى الأخص بيانات المهنة ، والحالة الاجتماعية لمستحقى المعاش من زواج وطلاق وأى تغيير يطرأ عليها ، وكذا حالات الوفاة التى تقع بين من يحصلون على معاشات من الهيئة .
على أن يكون موافاة الهيئة بالبيانات المشار إليها دون أى مقابل أو رسوم .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام تطبيق هذه المادة .$m254$,'a9faed3ac9eba5752b7db74acb75703b',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(146,0,1,$m254$على وحدات الجهاز الإدارى للدولة والهيئات والجمعيات والنقابات والشركات وأصحاب الأعمال الذين يستخدمون أحد أصحاب المعاشات أو المستحقين فى المعاش وفقا لأحكام هذا القانون أن يخطروا الهيئة باسم من يستخدمونه منهم وتاريخ التحاقه بالعمل ومقدار أجره والجهة التى يصرف منها معاشه ، وذلك خلال شهر من تاريخ استخدامه .
وعلى صاحب المعاش أو المستحق أو من يصرف باسمه المعاش إبلاغ الهيئة بكل تغيير فى أسلوب الاستحقاق يؤدى إلى قطع المعاش أو خفضه أو وقفه وذلك خلال شهر على الأكثر من تاريخ التغيير .$m254$,'c32f19d1d102205bf0d2d3695ebfdebc',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(147,0,1,$m254$استثناء من أحكام القانون المدنى ، تتقادم حقوق الهيئة قبل أصحاب الأعمال والمؤمن عليهم وأصحاب المعاشات والمستفيدين بانقضاء خمس عشرة سنة من تاريخ الاستحقاق ، وذلك فى حالة تمسك المدين بذلك .
ومع عدم الإخلال بأسباب قطع التقادم المنصوص عليها فى القانون المدنى ، تقطع مدة التقادم بأى عمل تقوم به الهيئة يكشف عن تمسكها بمستحقاتها لدى المدين وعلى الأخص بالتنبيه على المدين بأداء المبالغ المستحقة عليه بمقتضى أحكام هذا القانون بموجب كتاب موصى عليه مصحوبا بعلم الوصول أو بالحجز الإدارى أو غير ذلك من أعمال تكون قاطعة الدلالة فى هذا الشأن .
وفى جميع الأحوال ، لا يسرى التقادم فى مواجهة الهيئة بالنسبة للمدين الذى يتبع أيا من طرق الغش أو التحايل للحصول على أموال الهيئة أو لعدم الوفاء بمستحقاتها كاملة ، كما لا يسرى التقادم بالنسبة لصاحب العمل الذى لم يسبق اشتراكه فى التأمين عن كل عماله أو بعضهم إلا من تاريخ علم الهيئة بالتحاقهم لديه .$m254$,'9b89e73f5c945ff6bb99dc26c9dee2dc',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(148,0,1,$m254$تنشأ بالهيئة لجان لفحص المنازعات الناشئة عن تطبيق أحكام هذا القانون ويصدر بتشكيلها ونظام عملها ومكافآت أعضائها قرار من رئيس الهيئة بعد موافقة مجلس إدارة الهيئة .
وعلى أصحاب الأعمال والمؤمن عليهم وأصحاب المعاشات والمستحقين وغيرهم من المستفيدين قبل اللجوء إلى القضاء تقديم طلب إلى الهيئة لعرض النزاع على اللجان المشار إليها لتسويته بالطرق الودية .
ومع عدم الإخلال بأحكام المادة ( 118 ) من هذا القانون ، لا يجوز رفع الدعوى قبل مضى ثلاثين يوما من تاريخ تقديم الطلب المشار إليه .$m254$,'a5b7a747c2488f928912b19b39bdb26d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(149,0,1,$m254$تختص الهيئة بطلب الرأى من مجلس الدولة فيما يتعلق بتطبيق أحكام هذا القانون .$m254$,'c4cc71904cd6d83e8d0587f1554b3516',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(150,0,1,$m254$تلتزم جميع البنوك التجارية وبنك ناصر الاجتماعى وهيئة البريد وغيرها من الجهات بصرف المعاشات التى تحيلها الهيئة إليها .
وتحدد اللائحة التنفيذية لهذا القانون مواعيد وكيفية صرف المعاشات والجهات التى تصرف منها .
ويجوز للهيئة أن تقدم خدمات تكنولوجية لأصحاب المعاشات والمستحقين بنفسها أو من خلال التعاقد مع الشركات المتخصصة أو البنوك ، وتحدد اللائحة التنفيذية لهذا القانون هذه الخدمات وطريقة تقديمها ومقابل أدائها ، على ألا تتحمل الهيئة أى تكاليف إضافية مقابل تقديم هذه الخدمات .
ويفرض رسم على صاحب المعاش أو المستحق مقدارة ( 0.2٪ ) من قيمة المبالغ المستحقة بما لا يجاوز عشرين جنيها مقابل صرف أى من المبالغ المستحقة وفقا لأحكام هذا القانون ، وتحدد اللائحة التنفيذية لهذا القانون حالات الإعفاء منه .
وفى حالة وجود قائم بالصرف عن أكثر من مستحق لا يزيد الرسم الذى يتحملونه على الحد الأقصى المشار إليه .
وترحل حصيلة الرسم المشار إليه إلى حساب خاص يخصص لصالح العاملين بالهيئة ، وتحدد اللائحة التنفيذية لهذا القانون أوجه الصرف من هذا الحساب وقواعده ، ويجوز أن تقرر اللائحة التنفيذية لهذا القانون مد الخدمات التى تقررها فى هذا الشأن إلى أصحاب المعاشات من العاملين المشار إليهم .
كما تحدد اللائحة التنفيذية لهذا القانون النسبة التى تؤدى إلى الجهات القائمة بالصرف ، ويتم تخصيص نصف هذه النسبة لحساب العاملين القائمين بصرف المعاشات فى تلك الجهات .$m254$,'e911a91030b5c43c08cd924eef4ff6ca',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(151,0,1,$m254$يهمل كسر الجنيه عند حساب الحقوق التأمينية ، وفى إجمالى المبالغ التى يلتزم صاحب العمل بأدائها .$m254$,'e14d863f41cdf0392d252a61449c3d21',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(152,0,1,$m254$ينشأ معهد يسمى « المعهد القومى للتأمين الاجتماعى » ، يتبع الهيئة ، تكون له شخصية اعتبارية وموازنة مستقلة ، مقره مدينة القاهرة ، ويهدف المعهد إلى العمل على تنمية مهارات العاملين فى مجال التأمين الاجتماعى بهدف مسايرة التطور العالمى وترسيخ قواعد العمل المهنى السليم .
ويصدر بالنظام الأساسى للمعهد قرار من رئيس مجلس الوزراء بناء على موافقة مجلس الإدارة على أن يتضمن ما يأتى :
1 - مهام واختصاصات المعهد .
2 - تشكيل مجلس إدارة المعهد واختصاصاته وإجراءات الدعوة إلى اجتماعات المجلس ونظام العمل به .
3 - قواعد اختيار الخبراء والمدربين والفنيين والباحثين والعاملين .
4 - اللوائح المالية والإدارية للمعهد دون التقيد بالنظم المعمول بها فى الحكومة أو القطاع العام أو قطاع الأعمال العام .$m254$,'06176f20e00cda1a9fc52e42a8dd7ade',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(153,0,1,$m254$تبدأ السنة المالية للمعهد مع بداية السنة المالية للهيئة ، وتنتهى بنهايتها ويكون للمعهد حساب خاص تودع فيه موارده ، ويرحل هذا الحساب من سنة إلى أخرى .
وتتكون موارد المعهد مما يأتى :
1 - الاعتمادات التى يخصصها له مجلس الإدارة .
2 - المبالغ التى تؤديها الجهات مقابل تدريب العاملين بها .
3 - مقابل الخدمات التى يؤديها المعهد .
4 - العائد على استثمار أموال المعهد .
5 - التبرعات والهبات والإعانات التى ترد إلى المعهد من الجهات المختلفة ويقرر مجلس الإدارة قبولها .
ويصدر بتحديد المقابل المنصوص عليه فى البندين ( 2 ، 3 ) قرار من مجلس الإدارة بناء على اقتراح مجلس إدارة المعهد .$m254$,'28dc95e9ca01f5176feb9dd030a400f0',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(154,0,1,$m254$مع مراعاة الهيكل التنظيمى للهيئة ، ينقل إلى ديوان عام رئاسة الهيئة العاملون بديوان عام وزارة التأمينات بدرجاتهم وأوضاعهم الوظيفية فى تاريخ العمل بأحكام هذا القانون ، على أن تتم معاملتهم ماليا معاملة العاملين بالهيئة .$m254$,'4affd4293109910404b0337f0eef0510',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(155,0,1,$m254$تئول أموال صندوقى التأمين الاجتماعى المنصوص عليهما بقانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975 إلى الصندوق المنشأ بموجب المادة ( 5 ) من هذا القانون .
وتنقل الحقوق والالتزامات التى ترتبت على تنفيذ القوانين المتعلقة بالتأمين الاجتماعى إلى الصندوق المنشأ بموجب المادة ( 5 ) من هذا القانون .
وتتولى لجنة الخبراء تحديد رصيد أول المدة فى حسابات التأمين الاجتماعى ، ويصدر بها قرار من رئيس الهيئة بعد موافقة مجلس الإدارة .
ويلتزم الصندوق المشار إليه والخزانة العامة ، كل فيما يخصه ووفق أحكام القوانين المتعلقة بالتأمين الاجتماعى ، بقيمة الحقوق المقررة بها والحقوق التى يقررها القانون المرافق لأصحاب المعاشات والمستحقين المعاملين بتلك القوانين قبل العمل بأحكامه .$m254$,'b0fe889dc0dd257652469f433c8b8c46',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(156,0,1,$m254$يحدد أجر أو دخل التسوية عند مدة الاشتراك فى تأمين الشيخوخة والعجز والوفاة السابقة على تاريخ العمل بهذا القانون عن كل من الأجر الأساسى والأجر المتغير وفقا لأحكام قانون التأمين الاجتماعى التى قضيت المدة فى ظله ، ويزاد أجر أو دخل التسوية بنسبة متوسط نسب التضخم عن كل سنة من تاريخ العمل بهذا القانون حتى تاريخ تحقق واقعة الاستحقاق .$m254$,'31acacb106e877406b2040ffe17876ff',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(157,0,1,$m254$تحسب المكافأة عن المدة السابقة على تاريخ العمل بهذا القانون بواقع أجر شهر عن كل سنة من سنوات مدة الاشتراك خلال المدة المشار إليها .
ويقدر أجر حساب المكافأة بأجر حساب معاش الأجر الأساسى المنصوص عليه بالمادة السابقة .
ويراعى بالنسبة للمدد المحسوبة فى نظام المكافأة وفقا للمادة 34 من قانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975 ما يأتى :
1 - تحسب المكافأة عن هذه المدة فى حالات بلوغ سن استحقاق المعاش والوفاة وفقا للأحكام الواردة بالفقرتين السابقتين .
2 - فى غير الحالات المشار إليها بالبند السابق تحسب المكافأة طبقا للجدول رقم ( 4 ) المرفق بقانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975 ، وعلى أساس سن استحقاق المؤمن عليه فى تاريخ بدء العمل بهذا القانون وأجر حساب المكافأة المشار إليه فى الفقرة السابقة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام وإجراءات تنفيذ أحكام هذه المادة .$m254$,'d2e7aa59ea94cdea9c688713f47092bf',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(158,0,1,$m254$يوقف العمل بالقرارات والاتفاقات التى أبرمت مع الجهات التى طلبت زيادة اشتراك العاملين بها فى نظام المكافأة وفقا لقانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975 والقوانين المعدلة والمكملة له ، وتحسب المكافأة وفقا للقواعد المشار إليها بالمادة السابقة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وأحكام وإجراءات تنفيذ أحكام هذه المادة .$m254$,'5117be99f038a2dd2d7392891da8d99e',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(159,0,1,$m254$تعتبر مدة الاشتراك وفقا لقانون التأمين الاجتماعى الشامل الصادر بالقانون رقم 112 لسنة 1980 التى أدى المؤمن عليه الاشتراك عنها قبل العمل بهذا القانون ، مدة اشتراك وفقا لأحكام هذا القانون وعلى أساس الحد الأدنى لأجر أو دخل الاشتراك بحسب الأحوال ، وفقا لأحكام قانونى التأمين الاجتماعى رقمى 79 لسنة 1975 و 108 لسنة 1976 ، وذلك بمراعاة تدرج أجر أو دخل الاشتراك خلال كامل مدة الاشتراك المشار إليها .
وتلتزم الخزانة العامة بسداد مساهمة مالية تعادل حصة صاحب العمل عن هذه المدة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وإجراءات تطبيق هذه المادة .$m254$,'94ec3afb8e8bcdfa945e6eb9a837e390',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(160,0,1,$m254$يكون للمؤمن عليه السابق خضوعه لأحكام قانون التأمين الاجتماعى الشامل الصادر بالقانون رقم 112 لسنة 1980 أو قانون التأمين الاجتماعى على أصحاب الأعمال ومن فى حكمهم الصادر بالقانون رقم 108 لسنة 1976 الذى لا تسرى عليه أحكام هذا القانون الحق فى طلب الانتفاع بأحكام البند رابعا من المادة ( 2 ) خلال سنة من تاريخ العمل بأحكام هذا القانون .
وفى حالة وفاة المؤمن عليه قبل إبداء الرغبة فى الانتفاع يكون للمستحقين عنه الحق فى إبداء الرغبة خلال المدة المشار إليها بالفقرة السابقة .$m254$,'b7b43afa85ff466c1220cb9b59851867',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(161,0,1,$m254$تسرى حدود الجمع بين المعاشات أو بين المعاش والدخل المنصوص عليها فى هذا القانون على حالات الاستحقاق السابقة على تاريخ العمل به التى حرم فيها المستحق من المعاش الآخر أو جزء منه تطبيقا لحدود الجمع السابقة وذلك فى حدود الجزء غير الموزع من المعاش .$m254$,'d30e81a1625ed0a586fb6ed011ebbbf1',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(162,0,1,$m254$يتجاوز عن استرداد ما تبقى من المبالغ التى صرفت قبل العمل بهذا القانون بالمخالفة لأحكام حظر الجمع بين المعاشات أو بين المعاش والدخل وفقا لكل من قانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975 وقانون التأمين الاجتماعى على أصحاب الأعمال ومن فى حكمهم الصادر بالقانون رقم 108 لسنة 1976 وقانون التأمين الاجتماعى على العاملين المصريين فى الخارج الصادر بالقانون رقم 50 لسنة 1978 ، وذلك فى الحدود التى أجاز فيها هذا القانون الجمع بين أكثر من معاش أو بين المعاش والدخل .$m254$,'944b2b3768a7e9a93ae58a863ae6bcd9',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(163,0,1,$m254$تزاد معاشات تأمين الشيخوخة والعجز والوفاة المستحقة وفقا لهذا القانون بقيمة تعادل الفرق بين 450 جنيها و ( 33٪ ) ( ثلاثة وثلاثون فى المائة ) من إجمالى قيمة المعاش فى تاريخ الاستحقاق .
ويراعى إيقاف صرف الزيادة فى حالة عودة صاحب المعاش إلى العمل أو مزاولته مهنة قبل بلوغه سن التقاعد .
وإذا قل المعاش بعد إضافة هذه الزيادة عن 900 جنيه يرفع إلى هذا القدر .
ولا يتم الانتفاع بحكم هذه المادة إلا مرة واحدة عند ربط المعاش .
وتتحمل الخزانة العامة للدولة بالأعباء المترتبة على تنفيذ أحكام هذه المادة .
وتحدد اللائحة التنفيذية لهذا القانون ضوابط تنفيذ هذه المادة .$m254$,'494306249cc5bef0ed05b019b06001e2',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(164,0,1,$m254$مع مراعاة الإخلال بأى عقوبة أشد ينص عليها قانون العقوبات أو أى قانون آخر ، يعاقب على الجرائم المنصوص عليها فى المواد التالية بالعقوبات المقررة لها .$m254$,'2cbd626e673d849df8379b5e486d1ebb',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(165,0,1,$m254$يعاقب بالغرامة التى لا تقل عن ثلاثين ألف جنيه ولا تجاوز مائة ألف جنيه ، كل من منع العاملين بالهيئة ممن لهم صفة الضبطية القضائية من دخول محل العمل ، أو لم يمكنهم من الاطلاع على السجلات والدفاتر والمستندات والأوراق التى يتطلبها تنفيذ أحكام هذا القانون ، أو أعطى بيانات غير صحيحة ، أو امتنع عن إعطاء البيانات المنصوص عليها فى هذا القانون أو القرارات أو اللوائح المنفذة له .
وتضاعف العقوبة فى حالة العود .$m254$,'70bba366a4194206a9262693a32aaebf',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(166,0,1,$m254$يعاقب بغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز خمسين ألف جنيه ، كل من حصل على أموال الهيئة بغير حق أو قام بإعطاء بيانات غير صحيحة أو امتنع عن إعطاء بيانات مما يجب الإفصاح عنها وفقا لأحكام هذا القانون أو القرارات أو اللوائح المنفذة له مع علمه بذلك .
ويعاقب بذات العقوبة كل من تعمد عدم الوفاء بالمبالغ المستحقة للهيئة وفقا لأحكام هذا القانون عن طريق إعطاء بيانات خاطئة أو إخفاء بيانات .$m254$,'045ced77fda79b25d4d107652bbe5a04',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(167,0,1,$m254$يعاقب الموظف المختص فى الجهات الحكومية أو القطاع العام أو قطاع الأعمال العام أو المسئول الفعلى عن الإدارة لدى صاحب العمل ، بالحبس مدة لا تجاوز سنة ، وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مائة ألف جنيه ، أو بإحدى هاتين العقوبتين ، فى حالة ارتكابه أيا من الأفعال الآتية :
( أ ) عدم نقل المصاب إلى مكان العلاج بالمخالفة لحكم المادة ( 50 ) من هذا القانون .
( ب ) عدم إبلاغ الشرطة بغير عذر مقبول بأى حادث يصيب أحد العاملين الخاضعين لأحكام هذا القانون وذلك بالمخالفة لحكم المادة ( 61 ) من هذا القانون .
وتكون العقوبة الحبس مدة لا تجاوز ثلاث سنوات ، وغرامة لا تجاوز مليون جنيه ، إذا ترتب على عدم نقل المصاب وفاته أو تخلفت لديه نسبة عجز تجاوز ( 50٪ ) .
وتكون العقوبة الغرامة التى لا تقل عن عشرين ألف جنيه ولا تجاوز خمسين ألف جنيه فى حال ارتكابهم أيا من الأفعال الآتية :
( أ ) عدم تقديم بيانات بأسماء العاملين وأجورهم واشتراكاتهم للهيئة بالمخالفة لأحكام المادتين ( 120 ، 142 ) من هذا القانون .
( ب ) عدم موافاة الهيئة بملف التأمين الاجتماعى للمؤمن عليه فى حالة طلبه .
( ج ) مخالفة أحكام المادة ( 142 ) من هذا القانون أو القرارات واللوائح المنفذة لها .
( د ) الامتناع عن تنفيذ طلب الهيئة بخصم المبالغ التى صرفت للمؤمن عليه دون وجه حق أو عدم توريد هذه المبالغ إلى الهيئة فى مواعيد سداد الاشتراكات .
وتضاعف العقوبة فى حالة العود .$m254$,'aced48b2d559cb52dbdc06eafcdfc64d',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(168,0,1,$m254$يعاقب بغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه المسئول الفعلى عن الإدارة لدى صاحب العمل أو الموظف المختص فى الجهات الحكومية أو القطاع العام أو قطاع الأعمال العام الذى لم يقم بالاشتراك فى الهيئة عن أى من عماله الخاضعين لأحكام هذا القانون أو لم يقم بالاشتراك عنهم بالمدد أو الأجور الحقيقية .
ويعاقب بذات العقوبة المسئول الفعلى لدى صاحب العمل عن الإدارة أو الموظف المختص فى الجهات الحكومية أو القطاع العام أو قطاع الأعمال العام الذى يحمل المؤمن عليهم أى نصيب من نفقات التأمين لم ينص عليها فى هذا القانون ، وتحكم المحكمة من تلقاء نفسها بإلزامه بأن يرد إلى المؤمن عليهم قيمة ما تحملوه من نفقات التأمين .
وتضاعف الغرامة فى حالة العود .$m254$,'a324c1abd3e2d47827f1f74fb2fcd5a5',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(169,0,1,$m254$يعاقب بالحبس مدة لا تقل عن ستة أشهر ، وبغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه ، أو بإحدى هاتين العقوبتين ، كل من أفشى من موظفى الهيئة سرا من أسرار الصناعة أو المهنة أو العمل أو غير ذلك من أساليب العمل أو مكن أو سمح أو ساعد أو سهل للغير ، بطريق مباشر أو غير مباشر ، الاطلاع على سر من هذه الأسرار التى يكون قد اطلع عليها بحكم المادة ( 143 ) من هذا القانون أو ساعد صاحب العمل على التهرب من الوفاء بالتزاماته المقررة فى هذا القانون .
وتقضى المحكمة من تلقاء نفسها بعزله من وظيفته .$m254$,'e1a4a39ada059e153a8c215989717da6',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(170,0,1,$m254$يعاد النظر فى قيمة الغرامات الواردة فى هذا الباب كل عشر سنوات من تاريخ العمل بأحكام هذا القانون .$m254$,'9e614e0c2f1e06b482be3e5f7b4e5fe2',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$),
(1,-2,1,$m254$جدول رقم ( 1 ) أمراض المهنة
1 - الأمراض المهنية الناتجة عن التعرض لعوامل ناتجة عن النشاط المهنى :
0101 عوامل كيميائية .
0102 عوامل فيزيائية .
0103 عوامل حيوية .
0101 الأمراض المهنية الناتجة عن التعرض للعوامل الكيميائية :
الرمز | العامل المسبب | الأعمال والمهن
010101 | التسمم بالرصاص أو مركباته ومضاعفاته | أى عمل يستدعى استعمال أو تداول الرصاص أو مركباته أو المواد المحتوية عليه . ويشمل ذلك : - تداول الخامات المحتوية على الرصاص . - صب الرصاص القديم والزنك القديم ( الخردة ) فى سبائك . - العمل فى صناعة الأدوات من سبائك الرصاص أو الرصاص القديم ( الخردة ) . - العمل فى صناعة مركبات الرصاص ، صهر الرصاص . - تحضير واستعمال ميناء الخزف المحتوية على رصاص . - التلميع بواسطة برادة الرصاص أو المساحيق المحتوية على الرصاص . - تحضير أو استعمال البويات أو الألوان أو الدهانات المحتوية على الرصاص ... إلخ . - وكذا أى عمل يستدعى التعرض لغبار أو أبخرة الرصاص أو مركباته أو المواد المحتوية عليه .
010102 | التسمم بالزئبق أو مركباته ومضاعفاته | أى عمل يستدعى استعمال أو تداول الزئبق أو مركباته والمواد المحتوية عليه وكذا أى عمل يستدعى التعرض لغبار أو أبخرة الزئبق أو مركباتها أو المواد المحتوية عليه . ويشمل ذلك : - العمل فى صناعة مركبات الزئبق وصناعة آلات المعامل والمقاييس الزئبقية ، وتحضير المادة الخام فى صناعة القبعات وعمليات التذهيب واستخراج الذهب ، وصناعة المفرقعات الزئبقية ... إلخ .
010103 | التسمم بالزرنيخ أو مركباته ومضاعفاته | أى عمل يستدعى استعمال أو تداول الزرنيخ أو مركباته أو المواد المحتوية عليه وكذا أى عمل يستدعى التعرض لغبار أو أبخرة الزرنيخ أو مركباته أو المواد المحتوية عليه . ويشمل ذلك : العمليات التى يتولد فيها الزرنيخ أو مركباته وكذلك العمل فى إنتاج أو صناعة الزرنيخ أو مركباته .
010104 | التسمم بالأنتيمون أو مركباته ومضاعفاته | أى عمل يستدعى استعمال أو تداول الأنتيمون أو مركباته أو المواد المحتوية عليه ، وكذا أى عمل يستدعى التعرض لغبار أو أبخرة الأنتيمون أو مركباته أو المواد المحتوية عليه .
010105 | التسمم بالفسفور أو مركباته ومضاعفاته | أى عمل يستدعى استعمال أو تداول الفسفور أو مركباته أو المواد المحتوية عليه ، وكذا أى عمل يستدعى التعرض لغبار أو أبخرة الفسفور أو مركباته أو المواد المحتوية عليه .
010106 | التسمم بالبترول أو مثيلاته أو مركباته الأميدية أو الأزوتية أو مشتقاتها ومضاعفات ذلك التسمم . | كل عمل يستدعى استعمال أو تداول هذه المواد وكذا كل عمل يستدعى التعرض لأبخرتها أو غبارها .
010107 | التسمم بالمنجنيز أو مركباته ومضاعفاته | - كل عمل يستدعى استعمال أو تداول المنجنيز أو مركباته أو المواد المحتوية عليه - وكذا كل عمل يستدعى التعرض لأبخرة أو غبار المنجنيز أو مركباته أو المواد المحتوية عليه ويشمل ذلك : - العمل فى استخراج أو تحضير المنجنيز أو مركباته وصحنها وتعبئتها ... إلخ .
010108 | التسمم بالكبريت أو مركباته ومضاعفاته | كل عمل يستدعى استعمال أو تداول الكبريت أو مركباته أو المواد المحتوية عليه ، وكذا كل عمل يستدعى التعرض لأبخرة أو غبار أكسيد الكبريت أو مركباته أو المواد المحتوية عليه .
010109 | التأثر بالكروم أو مركباته وما ينشأ عنه من قرح ومضاعفات | كل عمل يستدعى تحضير أو تولد أو استعمال أو تداول الكروم أو حمض الكروميك أو كرومات أو بيكرومات الصوديوم أو البوتاسيوم أو الزنك أو أية مادة تحتوى عليه .
0101010 | التأثر بالنيكل أو مركباته أو ما ينشأ عنه من مضاعفات وقرح | كل عمل يستدعى تحضير أو تولد أو استعمال أو تداول النيكل أو مركباته أو أية مادة تحتوى على النيكل أو مركباته . ويشمل ذلك : التعرض لغبار كربونيل النيكل .
0101011 | التسمم بالبريليوم أو مركباته | أى عمل يستدعى استعمال أو تداول هذا العنصر أو مركباته أو المواد المحتوية عليه .
0101012 | التسمم بالسليليوم أو مركباته | أى عمل يستدعى التعرض لغباره أو أبخرته أو مركباته أو المواد المحتوية عليها .
0101013 | التسمم بالكادميوم أو مركباته ومضاعفاته | أى عمل يستدعى التعرض أو استعمال أو تداول الكادميوم أو مركباته أو المواد المحتوية عليه مثل الطلاء بالكهرباء - صناعة الطائرات والسيارات أو الأجهزة الإلكترونية ، والبويات والبلاستيك ، والبطاريات القلوية وغيرها .
0101014 | أمراض يسببها الألمونيوم أو مركباته | أى عمل يتضمن استنشاق أدخنة الألمونيوم أو مركباته مثل : - عمليات سبك الألمونيوم من خاماته ( الألومنيا أو البوكست ) . - إضافة بودرة الألمونيوم لأنواع الطلاء المقاوم وفى عمليات التبطين والتغليف . - عمليات تصنيع وإنتاج سبائك الألمونيوم والمحركات ومكونات المركبات والطائرات وأطر النوافذ والأسطح وحاويات وأوانى الطعام وكذلك إنتاج الكابلات والأسلاك الكهربائية .
0101015 | أمراض يسببها النحاس أو مركباته | أى عمل يتضمن التعرض لأدخنة النحاس مثل : - سبك وتنقية ولحام النحاس . - تصنيع المنتجات النحاسية أو التى يدخل النحاس فى تركيبها مثل صناعة الكابلات الكهربية . - المهمات والأدوات التى يدخل النحاس فى تركيبها والمستخدمة فى أنشطة التشييد والبناء مثل المواسير والأنابيب والخامات النحاسية . - إنتاج الكيماويات التى يدخل النحاس فى تركيبها مثل كبريتات النحاس السامة .
0101016 | أمراض يسببها القصدير أو مركباته | أى عمل يتضمن التعرض لأدخنة القصدير أو مركباته مثل : - استخلاص القصدير وتنقيته وتشغيله وتصنيعه . - تصنيع سبائك من القصدير مع معادن أخرى . - تصنيع مركبات القصدير مع مواد وعناصر أخرى . - استخدام القصدير فى صناعة أنواع من الزجاج . - استخدام القصدير فى تصنيع بعض مواد اللحام وبعض أنواع العبوات . - تصنيع أنواع من الأصباغ النسيجية . - مركبات القصدير العضوية التى تدخل فى تصنيع بعض أنواع مبيدات الفطريات . - مركبات القصدير التى تدخل فى تصنيع أنواع من البلاستيك ( كمادة تثبيت ) .
0101017 | أمراض يسببها الزنك أو مركباته | أى عمل يتضمن التعرض لأتربة وأدخنة الزنك أو مركباته ، مثل : - استخراج وإنتاج المعدن أو مركباته . - إعادة تصنيع المعدن أو مركباته . - استخراج الخلائط التى يدخل فيها المعدن أو مركباته .
0101018 | التسمم بثنائى كبريتيد الكربون | أى عمل يتضمن التعرض لثنائى كبريتيد الكربون أو مركباته أو أبخرته أو أى مادة يدخل فى تركيبها .
0101019 | التسمم بالكحول ، الجليكول ، الكيتون بأنواعها المختلفة ومضاعفاتها . | أى عمل يستدعى التعرض أو استعمال أو تداول هذه المواد ومركباتها والمواد المحتوية عليها ويشمل ذلك الصباغة والتنظيف والطباعة والحرير الصناعى والجلود والمطاط وغيرها .
0101020 | أمراض يسببها الأمونيا أو مركباتها | أى عمل يتضمن التعرض لأبخرة الأمونيا مثل : إنتاج الأسمدة ، والتخمر العضوى ، الأعمال التى تؤدى إلى إفراز الأمونيا أو انتشارها .
0101021 | أمراض مهنية ناتجة عن التعرض للإيزوسياناتات | الأعمال المعرضة لاستنشاق أو مباشرة الإيزوسياناتات العضوية خاصة : - صناعة واستعمال ملمعات وورنيش متعدد الأوريتان وصناعة الألياف الاصطناعية ، - صناعة رغوة متعدد الأوريتان واستعمالها سائلة ، - صناعة واستعمال الغراء الداخل فى تكوينه متعدد الأوريتان ، - صناعة واستعمال الأدهان المحتوية على الإيزوسياناتات العضوية .
0101022 | أمراض مهنية نتيجة التعرض لبروتينات اللاتكس | أى عمل يتضمن التعرض لبروتينات اللاتكس مثل : - تحضير واستعمال ومباشرة المطاط الطبيعى ( اللاتكس ) والمواد التى تحتويه خاصة : - إنتاج ومعالجة اللاتكس الطبيعى ، - صناعة واستعمال أدوات من المطاط الطبيعى . - المنتجات التى تحتوى على المطاط مثل ( القفازات - مقابض الدراجات - المطاط فى أماكن الرعاية الصحية ) .
0101023 | التسمم بالغازات الخانقة مثل أول أكسيد الكربون ، كبريتيد الهيدروجين ، سيانيد الهيدروجين ، ومشتقاتها السامة | المهن التى يتم فيها التعرض لهذه الغازات خصوصا الصرف الصحى .
0101024 | التسمم بحامض السيانور ومركباته وما ينشأ عن ذلك من مضاعفات | كل عمل يستدعى تغيير استعمال أو تداول حامض السيانور أو مركباته ، وكذا كل عمل يستدعى التعرض لأبخرة أو رذاذ الحامض أو مركباته أو أتربتها أو المواد المحتوية عليها .
0101025 | التسمم بالكلور والفلور والبروم ومركباتها | كل عمل يستدعى تحضير أو استعمال أو تداول الكلور أو الفلور أو البروم أو مركباتها ، وكذا أى عمل يستدعى التعرض لتلك المواد أو لأبخرتها أو غبارها .
0101026 | التسمم بالبترول أو غازاته أو مشتقاته ومضاعفاته | كل عمل يستدعى تداولا واستعمال البترول أو غازاته أو مشتقاته ، وكذا أى عمل يستدعى التعرض لتلك المواد ، صلبة كانت أو سائلة أو غازية .
0101027 | التسمم بالكلوروفورم ورابع كلورور الكربون | أى عمل يستدعى استعمال أو تداول الكلوروفورم أو رابع كلورور الكربون ، وكذا أى عمل يستدعى التعرض لأبخرتها أو الأبخرة المحتوية عليها .
0101028 | أمراض تسببها المذيبات العضوية متضمنة الهكسان | أى عمل يتضمن التعرض لأبخرة المذيبات العضوية والهكسان مثل : - إنتاج واستخلاص وصنع واستخدام خلائط يدخل فيها المذيبات العضوية أو الهكسان . - تداول وتخزين والتخلص من مخلفات المذيبات العضوية أو الهكسان .
0101029 | أمراض يسببها رابع كلوروالإثيلين ، ثالث كلوروالأثيلين ، ثانى كلوريد الميتان ( كلوريد الميتيلان ) ثالث كلوريد الميتان ( كلوروفورم ) / ثالث بروموميتان ( بروموفورم ) / ثانى كلور 1-2 الإيتيلان / ثانى بروم 1-2 الإيتاين / ثالث كلور 1-1-1 الإيتان ( ميتيكلورفورم ) / ثانى كلور 1-1 الإيتيلان ( ثانى كلور الإيتيلان ) / ثالث كلور الإيتيلان / رابع كلور الإيتيلان / ثانى كلور 1-2 البروبيلان / كلور البروبيان ( كلوريد الأليل ) / كلور 2 - بوتاديان - 3 ( كلوربران ) والمشتقات الهالوجينية الأخرى للمركبات الهيدروكربونية من المجموعة الأليفاتية والعطرية . | أى عمل يستدعى استعمال أو تداول هذه المواد والتعرض لأبخرتها أو الأبخرة المحتوية عليها .
0101030 | التسمم بالنترات والنتريتات والنيتروجلسرين والأملاح العضوية الأخرى لحامض النيتريك . | أى عمل يستدعى استعمال أو تداول هذه المواد والتعرض لأبخرتها أو الأبخرة المحتوية عليها .
0101031 | أمراض يسببها الأكريلاميد والأكريلونيتريل . | أى عمل يتطلب التعامل مع الأكريلاميد والأكريلونيتريل مثل : - تخليق ( إنتاج ) الأكريلاميد المتعدد Polyacrylamide وبعض الكيماويات العضوية . - معامل الأسنان والأجهزة التعويضية . - صناعة الورق . - عمليات تشغيل الخامات المعدنية والأصباغ ومواد اللصق . - عمليات استعادة الزيت فى صناعة الزيوت . - كيماويات البناء . - عمليات تخليق ( إنتاج ) المركبات البوليمرية للأكريليك فى صناعة المنسوجات . - تصنيع المطاط الذى يدخل فيه مركبات الإستيرين والبيوتاديين . - صناعة البلاستيك والأكريلونيترايد . - صناعة المدخنات Fumigants .
0101032 | التسمم بمبيدات الآفات | أى عمل يستدعى استعمال أو تداول أو تصنيع هذه المواد وكذلك أى عمل يستدعى التعرض لها .
0101033 | أمراض تسببها المواد الصيدلانية | صناعة وتحضير وتجهيز المواد والمركبات الصيدلانية مثل : - المضادات الحيوية ومركبات السلفا والمركبات المطهرة . - أدوية علاج السرطان المضادة للأورام . - الأدوية المخدرة مثل المورفين ومشتقاته ، والمركبات المهدئة ، والمواد المستخدمة فى التخدير وفى الإنعاش . - المركبات المسيلة للدم . - مركبات النيتروجلسرين العلاجية .
0101034 | الأعراض والأمراض الباثولوجية التى تنشأ عن الهرمونات ومشتقاتها | كل عمل يستدعى التعرض لتأثير الهرمونات أو المشتقات الهرمونية .
2-1- الأمراض المهنية الناتجة عن التعرض للعوامل الفيزيائية :
الرمز | العامل المسبب | الأعمال والمهن
010201 | الصمم المهنى | العمل فى الصناعات أو الأعمال التى يتعرض فيها العمال لتأثير الضوضاء أو العقاقير والكيماويات التى تؤثر على السمع .
010202 | الأعراض والعلامات الباثولوجية بالأطراف العليا الناتجة عن الاهتزازات الموضوعية ( vibrating whie finger ) | أى عمل يستدعى التعرض للاهتزازات بالأطراف خاصة إذا كان يصاحبه برودة فى أعمال الحفر والتخريم والمسابك والمناجم والمحاجر والصناعات الثقيلة وغيرها .
010203 | الأمراض التى تنشأ عن التعرض لدرجات الحرارة أو البرودة الشديدة . | الأعمال التى تتطلب التعرض لحرارة عالية أو برودة شديدة مثل : العمل فى ثلاجات حفظ الأطعمة ، ... إلخ .
010204 | الأعراض والأمراض الباثولوجية الناتجة عن التعرض للراديوم أو المواد ذات النشاط الإشعاعى أو أشعة إكس . | أى عمل يستدعى التعرض للراديوم أو أشعة إكس أو أية مادة أخرى ذات نشاط إشعاعى .
010205 | الأمراض الناتجة عن الإشعاعات غير المؤينة مثل : - الأشعة فوق البنفسجية . - الأشعة تحت الحمراء . | أى عمل يستدعى التعرض لهذه الإشعاعات .
010206 | الأعراض والأمراض الناتجة عن التعرض لتغيرات الضغط الجوى . | كل عمل يستدعى التعرض المفاجئ أو العمل تحت ضغط جوى مرتفع أو التخلخل المفاجئ فى الضغط الجوى أو العمل تحت ضغط جوى منخفض لمدد طويلة .
3-1- الأمراض المهنية الناتجة عن التعرض للعوامل الحيوية :
الرمز | العامل المسبب | الأعمال والمهن
010301 | الجمرة الخبيثة - إنثراكس | كل عمل يستدعى الاتصال بحيوانات مصابة بهذا المرض أو تداول رممها أو أجزاء منها أو منتجاتها الخام أو مخلفاتها بما فى ذلك الجلود والحوافر والشعر والقرون وكذلك العمل فى شحن وتفريغ أو نقل البضائع المحتوية على منتجات الحيوانات الخام أو مخلفاتها أو البضائع التى يحتمل أن تكون قد تلوثت بأبواع المرض ( حويصلات المرض ) عن طريق الحيوانات أو فضلاتها .
010302 | السقاوة | كل عمل يستدعى الاتصال بحيوانات مصابة بهذا المرض وتداول رممها أو أجزاء منها .
010303 | الدرن | - العمل فى المستشفيات المخصصة لعلاج هذا المرض . - الأعمال التى يمكن أن تضع العمال فى اتصال مع الحيوانات الحاملة للعصيات الدرنية أو المنجزة فى محلات آوت الحيوانات المصابة وخاصة الأعمال المنجزة فى المسالخ والمجازر وأماكن معالجة لحم الخنزير ومعالجة الكروش أو المصارين فى مؤسسات القصابة ومباشرة أو معالجة الدم والغدد والعظام والقرون والجلود الطرية والعلاج البيطرى . - أعمال المخابر البيولوجية .
010304 | الحمى المالطية ( البروسيلا ) | كل الأعمال التى تستدعى التعامل مع الحيوانات المصابة أو أجزائها أو جثثها أو تداولها .
010305 | التهاب الكبدى الفيروس نوع : بى أو سى | أى عمل يستدعى الاختلاط بدم مصاب أو أحد منتجاته أو مصدر للفيروس مع ضرورة توفر الشروط التالية : - أن يكون العامل غير مصاب بالفيروس قبل الالتحاق بالعمل من واقع الفحص الطبى الأولى قبل العمل . - أن تكون حادثة التعرض موثقة فى وثيقة رسمية . - أن يتم إثبات وجود المرض لدى المريض ناقل العدوى من خلال الفحوصات المخبرية ومعطيات الملف الطبى . - أن تظهر الفحوصات المخبرية للعامل تغير نتيجة الفحص إلى الإيجابية خلال الستة أشهر الموالية لحادثة التعرض .
010306 | فيروس نقص المناعة المكتسبة . | العاملين الذين تتطلب طبيعة عملهم التعرض للدم أو منتجاته أو السوائل الجسمية الأخرى أو الأنسجة لمرضى مصابين بالفيروس مع ضرورة توفر كل الشروط التالية : - أن يكون العامل غير مصاب بالفيروس قبل الالتحاق بالعمل من واقع الفحص الطبى الأولى قبل العمل . - أن تكون حادثة التعرض موثقة فى وثيقة رسمية . - أن يتم إثبات وجود المرض لدى المريض ناقل العدوى من خلال الفحوصات المخبرية ومعطيات الملف الطبى . أن تظهر الفحوصات المخبرية للعامل تغير نتيجة الفحص إلى الإيجابية خلال الستة أشهر الموالية لحادثة التعرض .
010307 | الكزاز | - الأعمال المنجزة فى قنوات الصرف الصحى . - الأعمال الفلاحية وكذلك الأعمال المؤدية إلى الاختلاط بالحيوانات الأليفة وجثثها أو فضلاتها .
010308 | العوامل الحيوية الأخرى المسببة للأمراض المعدية لم يرد ذكرها فى الجداول والتى تم إثبات علاقتها المباشرة بطبيعة النشاط المهنى علميا . | العمل فى منشآت الرعاية الصحية والصرف الصحى والتعامل مع الحيوانات والحشرات والقوارض .
2 - الأمراض المهنية تبعا لوظائف وأجهزة الجسم :
2.1. الأمراض المهنية فى الجهاز التنفسى .
2.2. الأمراض المهنية فى الجلد والأغشية المخاطية .
2.3. الاعتلالات العضلية العظمية الناتجة عن التعرض المهنى .
2.4. الاضطرابات النفسية السلوكية الناتجة عن التعرض المهنى .
2.5. أمراض مهنية أخرى .
1-2- الأمراض المهنية فى الجهاز التنفسى :
الرمز | المرض | الأعمال والمهن
020101 | أمراض الغبار الرئوى ( بنوموكونيوزس ) التى تنشأ عن : - غبار السليكا ( سليكوزس ) . - غبار الأسبستوس ( أسبستوزس ) . | أى عمل يستدعى التعرض لغبار حديث التولد لمادة السليكا أو المواد التى تحتوى على مادة السليكا بنسبة تزيد على 5٪ كالعمل فى المناجم والمحاجر أو نحت الأحجار أو صحنها أو فى صناعة المسنات الحجرية أو تلميع المعادن بالرمل أو أية أعمال أخرى تستدعى نفس التعرض . أى عمل يستدعى التعرض لغبار الأسبستوس وخاصة استخراج ومباشرة ومعالجة خامات وصخور الأسبست ومباشرة واستعمال الأسبست الخام فى العمليات الصناعية التالية : ( الأسبسبت - الإسمنت ، الأسبست - البلاستيك ، الأستبست - النسيج ، الأستبسب - المطاط ، طلاء وصحائف ووصلات من الأسبتسب ، حشو بطائن الاحتكاك تحتوى على الأسبسبت ، منتجات مقبولة أو مواد عازلة محتوية أساسا على الأسبست ) وكذلك أعمال الندف والغزل والنسيج وخياطة المنتجات المحتوية على الأسبست واستعمال وتحطيم وإزالة المواد المحتوية على الإستبست أو الإسبست المقذوف وعزل الحرارة بواسطة مواد الأسبست وأعمال وضع وإزالة العوازل الحرارية المحتوية على الإسبست وأعمال التجهيز والصيانة والحفظ المنجزة بآلات أو فى محلات وتوابع المحلات مكسوة أو محتوية على مواد يدخل الأسبست فى تكوينها والأعمال التى تستوجب عادة حمل ملابس تحتوى على الإسبست .
020102 | أمراض الجهاز التنفسى الناتجة عن التعرض لأغبرة : القطن ( بيسينوسز ) والكتان ، وبودرة التلك ( تلكوزس ) ، وخيوط القنب والسيزال ، والقصب السكرى . | أى عمل يستدعى التعرض لغبار القطن ، وغبار الكتان ، وغبار بودرة التلك ، وغبار خيوط القنب ، وغبار خيوط القصب السكرى وخاصة الأعمال التى تستدعى التعامل مع الألياف بأماكن سيئة التهوية فى أماكن الغزل أو النسيج .
020103 | أزمات ربو بسبب التعرض المهنى للآتى : 1 - الأيزوسينات . 2 - المضادات الحيوية . 3 - الفورما لدهيد . 4 - المنظفات التى يدخل فى تركيبها الخمائر . 5 - غبار الدقيق والحبوب . | أى عمل يتضمن التعرض لمسببات الأزمات الربوية المهنية المذكورة مثل : - استخدام البولى يوريثان فى إنتاج المراتب وحشو الوسائد وصناعة الأسفنج الصناعى ومخلفاتها . - رش ( بخ ) الدهانات والورنيش وصناعة مواد العزل التى تدخل الأيزوسيانات فى تركيبها . أعمال السباكة ( القوالب الرملية ) . استخدام أنهيدريدات الأحماض فى المعالجة الكيمائية لإنتاج الألكيد والبولى إستر والراتنجات الإيبوكسية . رش ( بخ ) الدهانات وصناعة واستخدام المواد الرغوية ( الراتنجات الإيبوكسية ) ومواد الطلاء والتغطية . استخدام الأمينات الأليفاتية فى المعالجة الكيميائية لإنتاج البولى أميدات وتكرير النفط ومعالجة المطاط ورش ( بخ ) الدهانات وتداول المواد الرغوية الراتنجية الإيبوكسية ومواد الطلاء والتغطية . تصنيع وتنقية وتحضير وإعداد وتخزين ( تداول ) الأدوية مثل المضادات الحيوية ومستخلصات الغدد ومصنعاتها والمستحضرات السامة للخلايا والفطائر النشطة ومواد التطهير والتعقيم . العمل فى أنشطة الرعاية الصحية والبيطرية .
020104 | التهاب الحويصلات الرئوية لأسباب حساسية مهنية خارجية المنشأ Extrinsic allergic Alveolitis | أى عمل يتضمن استنشاق أنواع من الأغبرة العضوية أو الأيروسولات الملوثة بالميكروبات والفطريات الموجودة فى أنشطة العمل مثل : كافة الأعمال التى يتعرض فيها العمال إلى استنشاق الأغبرة الناتجة عن تخزين وطحن وتعبئة الحبوب الغذائية . أعمال تربية الطيور وتداول مخلفاتها ( بقاياها ) مثل الريش والزبل . العمليات الزراعية أو الصناعية التى يتعرض فيها العمال إلى أغبرة القش ومصاص القصب ( البجاس ) والتبن . تصنيع وتجهيز الأعلاف المصنعة باستخدام المواد المذكورة أعلاه .
