12 | والد واحد أو والدين وأخ أو أخت أو أكثر | - | - | 1/2 لأيهما أو كليهما بالتساوى | 1/4 لأيهم أو لهم جميعا بالتساوى$m254$,'2fe2dbfb885706f3ea5137206e7d42b7',DATE '2020-01-01',NULL,'active',NULL,NULL,$m254$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 33 مكرر (أ) فى 19 أغسطس 2019 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m254$);

DO $m254$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m254_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m254_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[254] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m254_art) <> 185 OR (SELECT sum(char_length(body)) FROM m254_art) <> 166262 OR (SELECT count(*) FROM m254_ver) <> 185 THEN
    RAISE EXCEPTION '[254] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=148 AND law_year=2019 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%التأمينات الاجتماعية%' THEN
    RAISE EXCEPTION '[254] يوجد مستند آخر برقم 148 لسنة 2019 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (148, 2019, $t254$القانون رقم 148 لسنة 2019 بإصدار قانون التأمينات الاجتماعية والمعاشات (النص الأصلى كما نشر بالجريدة الرسمية)$t254$, $t254$قانون التأمينات الاجتماعية والمعاشات 148/2019$t254$, 'other', 'amended', NULL, DATE '2019-08-19', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m254_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m254_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m254_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 185 THEN
    RAISE EXCEPTION '[254] عدد صفوف النص % بدل 185', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 185 THEN
    RAISE EXCEPTION '[254] عدد نسخ النص % بدل 185', v_vcnt;
  END IF;
  RAISE NOTICE '[254] قانون 148/2019: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m254$;
